export const DOCS = {"geradoEm":"local","comandos":[{"nome":"pedidos","descricao":"Pedidos de ajuda por tratar","quem":"admin, dev, suporte (e master)"},{"nome":"pedido","descricao":"Ver um pedido e agir sobre ele","quem":"admin, dev, suporte (e master)"},{"nome":"responder","descricao":"Responder e marcar como em resolução","quem":"admin, dev, suporte (e master)"},{"nome":"fechar","descricao":"Marcar um pedido como concluído","quem":"admin, dev, suporte (e master)"},{"nome":"erros","descricao":"Erros recentes da aplicação","quem":"dev (e master)"},{"nome":"uso","descricao":"Consumo da infraestrutura agora","quem":"admin (e master)"},{"nome":"comandos","descricao":"O que podes fazer com o teu papel","quem":"admin, dev, suporte (e master)"},{"nome":"entrar","descricao":"Abrir a ferramenta de suporte no browser","quem":"admin, dev, suporte (e master)"},{"nome":"docs","descricao":"Como isto funciona por dentro (gerado do código)","quem":"admin, dev, suporte (e master)"},{"nome":"test","descricao":"Ligação temporária para o ambiente de teste, numa conta lavada","quem":"dev, suporte (e master)"},{"nome":"access","descricao":"Quem pode que comandos (só o master)","quem":"só o master"},{"nome":"copias","descricao":"Cópias da base de dados no R2","quem":"admin (e master)"},{"nome":"resumo","descricao":"Enviar o resumo diário para o canal de administração","quem":"admin (e master)"}],"capitulos":[{"id":"auth","titulo":"Autenticação e conta","itens":[{"nome":"worker/src/auth.js","texto":"Autenticação: hash de palavras-passe (PBKDF2 via WebCrypto) e sessões em KV.","funcoes":[{"nome":"toB64","assinatura":"function toB64(buf)","doc":"Bytes (ArrayBuffer ou typed array) para base64, para guardar hash e salt como texto."},{"nome":"fromB64","assinatura":"function fromB64(b64)","doc":"Inverso de toB64: base64 para Uint8Array."},{"nome":"hashPassword","assinatura":"async function hashPassword(password, saltB64)","doc":"Deriva o hash PBKDF2-SHA256 (100 mil iterações) da palavra-passe. Sem\nsaltB64 gera um salt novo (registo); com ele reusa-o (verificação).\nDevolve { hash, salt } ambos em base64, prontos a guardar."},{"nome":"verifyPassword","assinatura":"async function verifyPassword(password, saltB64, expectedHashB64)","doc":"Confere a palavra-passe contra o hash guardado, comparando em tempo\nconstante para não se poder medir por tempos onde a comparação falhou."},{"nome":"randomToken","assinatura":"function randomToken(bytes 32)","doc":"Token aleatório em hexadecimal (32 bytes por omissão → 64 caracteres, o formato que TOKEN_RE exige)."},{"nome":"newUserId","assinatura":"function newUserId()","doc":"Id curto e legível para partilhar com outros utilizadores (sem 0/O/1/I)."},{"nome":"createSession","assinatura":"async function createSession(env, userId, epoch 0)","doc":"Cria uma sessão em KV (expira ao fim de 30 dias) e devolve o token. O epoch\ngravado é o que permite revogar todas as sessões do utilizador de uma vez."},{"nome":"destroySession","assinatura":"async function destroySession(env, token)","doc":"Apaga a sessão do KV (logout). Tolera token vazio ou já expirado."},{"nome":"sessionCookie","assinatura":"function sessionCookie(token, expire false)","doc":"Valor do Set-Cookie da sessão (HttpOnly, Secure, SameSite=Lax); com\nexpire=true devolve a variante que apaga o cookie, para o logout."},{"nome":"readSessionToken","assinatura":"function readSessionToken(request)","doc":"Extrai o token do pedido: primeiro o cabeçalho Bearer, senão o cookie\ngi_session. Só aceita 64 hexadecimais; tudo o resto devolve null."},{"nome":"getSessionUser","assinatura":"async function getSessionUser(env, request)","doc":"Resolve o pedido num utilizador autenticado: token → sessão em KV → linha\nem users na D1. Devolve null se faltar qualquer elo, se a conta estiver\napagada ou suspensa, ou se o sess_epoch já rodou (sessões revogadas);\ncaso contrário devolve o utilizador com o token anexado."}]},{"nome":"worker/src/oauth.js","texto":"Verificação de ID tokens (JWT RS256) do Google e da Apple, sem dependências:\nvai buscar as chaves públicas (JWKS) do fornecedor, valida a assinatura com\nWebCrypto e confere emissor, audiência e validade.","funcoes":[{"nome":"b64uToBytes","assinatura":"function b64uToBytes(s)","doc":"base64url → bytes: repõe o padding e os carateres +/ do base64 clássico antes do atob."},{"nome":"b64uToJSON","assinatura":"function b64uToJSON(s)","doc":"descodifica um segmento base64url do JWT (cabeçalho ou payload) para objeto"},{"nome":"getKey","assinatura":"async function getKey(provider, kid)","doc":"A chave pública do fornecedor com aquele kid. Cache de uma hora, renovada também\nquando o kid não aparece — é assim que uma rotação de chaves passa sem se dar por ela."},{"nome":"verifyIdToken","assinatura":"async function verifyIdToken(provider, token, audience)","doc":"Valida um ID token de ponta a ponta: assinatura RS256 contra as chaves públicas do\nfornecedor ('google' ou 'apple'), emissor, audiência (o client id da app), validade\ne email confirmado. Devolve o payload quando tudo bate certo; qualquer falha lança\nError com a razão — quem chama decide o que mostrar. Vai à rede buscar as chaves\nquando a cache não chega."}]},{"nome":"worker/src/rotas/auth.js","texto":"Registo, entrada, saida e entrada com Google. Corre antes da sessao.","funcoes":[{"nome":"rotasAuth","assinatura":"async function rotasAuth(c)","doc":"Trata as rotas /api/auth: registo, entrada (email e Google), reposição de\npalavra-passe, configuração pública e saída. Recebe o contexto partilhado do\nworker; devolve uma Response quando a rota é dele e undefined para o pedido\nseguir para as rotas com sessão. Os POST (menos o logout) têm limite por IP."}]},{"nome":"worker/src/rotas/conta.js","texto":"A conta de quem esta ligado: dados, termos, palavra-passe, sessoes e apagar.","funcoes":[{"nome":"rotasConta","assinatura":"async function rotasConta(c)","doc":"As rotas da própria conta: /api/me (ver e apagar), os termos, a\npalavra-passe e as sessões. Tudo aqui chega já autenticado — o `me` vem no\ncontexto. O que mexe em credenciais sobe o sess_epoch, que é o que deita\nabaixo as sessões dos outros aparelhos, e devolve um token novo para este\ncontinuar dentro. Sem rota que sirva não devolve nada, e o worker segue."}]},{"nome":"web/cloud/entrada.js","texto":"Ecras de entrada: sessao, aviso inicial e ligacao com a Google.","funcoes":[{"nome":"setSyncBadge","assinatura":"function setSyncBadge(state)","doc":"Selo fixo no canto superior direito: 'off' mostra o aviso de falta de ligação,\nqualquer outro estado esconde-o. Cria o elemento na primeira chamada."},{"nome":"passProblem","assinatura":"function passProblem(p)","doc":"forte: 8+ caracteres com maiúsculas, minúsculas, números e um símbolo"},{"nome":"showAuth","assinatura":"function showAuth(msg)","doc":"Desenha o ecrã de entrada por cima de tudo — login ou registo, conforme\nCW.showAuthMode — com msg como erro opcional no topo. No registo liga a\nvalidação ao vivo do email e dos requisitos da palavra-passe; no fim tenta\nmontar a entrada social (Google), se estiver configurada."},{"nome":"showAuth","assinatura":"showAuth ()","doc":"a versão pública, sem mensagem de erro — é a que os botões da app chamam"},{"nome":"toggleAuth","assinatura":"toggleAuth ()","doc":"alterna entre \"Entrar\" e \"Criar conta\" e redesenha o ecrã"},{"nome":"finishLogin","assinatura":"function finishLogin(u)","doc":"O fecho de qualquer entrada bem-sucedida (formulário, Google, ligação por\nemail): guarda a sessão, descarta a cache local se pertencia a outra conta,\nvolta à visão geral, mostra os portões legais que faltem e arranca o sync."},{"nome":"submitAuth","assinatura":"submitAuth ()","doc":"Valida o formulário (no registo: palavra-passe forte, confirmação igual e\ntermos aceites) e envia o login ou o registo à API. Os erros ficam escritos\nno próprio ecrã, e o botão desativa-se enquanto o pedido anda."},{"nome":"esqueci","assinatura":"esqueci (e)","doc":"Esqueci-me da palavra-passe: pede a ligação por email e, quando a pessoa\nvolta com o token no endereço, troca-a aqui mesmo. A resposta do servidor\né sempre a mesma, exista a conta ou não."},{"nome":"reporConfirmar","assinatura":"reporConfirmar ()","doc":"Valida a palavra-passe nova e confirma a reposição com o token da ligação de\nemail; se o servidor aceitar, fecha a sobreposição e devolve o ecrã de entrada."},{"nome":"avisoFimDemo","assinatura":"function avisoFimDemo(fim)","doc":"O aviso dos 30 dias: quando o master marca o fim da demonstração, toda a\ngente fica a saber — uma vez por aparelho e por data marcada, com a data\nconcreta e o que muda. É este aviso que os termos prometem."},{"nome":"fimDemoVisto","assinatura":"fimDemoVisto (chave)","doc":"o \"Percebi\" do aviso: marca-o como visto neste aparelho e fecha o modal"},{"nome":"loadScript","assinatura":"function loadScript(src, cb)","doc":"carrega um script externo uma única vez; se já estiver na página, só espera pelo load"},{"nome":"loadSocial","assinatura":"function loadSocial()","doc":"Monta a zona \"ou continua com…\" do ecrã de entrada: pede /api/auth/config\n(fica em cache) e, se houver id do Google, carrega o SDK e desenha o botão.\nSem configuração — ou sem rede — a zona simplesmente não aparece."},{"nome":"socialLogin","assinatura":"function socialLogin(provider, body)","doc":"troca a credencial do fornecedor (ex.: Google) por uma sessão nossa e acaba como um login normal"},{"nome":"hideAuth","assinatura":"function hideAuth()","doc":"esconde o ecrã de entrada e devolve o scroll à página"}]}]},{"id":"sync","titulo":"Sincronização e estado","itens":[{"nome":"worker/src/rotas/sync.js","texto":"Sincronizacao em lote das alteracoes pendentes do cliente.","funcoes":[{"nome":"rotasSync","assinatura":"async function rotasSync(c)","doc":"Rota do POST /api/sync: aplica as operações pendentes do cliente (put/del\nde casas, registos e dados globais) uma a uma, com validação e controlo de\nacesso por operação — uma falha não trava as seguintes. Escreve na D1 e\ndevolve a Response; noutros caminhos não devolve nada, para o encaminhador\ntentar a rota seguinte."}]},{"nome":"worker/src/rotas/estado.js","texto":"O estado completo que este utilizador pode ver, numa so leitura.\n\nRota do GET /api/state: junta numa só resposta tudo o que este utilizador\npode ver — casas, registos, dados globais, conexões, perfis e propostas.\nSó lê da base; noutros caminhos não devolve nada.","funcoes":[{"nome":"rotasEstado","assinatura":"async function rotasEstado(c)","doc":"Rota do GET /api/state: junta numa só resposta tudo o que este utilizador\npode ver — casas, registos, dados globais, conexões, perfis e propostas.\nSó lê da base; noutros caminhos não devolve nada."}]},{"nome":"web/cloud/nucleo.js","texto":"Sessao, sincronizacao com o servidor e reconstrucao dos dados locais.","funcoes":[{"nome":"localTheme","assinatura":"function localTheme()","doc":"Tema guardado neste aparelho; 'auto' se nada houver ou se o localStorage falhar."},{"nome":"applyLocalTheme","assinatura":"function applyLocalTheme()","doc":"Sobrepõe o tema do aparelho ao que estiver em db.settings e aplica-o."},{"nome":"loadSnap","assinatura":"function loadSnap()","doc":"Carrega do aparelho o retrato do servidor (chave -> JSON do que já lá está)."},{"nome":"saveSnap","assinatura":"function saveSnap()","doc":"Guarda o retrato no aparelho; se o localStorage falhar, refaz-se no próximo pull."},{"nome":"api","assinatura":"function api(method, path, data)","doc":"Chamada à API: junta o token da sessão, serializa 'data' em JSON e devolve\na resposta já decomposta. Um 401 fora de /api/auth/ encerra a sessão local\n(sessionLost). Resposta não-ok rejeita com um Error cuja mensagem vem do\nservidor e com .status preenchido."},{"nome":"sessionLost","assinatura":"function sessionLost()","doc":"Deita fora a sessão local e volta ao ecrã de entrada, com aviso de expiração."},{"nome":"strip","assinatura":"function strip(o)","doc":"Cópia profunda sem as chaves de trabalho (as que começam por '_'):\né esta a forma que segue para o servidor."},{"nome":"stripHouse","assinatura":"function stripHouse(p)","doc":"As quotas são geridas pelo servidor (propostas com confirmação): a casa\nexportada nunca as leva, para um cliente desatualizado não as reverter."},{"nome":"exportEntities","assinatura":"function exportEntities()","doc":"Mapa completo do que este utilizador deve ter no servidor.\nchave -> {scope, houseId?, kind?, id?, data}"},{"nome":"parseKey","assinatura":"function parseKey(k)","doc":"Decompõe uma chave do retrato ('h:...', 'r:...', 'u:...') em {scope, houseId?,\nkind?, id?} — o inverso das chaves que exportEntities() constrói."},{"nome":"schedulePush","assinatura":"function schedulePush()","doc":"Agenda um envio daqui a 1,2s, juntando alterações seguidas num só push."},{"nome":"avisoPlano","assinatura":"function avisoPlano(msg)","doc":"Cada aviso de limite do plano aparece uma única vez por sessão (toast de 6s)."},{"nome":"pushNow","assinatura":"function pushNow()","doc":"Envia ao servidor a diferença entre o estado local e o retrato: 'put' do que\nmudou (casas primeiro, que os registos dependem delas) e 'del' do que\ndesapareceu, em lotes de 200. Atualiza o retrato à medida que o servidor\naceita, marca as recusas do plano (402) para não reinsistir e acerta o selo\nde sincronização. Reentrante: se já está a enviar, fica marcado um novo\nenvio para o fim. A Promise devolvida nunca rejeita."},{"nome":"rebuildDb","assinatura":"function rebuildDb(st)","doc":"Reconstrói a base local inteira a partir do estado do servidor: casas com\ndonos e quotas vindas de lá, registos por casa, dados do utilizador e\nperfis — os \"proprietários\" passam a ser os utilizadores com acesso.\nDevolve o db novo, normalizado e filtrado por dropUnsafe; não toca no\ndb global."},{"nome":"applyState","assinatura":"function applyState(st)","doc":"Adota o estado do servidor: substitui o db local, refaz o retrato (o que o\nservidor não tem fica de fora, para o próximo push o enviar; o que só ele\ntem fica marcado para apagar), grava tudo no aparelho e redesenha a app."},{"nome":"pullNow","assinatura":"function pullNow(force)","doc":"Lê o estado do servidor e adota-o. Com um modal aberto não faz nada (para\nnão pisar uma edição a meio), salvo com force. Falhas põem o selo a 'off'."},{"nome":"syncCycle","assinatura":"function syncCycle()","doc":"Um ciclo: envia o que houver e, se a última leitura já passou PULL_MS e\nnada está a ser editado, volta a ler."},{"nome":"startSync","assinatura":"function startSync()","doc":"Arranque da sessão: primeira leitura ao servidor. Se ele está vazio e há\ndados locais deste utilizador (primeira sessão de quem já usava a app sem\nconta), sobem primeiro; caso contrário o servidor manda. Liga o ciclo de\n30s e as sincronizações ao voltar online ou ao regressar à frente."},{"nome":"dropUnsafe","assinatura":"function dropUnsafe(d)","doc":"Deita fora, à entrada, tudo o que tenha id fora do formato que a app gera —\nregistos e sub-listas das casas — e limpa as datas fora do ISO. Altera e\ndevolve o próprio objeto."}]},{"nome":"web/app/dados.js","texto":"","funcoes":[{"nome":"rawGet","assinatura":"function rawGet(k)","doc":"lê do localStorage; se estiver bloqueado (modo privado), vale a cópia em memória desta sessão"},{"nome":"rawSet","assinatura":"function rawSet(k,v)","doc":"escreve no localStorage e numa cópia em memória; se o disco falhar, a app continua só em memória e avisa uma vez"},{"nome":"stampPct","assinatura":"stampPct ()","doc":"taxa do imposto do selo sobre os juros: configurável em Definições, 4% por omissão"},{"nome":"amortFeeRate","assinatura":"function amortFeeRate(l,dateStr)","doc":"comissão de amortização antecipada, conforme a fase da taxa (mista: fixa até fixedYears, variável depois)"},{"nome":"loanAvail","assinatura":"function loanAvail(t,l)","doc":"quanto ainda se pode amortizar nesta prestação: dívida atual + o capital do próprio registo (em edição)"},{"nome":"uid","assinatura":"function uid()","doc":"id único para qualquer registo novo; onde não há crypto.randomUUID, serve data + aleatório"},{"nome":"migrateInline","assinatura":"function migrateInline()","doc":"despacha para o IndexedDB os anexos que o normFile apanhou em base64 e grava os dados já sem eles;\no que já existir lá não é reescrito, e uma falha num ficheiro não trava os outros"},{"nome":"normLoan","assinatura":"function normLoan(l)","doc":"normaliza uma hipoteca: omissões preenchidas, campos extintos (active, taeg, mtic) fora, anexos pelo normFile"},{"nome":"normPerson","assinatura":"function normPerson(p)","doc":"normaliza uma ficha de pessoa (dono ou inquilino): campos em falta ficam vazios, anexos pelo normFile"},{"nome":"normProp","assinatura":"function normProp(p)","doc":"normaliza um imóvel e migra o que mudou entre versões: equity passa a purchase, o crédito único\nvira lista de hipotecas, quartos em texto ganham id, e quotas de donos removidos são descartadas"},{"nome":"normContract","assinatura":"function normContract(c)","doc":"normaliza um contrato: omissões preenchidas; itens do inventário e chaves ganham id próprio"},{"nome":"migrateSettlements","assinatura":"function migrateSettlements(d)","doc":"as liquidações antigas (lista própria) passam a movimentos do tipo \"acerto\""},{"nome":"fillCats","assinatura":"function fillCats(st)","doc":"categorias novas que uma base antiga ainda não tem"},{"nome":"txSnapshot","assinatura":"function txSnapshot(t)","doc":"cópia profunda de um movimento só com os campos que fazem sentido repetir (TX_TPL_KEYS):\né o que os modelos e as recorrências guardam — data e id ficam de fora de propósito"},{"nome":"load","assinatura":"function load()","doc":"lê os dados guardados (ou a versão antiga mais recente que houver), normaliza tudo e faz as\nmigrações maiores: inquilinos com renda passam a contratos, categorias renomeadas são remapeadas\ne as liquidações antigas viram movimentos de acerto; devolve sempre uma base utilizável"},{"nome":"save","assinatura":"function save()","doc":"grava a base inteira no aparelho e reagenda os lembretes no telemóvel"},{"nome":"scheduleReminders","assinatura":"function scheduleReminders()","doc":"reagenda as notificações locais via ponte Android (fora da app instalada não faz nada): espera\n400ms para juntar gravações seguidas numa só chamada e envia até 60 lembretes futuros, por data"}]},{"nome":"web/app/arranque.js","texto":"","funcoes":[{"nome":"seed","assinatura":"function seed()","doc":"EXEMPLO"},{"nome":"topSheet","assinatura":"topSheet ()","doc":"a folha (.sheet) da janela que está por cima, ou null se não há nenhuma aberta"}]},{"nome":"web/app/copias.js","texto":"","funcoes":[{"nome":"bkName","assinatura":"bkName ()","doc":"CÓPIAS"},{"nome":"b64","assinatura":"function b64(s)","doc":"Texto -> base64 passando por UTF-8 (o btoa sozinho rebenta com acentos); devolve '' se tudo falhar."},{"nome":"driveSave","assinatura":"function driveSave()","doc":"Cópia de segurança: serializa a base inteira em JSON e entrega ao seletor de ficheiros do Android ou, no browser, descarrega o .json."},{"nome":"driveOpen","assinatura":"function driveOpen()","doc":"Repor uma cópia: no Android abre o seletor de ficheiros nativo; no browser cai no modal de colar o JSON."},{"nome":"__fileLoaded","assinatura":"__fileLoaded (name,text)","doc":"Chamada pelo lado Android depois de o utilizador escolher um ficheiro: .csv segue para a importação do Splitwise, o resto é tratado como cópia de segurança."},{"nome":"bkPasteBox","assinatura":"function bkPasteBox()","doc":"Modal com textarea para colar o conteúdo de uma cópia de segurança à mão."},{"nome":"bkLoad","assinatura":"function bkLoad(text)","doc":"Repõe uma cópia de segurança: valida o JSON (tem de trazer imóveis e movimentos),\npede confirmação com os totais e só então substitui a base inteira — normalizando\ncada coleção e correndo as migrações, para as cópias de versões antigas continuarem\na abrir. No fim grava, refaz a navegação e re-renderiza tudo."},{"nome":"download","assinatura":"function download(name,mime,content)","doc":"Descarrega \"content\" como ficheiro no browser: cria um <a download> temporário, clica-o e remove-o."},{"nome":"downloadBytes","assinatura":"function downloadBytes(name,mime,bin)","doc":"\"bin\" é uma string em que cada carácter é um byte (o PDF) — não pode passar por UTF-8"},{"nome":"downloadCsv","assinatura":"function downloadCsv()","doc":"Exporta todos os movimentos para CSV (ponto e vírgula, campos entre aspas), com\nas colunas já traduzidas para nomes legíveis — imóvel, quem pagou, inquilinos,\ncategoria. Pensado para abrir diretamente no Excel."},{"nome":"shareReport","assinatura":"function shareReport()","doc":"Partilha o relatório do portefólio por ordem de preferência: folha de partilha do Android, Web Share API, ou cópia para a área de transferência."},{"nome":"wipe","assinatura":"function wipe()","doc":"Apagar tudo: limpa a base local (mantém o tema) após confirmação; com sessão iniciada recusa e aponta as alternativas seguras."}]}]},{"id":"partilha","titulo":"Casas, partilha e ligações","itens":[{"nome":"worker/src/rotas/casas.js","texto":"Casas, quotas, registos de cada casa e dados globais do utilizador.","funcoes":[{"nome":"rotasCasas","assinatura":"async function rotasCasas(c)","doc":"Rotas das casas e do que vive dentro delas: criar/atualizar e apagar uma\ncasa, propor e confirmar a divisão de quotas entre comproprietários, e os\nput/del de registos da casa e de dados globais do utilizador. Escreve na\nD1; devolve a Response da rota que casar com o pedido, ou nada para o\nencaminhador tentar a seguinte."}]},{"nome":"worker/src/rotas/conexoes.js","texto":"Ligacoes entre utilizadores e escolha das casas partilhadas.","funcoes":[{"nome":"rotasConexoes","assinatura":"async function rotasConexoes(c)","doc":"Rotas das conexões: convidar outro utilizador pelo id curto, aceitar o\nconvite, cortar a ligação (leva as partilhas com ela) e escolher que casas\nminhas ficam partilhadas nessa conexão. Devolve a Response da rota que\ncasar com o pedido, ou nada."}]},{"nome":"worker/src/lib/acesso.js","texto":"Quem pode ver e mexer em que casa, e o que acontece quando uma conta\ndesaparece. E aqui que vive a regra de ouro: o me.id vem sempre da\nsessao, nunca do pedido.","funcoes":[{"nome":"canAccessHouse","assinatura":"async function canAccessHouse(env, userId, houseId)","doc":"O dono acede sempre; outro utilizador só se a casa estiver partilhada consigo\nnuma conexão aceite."},{"nome":"participantsOf","assinatura":"async function participantsOf(env, houseId)","doc":"Comproprietários de uma casa: o dono + todos os utilizadores com quem a\ncasa está partilhada através de conexões aceites."},{"nome":"preserveOwnership","assinatura":"function preserveOwnership(existingDataStr, incoming)","doc":"As quotas (ownerIds/ownerShares) são geridas pelo servidor através das\npropostas de divisão: um cliente a gravar a casa nunca as pode alterar."},{"nome":"connectionForUser","assinatura":"async function connectionForUser(env, connId, userId)","doc":"A conexão com este id em que o utilizador participa (convidou ou foi\nconvidado), ou nada — a procura serve logo de verificação de acesso."},{"nome":"purgeAccount","assinatura":"async function purgeAccount(env, uid)","doc":"Apaga tudo o que e do utilizador e deixa a identidade como lapide, para as\nreferencias noutras contas continuarem legiveis sem revelar quem era."}]},{"nome":"web/cloud/partilha.js","texto":"Pagina Conta e partilha: id, ligacoes, seguranca e apagar a conta.","funcoes":[{"nome":"connCard","assinatura":"function connCard(c)","doc":"O cartão de uma ligação a outro utilizador, com os botões certos para o\nestado dela: convite recebido (aceitar/recusar), convite enviado (cancelar)\nou ligação ativa, com a contagem de casas partilhadas em cada sentido."},{"nome":"vCloud","assinatura":"function vCloud()","doc":"O HTML da página \"Conta e partilha\": a conta e o id para dar a outros, o campo\npara adicionar uma ligação, a lista de utilizadores ligados, a segurança e o\napagar da conta. Sem sessão iniciada, mostra apenas o convite para entrar."},{"nome":"vFaq","assinatura":"function vFaq()","doc":"As perguntas que vão chegar de certeza — respondidas antes de chegarem.\nCada resposta aponta o caminho concreto na app, não teoria."}]},{"nome":"web/cloud/utilizadores.js","texto":"Os proprietarios sao os utilizadores: perfil proprio e quotas por proposta.","funcoes":[{"nome":"injectPhoneCountry","assinatura":"function injectPhoneCountry()","doc":"mete um seletor de indicativo de país à frente do campo do telefone no modal de\nperfil, separando o indicativo que já lá estiver escrito do resto do número\n(mexe no DOM: embrulha campo e seletor numa linha flex). Não faz nada se o campo\nnão existir ou se o seletor já tiver sido injetado."},{"nome":"editProfile","assinatura":"editProfile ()","doc":"abre \"O meu perfil\": a ficha de proprietário do próprio utilizador (criada na hora\nse faltar, com nome e email da conta a entrarem nos campos vazios), com o seletor\nde indicativo no telefone. Embrulha o onSave do modal para juntar indicativo e\nnúmero antes de gravar. Sem sessão iniciada, abre antes o ecrã de entrada."},{"nome":"cwOwnersBlock","assinatura":"function cwOwnersBlock()","doc":"HTML da secção \"Proprietários e quota-parte\" do formulário do imóvel, na versão\ncom contas: quotas atuais e, se houver proposta pendente, as novas percentagens\ncom os botões de confirmar/rejeitar (ou cancelar, para quem já confirmou); sem\nproposta, o botão de propor. Com um só dono, apenas explica como partilhar.\nLê o imóvel \"vivo\" da base, não o rascunho do formulário."},{"nome":"refreshPropModal","assinatura":"function refreshPropModal(hid)","doc":"se o modal do imóvel hid estiver aberto, recolhe o que está escrito e repinta-o —\né assim que uma proposta acabada de chegar aparece sem fechar o formulário."},{"nome":"proposeShares","assinatura":"proposeShares (hid, fromShare)","doc":"modal para propor nova divisão de quotas da casa hid: valida que as percentagens\nsomam 100 e envia a proposta para a API — só entra em vigor quando todos os\ncomproprietários confirmarem. Uma divisão igual à atual não gera proposta.\nfromShare ajusta o texto para o caso de a casa ter acabado de ser partilhada;\nno fim segue para a próxima proposta em fila (nextShareProposal)."},{"nome":"answerProposal","assinatura":"answerProposal (hid, accept)","doc":"responde à proposta de divisão pendente da casa hid: com accept confirma (e avisa\nse, sendo o último, a divisão entrou logo em vigor), sem accept rejeita — que\nserve também para quem propôs a cancelar. Fala com a API e atualiza o modal."}]},{"nome":"web/app/splitwise.js","texto":"","funcoes":[{"nome":"swPick","assinatura":"function swPick(input)","doc":"Recebe o ficheiro escolhido no <input type=file>, lê-o como texto e passa-o ao swParse.\nLimpa o input para que escolher o mesmo ficheiro volte a disparar o evento."},{"nome":"swPasteBox","assinatura":"function swPasteBox()","doc":"Alternativa ao seletor de ficheiros: modal com textarea para colar o conteúdo do CSV à mão."},{"nome":"splitDelim","assinatura":"function splitDelim(line)","doc":"Adivinha o separador do CSV pela linha de cabeçalho: conta vírgulas e pontos e vírgula fora de aspas e fica com o mais frequente."},{"nome":"parseCsv","assinatura":"function parseCsv(text,d)","doc":"Leitor de CSV completo: respeita campos entre aspas, aspas escapadas (\"\") e\nfins de linha \\r\\n. Recebe o texto e o separador (d) e devolve as linhas como\narrays de células, já sem as linhas totalmente vazias."},{"nome":"swParse","assinatura":"function swParse(text)","doc":"Ponto de entrada da importação (ficheiro ou colagem): analisa o CSV, guarda cabeçalho e\nlinhas em swHead/swRows e abre o modal de mapeamento. Avisa por toast se não houver nada aproveitável."},{"nome":"findCol","assinatura":"findCol (...names)","doc":"Índice da coluna cujo cabeçalho, reduzido a minúsculas e só letras (a-z e ç), coincide com um dos nomes dados; -1 se nenhum."},{"nome":"swMapModal","assinatura":"function swMapModal()","doc":"Depois de ler o CSV: deteta as colunas de data, descrição, custo e categoria,\nguarda os índices em window._swCols e abre o modal de importação com escolha\nde imóvel, quota-parte e pré-visualização das despesas."},{"nome":"swRefresh","assinatura":"function swRefresh()","doc":"Refaz a pré-visualização (#swPrev) quando o utilizador mexe na quota-parte."},{"nome":"swPrepare","assinatura":"function swPrepare(iDate,iDesc,iCost,iCat,limit,quota)","doc":"Converte as linhas do CSV em despesas prontas a lançar: salta o \"Total balance\"\ne os acertos (\"Payment\"), aplica a quota-parte (%), normaliza a data para ISO\ne traduz a categoria. Pára ao atingir \"limit\" (a pré-visualização usa 100)."},{"nome":"isoDate","assinatura":"function isoDate(s)","doc":"Normaliza \"31/12/2024\", \"2024-12-31\" ou \"31.12.2024\" para AAAA-MM-DD; assume dia primeiro quando o ano vem no fim. Devolve null se não reconhecer."},{"nome":"mapCat","assinatura":"function mapCat(c)","doc":"Traduz a categoria do Splitwise (inglês ou português) para o par [categoria, subcategoria] da app; sem correspondência cai em \"Outros\"."},{"nome":"swPrevHtml","assinatura":"function swPrevHtml(rows)","doc":"HTML da pré-visualização: contagem e total das despesas, mais as primeiras 6 em tabela."},{"nome":"swDo","assinatura":"function swDo(iDate,iDesc,iCost,iCat)","doc":"Executa a importação: guarda a quota nas definições, lança as despesas no imóvel\nescolhido saltando duplicados (mesma data, imóvel, valor e descrição) e marca o\nlote com um id para o undoImport poder anular. Grava e volta a renderizar."},{"nome":"undoImport","assinatura":"function undoImport()","doc":"Anula a última importação: apaga, após confirmação, todos os movimentos do lote mais recente."},{"nome":"HW","assinatura":"HW (function()","doc":"GERADOR DE PDF\nEscritor de PDF mínimo, sem bibliotecas: fontes Helvetica padrão,\ncodificação WinAnsi (cobre todos os acentos portugueses) e quebra de\nlinha calculada com as larguras reais dos glifos."},{"nome":"HWB","assinatura":"HWB (function()","doc":"Larguras dos glifos da Helvetica-Bold — o par negrito da tabela HW acima."},{"nome":"charW","assinatura":"function charW(code,bold)","doc":"Largura de um carácter (milésimos de em) na fonte pedida; acentuados usam a letra base, desconhecidos levam uma largura média."},{"nome":"textW","assinatura":"textW (s,size,bold)","doc":"Largura de uma linha de texto em pontos, para o tamanho e peso dados — é isto que decide as quebras de linha."},{"nome":"pdfEsc","assinatura":"function pdfEsc(s)","doc":"Prepara texto para uma string literal do PDF: converte os símbolos tipográficos\nvia tabela WIN, reduz o resto do não-latin-1 à letra base (ou \"?\") e escapa\nparênteses e barra invertida."},{"nome":"PDF","assinatura":"function PDF()","doc":"Cria um documento A4 e devolve o escritor: text() escreve parágrafos com quebra\nde linha calculada e mudança de página automática, line() faz linhas de tabela,\nphoto() coloca um JPEG com legenda, rule()/gap() separam, e build() devolve o\nficheiro completo como string latin-1 (um carácter = um byte)."},{"nome":"photoJpeg","assinatura":"function photoJpeg(meta,maxPx)","doc":"fotografia guardada em IndexedDB -> JPEG redimensionado, em string de bytes (para o PDF)"}]}]},{"id":"imoveis","titulo":"Imóveis, contratos e pessoas","itens":[{"nome":"web/app/imovel.js","texto":"","funcoes":[{"nome":"propModal","assinatura":"function propModal(id)","doc":"Abre o modal de criar/editar imóvel. Com id, trabalha sobre uma cópia\nprofunda do imóvel (nada muda na base até Guardar); sem id, começa um novo.\nAo guardar valida o nome, escreve em db.properties e repinta a app."},{"nome":"propBody","assinatura":"function propBody()","doc":"Constrói o HTML do formulário do imóvel a partir de pForm: proprietários e\nquotas-partes, destino, quartos, valores, fotos, dados registais, hipotecas\ne anúncio. Só lê — quem escreve de volta é collectProp()."},{"nome":"loanSect","assinatura":"function loanSect(l,i)","doc":"Secção de uma hipoteca no formulário: campos consoante o tipo de taxa,\ncaixa de simulação e documentos. O i serve só para o título por omissão."},{"nome":"collectProp","assinatura":"function collectProp()","doc":"Lê os campos do DOM de volta para pForm. Tolerante a campos ausentes: as\nsecções dobradas podem não estar no DOM e nesses casos ficam os valores\nque lá estavam. Chamar sempre antes de mexer em pForm ou de repintar."},{"nome":"shareHint","assinatura":"function shareHint(owners,custom,sumSh)","doc":"Frase que explica a divisão das quotas-partes: partes iguais, soma 100%,\nrestante para quem não tem percentagem, ou soma diferente normalizada."},{"nome":"liveShares","assinatura":"function liveShares()","doc":"oninput das percentagens: relê o formulário e actualiza a frase das quotas."},{"nome":"repaintProp","assinatura":"function repaintProp()","doc":"Repinta o corpo do modal a partir de pForm (ou do pintor alternativo em\n_propPaint) e volta a carregar as miniaturas das fotos."},{"nome":"setUse","assinatura":"function setUse(u)","doc":"Muda o destino do imóvel (arrendamento/uso próprio) e repinta — os campos\nvisíveis dependem dele."},{"nome":"setMode","assinatura":"function setMode(m)","doc":"Muda o tipo de arrendamento; ao passar a quartos sem nenhum criado, semeia\ndois para a lista não aparecer vazia."},{"nome":"addRoom","assinatura":"function addRoom()","doc":"Acrescenta um quarto com nome sequencial e repinta."},{"nome":"delRoom","assinatura":"function delRoom(rid)","doc":"Tira um quarto do formulário. Se algum contrato apontava para ele, perde já\na ligação em db.contracts (não espera pelo Guardar do imóvel) e avisa."},{"nome":"addLoan","assinatura":"function addLoan()","doc":"Acrescenta uma hipoteca normalizada; a primeira chama-se \"Aquisição\" por\nomissão, as seguintes ficam sem nome até o utilizador dizer a finalidade."},{"nome":"delLoan","assinatura":"function delLoan(lid)","doc":"Apaga uma hipoteca depois de confirmar. Se há prestações registadas, os\nmovimentos ficam mas perdem a ligação (loanId a null); os documentos\nanexados são apagados do IndexedDB de imediato, sem Anular."},{"nome":"loanAddFiles","assinatura":"function loanAddFiles(input,lid)","doc":"Anexa os ficheiros escolhidos no input à hipoteca lid (assíncrono — lê e\nguarda os ficheiros primeiro) e repinta quando estiverem prontos."},{"nome":"delLoanFile","assinatura":"function delLoanFile(fid)","doc":"Remove um documento de qualquer hipoteca que o tenha e apaga o blob do\nIndexedDB."},{"nome":"toggleStamp","assinatura":"function toggleStamp(lid)","doc":"Liga/desliga o imposto do selo de uma hipoteca e refaz a simulação dela."},{"nome":"setLType","assinatura":"function setLType(lid,t)","doc":"Muda o tipo de taxa (fixa/mista/variável) e repinta — cada tipo tem os\nseus campos."},{"nome":"liveLoan","assinatura":"function liveLoan(lid)","doc":"Refaz a caixa de simulação da hipoteca lid sem repintar o resto do\nformulário; sem lid, refaz todas."},{"nome":"liveLoanAll","assinatura":"function liveLoanAll()","doc":"Refaz as caixas de simulação de todas as hipotecas (o select do indexante\nrepinta-se a si próprio, por isso não dá para saber qual mudou)."},{"nome":"loanBox","assinatura":"function loanBox(l)","doc":"HTML da caixa de simulação de uma hipoteca: prestação mensal decomposta em\ncapital, juros e selo, prestação após a fase fixa (mista) e custo total do\ncrédito. Sem capital em dívida ou prazo devolve só a dica do que falta."},{"nome":"propAddPhotos","assinatura":"function propAddPhotos(input)","doc":"Junta as fotos escolhidas no input às do imóvel (assíncrono) e repinta."},{"nome":"photoDrag","assinatura":"function photoDrag(e,h,idx)","doc":"Início do arrasto (pointerdown no puxador): mede o passo entre linhas,\ncaptura o ponteiro e liga os handlers de mover e largar."},{"nome":"photoDragMove","assinatura":"function photoDragMove(e)","doc":"Durante o arrasto: a linha agarrada segue o ponteiro e as outras deslocam-se\npara mostrar onde ela vai cair."},{"nome":"photoDragEnd","assinatura":"function photoDragEnd()","doc":"Largar a foto: limpa os transforms e, se a posição mudou, aplica a nova\nordem a pForm.photos e ajusta o DOM e a etiqueta de capa à mão."},{"nome":"delPropPhoto","assinatura":"function delPropPhoto(fid)","doc":"Tira uma foto do imóvel e apaga o blob e a miniatura do IndexedDB."},{"nome":"addPropOwner","assinatura":"function addPropOwner()","doc":"Abre a lista dos proprietários ainda não associados para escolher um, com\natalho para criar um novo."},{"nome":"delPropOwner","assinatura":"function delPropOwner(oid)","doc":"Desassocia um proprietário do imóvel e esquece a quota-parte dele."},{"nome":"newOwnerFromProp","assinatura":"function newOwnerFromProp()","doc":"Cria um proprietário novo a partir da ficha do imóvel: abre a ficha de\npessoa e, ao gravar, associa-o logo ao imóvel em edição."},{"nome":"propSaver","assinatura":"function propSaver()","doc":"Devolve o handler de gravação do imóvel (para usar como onSave): valida o\nnome, escreve em db.properties e sincroniza os movimentos recorrentes das\nhipotecas antes de fechar e repintar."},{"nome":"delProp","assinatura":"function delProp(id)","doc":"Apaga o imóvel e, em cascata, os contratos e os movimentos associados, com\nAnular. A cópia guarda-se antes de apagar; as fotos e os documentos das\nhipotecas só saem do IndexedDB quando o Anular expira."}]},{"nome":"web/app/contrato.js","texto":"","funcoes":[{"nome":"ctModal","assinatura":"function ctModal(id,pid)","doc":"Abre o modal de criar/editar contrato. Sem id é um contrato novo; pid\npré-escolhe o imóvel (só se for de investimento, senão cai no primeiro\narrendável). Trabalha sobre uma cópia em cForm — nada toca na base até\no guardar. Recusa abrir se não houver imóveis de arrendamento."},{"nome":"ctSaver","assinatura":"function ctSaver()","doc":"Devolve o handler que o modal usa ao guardar: valida imóvel, renda,\ninquilinos e datas, insere ou substitui o contrato em db.contracts,\nsincroniza o movimento recorrente da renda e persiste tudo."},{"nome":"ctBody","assinatura":"function ctBody()","doc":"HTML do formulário do contrato, montado a partir de cForm. Só devolve a\nstring — é o ctModal/repaintCt que a põe no modal e pinta as miniaturas."},{"nome":"netBox","assinatura":"function netBox()","doc":"HTML do resumo bruto → imposto → líquido. Lê os campos do formulário se\njá estiverem no DOM; antes disso usa os valores de cForm."},{"nome":"liveNet","assinatura":"function liveNet()","doc":"Recalcula o resumo da renda líquida enquanto se escreve na renda ou no imposto."},{"nome":"collectCt","assinatura":"function collectCt()","doc":"Copia o que está nos campos do modal para cForm. Chamar SEMPRE antes de\nrepintar ou de mexer nas listas (inventário, chaves, fotos), senão o que\no utilizador escreveu perde-se. Também normaliza os dias de pagamento\n(1–31, o \"até\" nunca antes do \"de\") e as rendas antecipadas (0–36)."},{"nome":"repaintCt","assinatura":"function repaintCt()","doc":"Repinta o corpo do modal a partir de cForm e recarrega as miniaturas das\nfotos. Não recolhe os campos — chama collectCt() antes, se for preciso."},{"nome":"contactSect","assinatura":"function contactSect(kind,c,p)","doc":"contacto: escolher de uma pessoa conhecida, ou escrever outro"},{"nome":"onOwnerContact","assinatura":"function onOwnerContact()","doc":"Ao escolher o contacto do senhorio: copia o email/telefone da pessoa\nescolhida para o contrato e repinta o formulário."},{"nome":"onTenantContact","assinatura":"function onTenantContact()","doc":"Ao escolher o contacto do inquilino: copia o email/telefone da pessoa\nescolhida para o contrato e repinta o formulário."},{"nome":"togCtPhoto","assinatura":"function togCtPhoto(fid)","doc":"Liga/desliga uma foto do imóvel no registo fotográfico do contrato."},{"nome":"allCtPhotos","assinatura":"function allCtPhotos(on)","doc":"Seleciona todas as fotos do imóvel para o contrato (on=1) ou nenhuma (on=0)."},{"nome":"addKey","assinatura":"function addKey()","doc":"Acrescenta uma linha de chave vazia (quantidade 1) e repinta."},{"nome":"delKey","assinatura":"function delKey(kid)","doc":"Remove um tipo de chave pelo id e repinta."},{"nome":"keyToggleAll","assinatura":"function keyToggleAll()","doc":"Marca/desmarca as checkboxes de todas as chaves conforme o \"Selecionar todos\"."},{"nome":"delKeySelected","assinatura":"function delKeySelected()","doc":"Remove as chaves com a checkbox marcada; avisa se nenhuma estiver selecionada."},{"nome":"addKeyBulk","assinatura":"function addKeyBulk()","doc":"Abre um modal com textarea para colar várias chaves de uma vez, uma por\nlinha (\"Nome; quantidade\"). Quem as processa é o doKeyBulk()."},{"nome":"doKeyBulk","assinatura":"function doKeyBulk()","doc":"Lê o textarea do addKeyBulk: uma chave por linha, nome e quantidade\nseparados por ;, | ou tab. Sem quantidade, fica 1."},{"nome":"fillOwnerContact","assinatura":"function fillOwnerContact()","doc":"puxa o contacto do primeiro proprietário, se ainda estiver vazio"},{"nome":"fillTenantContact","assinatura":"function fillTenantContact(tid)","doc":"Preenche o contacto do inquilino do contrato com o da pessoa, mas só os\ncampos ainda vazios — não pisa o que já lá estava."},{"nome":"onCtProp","assinatura":"function onCtProp()","doc":"Ao trocar o imóvel do contrato: limpa o quarto (pertencia ao anterior),\npuxa o contacto do proprietário novo e repinta."},{"nome":"addCtTenant","assinatura":"function addCtTenant()","doc":"Abre o seletor de inquilinos (só os que ainda não estão no contrato); ao\nescolher, junta-o e preenche o contacto do contrato se estiver vazio."},{"nome":"delCtTenant","assinatura":"function delCtTenant(tid)","doc":"Tira um inquilino do contrato — a ficha da pessoa fica intacta."},{"nome":"newTenantFromCt","assinatura":"function newTenantFromCt()","doc":"Cria um inquilino novo sem sair do fluxo do contrato: fecha o seletor,\nabre a ficha de pessoa e, quando esta é guardada, volta ao modal do\ncontrato já com o inquilino adicionado e o contacto preenchido."},{"nome":"addInv","assinatura":"function addInv()","doc":"Acrescenta um artigo vazio ao inventário (quantidade 1, usado) e repinta."},{"nome":"delInv","assinatura":"function delInv(iid)","doc":"Remove um artigo do inventário pelo id e repinta."},{"nome":"invToggleAll","assinatura":"function invToggleAll()","doc":"Marca/desmarca as checkboxes de todos os artigos conforme o \"Selecionar todos\"."},{"nome":"delInvSelected","assinatura":"function delInvSelected()","doc":"Remove os artigos com a checkbox marcada; avisa se nenhum estiver selecionado."},{"nome":"addInvBulk","assinatura":"function addInvBulk()","doc":"Abre um modal com textarea para colar vários artigos de uma vez, um por\nlinha (\"Nome; quantidade; estado\"). Quem os processa é o doInvBulk()."},{"nome":"doInvBulk","assinatura":"function doInvBulk()","doc":"Lê o textarea do addInvBulk: um artigo por linha, campos separados por ;,\n| ou tab. Sem quantidade fica 1; o estado só é \"novo\" se a linha o disser."},{"nome":"ctAddFiles","assinatura":"function ctAddFiles(input)","doc":"Recebe os ficheiros do input de anexos: o conteúdo vai para o IndexedDB\n(takeFiles) e os metadados juntam-se a cForm.files. Assíncrono — repinta no fim."},{"nome":"ctDelFile","assinatura":"function ctDelFile(fid)","doc":"Tira um anexo do contrato e apaga logo o conteúdo do IndexedDB — para o\nficheiro em si não há desfazer."},{"nome":"endContract","assinatura":"function endContract(id)","doc":"Pede confirmação e termina o contrato: fica inativo, ganha data de fim\n(hoje, se não tiver) e o movimento recorrente da renda é desligado."},{"nome":"reactivateContract","assinatura":"function reactivateContract(id)","doc":"Pede confirmação e reativa o contrato: limpa a data de fim e volta a\nligar o movimento recorrente da renda."},{"nome":"delContract","assinatura":"function delContract(id)","doc":"Apaga o contrato, com confirmação: sai da lista, o recorrente automático\nda renda vai com ele e os movimentos ligados ficam órfãos (mantêm-se, mas\nsem contractId). O toast dá para desfazer tudo; os anexos só se apagam do\nIndexedDB quando o desfazer expira sem ser usado."}]},{"nome":"web/app/contrato-pdf.js","texto":"","funcoes":[{"nome":"ext3","assinatura":"function ext3(n)","doc":"Escreve 1–999 por extenso (\"cento e vinte e três\"); devolve '' para zero, para o extenso() ligar os grupos sem restos."},{"nome":"extenso","assinatura":"function extenso(n)","doc":"Número inteiro por extenso até aos milhões, com as ligações certas do português:\n\"mil e cem\", \"duzentos e trinta mil quatrocentos e doze\". Ignora o sinal e a parte decimal."},{"nome":"euroExtenso","assinatura":"function euroExtenso(v)","doc":"Valor em euros por extenso: \"mil duzentos e trinta euros e cinquenta cêntimos\". Arredonda ao cêntimo."},{"nome":"dataLonga","assinatura":"function dataLonga(iso)","doc":"\"2026-03-05\" -> \"5 de março de 2026\"; devolve o valor tal e qual se não vier em ISO."},{"nome":"prazoTexto","assinatura":"function prazoTexto(a,b)","doc":"Duração entre duas datas por extenso: anos certos como \"2 (dois) anos\", o resto em meses arredondados. Sem datas devolve \"prazo certo\"."},{"nome":"generoTexto","assinatura":"function generoTexto(t,g)","doc":"\"Casado(a)\" -> \"casado\" ou \"casada\", conforme o género da ficha"},{"nome":"pessoaTexto","assinatura":"function pessoaTexto(p)","doc":"Frase de identificação de uma pessoa para o contrato: nome em maiúsculas, estado\ncivil ajustado ao género, nacionalidade, nascimento, Cartão de Cidadão, NIF e\nmorada fiscal — só entram os campos preenchidos na ficha."},{"nome":"fullAddress","assinatura":"function fullAddress(p)","doc":"morada completa a partir dos campos registais; se não houver, a morada curta da ficha"},{"nome":"contractData","assinatura":"function contractData(c)","doc":"Constrói o dicionário de marcadores {{...}} do modelo a partir do contrato, do\nimóvel e das fichas das partes: moradas, identificações, valores por extenso,\ndatas longas e o local de assinatura. Um marcador vazio faz o modelo omitir a\nfrase ou a cláusula que o usa."},{"nome":"fillTpl","assinatura":"function fillTpl(str,d)","doc":"Substitui os marcadores {{chave}} pelos valores de d; os blocos {{#chave}}…{{/}} só sobrevivem se a chave tiver valor."},{"nome":"generateContractPdf","assinatura":"async function generateContractPdf(cid)","doc":"Gera e descarrega o PDF do contrato: valida (imóvel e pelo menos um inquilino),\nlê o modelo CONTRACT_XML, preenche os marcadores com contractData e percorre\ncláusulas, secções e anexos a escrever no PDF — incluindo as fotografias\nescolhidas, carregadas do IndexedDB e redimensionadas (daí ser assíncrona).\nNo Android entrega o ficheiro ao seletor nativo em vez de descarregar."},{"nome":"tabela","assinatura":"function tabela(pdf,el,c,p,d,imgs)","doc":"Desenha um elemento <tabela> do modelo: inventário e chaves saem como tabela de\ntexto; a fonte \"fotos\" sai como sequência de fotografias com legenda. Sem dados\nescreve uma nota entre parênteses em vez de deixar o anexo vazio."},{"nome":"assinaturas","assinatura":"function assinaturas(pdf,parte,c,p)","doc":"Blocos de assinatura de uma das partes: linha, nome e papel ajustado ao género (Senhoria/Senhorio, Inquilina/Inquilino), sem quebrar a meio da página."},{"nome":"b64Latin1","assinatura":"function b64Latin1(s)","doc":"o PDF é texto latin-1: converte byte a byte, sem passar por UTF-8"}]},{"nome":"web/app/pessoas.js","texto":"PESSOAS (inquilinos e proprietários)","funcoes":[{"nome":"personModal","assinatura":"function personModal(kind,id,after)","doc":"Abre a ficha de pessoa (kind 'owner' ou 'tenant'); sem id cria uma nova.\nafter, se vier, é chamado com o id da ficha depois de guardar, em vez do\nfecho normal — é assim que o contrato cria um inquilino sem perder o fluxo."},{"nome":"personBody","assinatura":"function personBody()","doc":"HTML do formulário da ficha, montado a partir de perForm. Proprietários\nnão têm a secção de documentos nem as notas."},{"nome":"collectPerson","assinatura":"function collectPerson()","doc":"Copia os campos do modal para perForm. Chamar antes de repintar ou de\nmexer nos documentos, senão perde-se o que o utilizador escreveu."},{"nome":"personAddFiles","assinatura":"function personAddFiles(input)","doc":"Recebe os ficheiros do input de documentos: o conteúdo vai para o IndexedDB\n(takeFiles) e os metadados juntam-se a perForm.files. Assíncrono — repinta no fim."},{"nome":"repaintPerson","assinatura":"function repaintPerson()","doc":"Repinta o corpo do modal a partir de perForm (sem recolher os campos antes)."},{"nome":"delPersonFile","assinatura":"function delPersonFile(fid)","doc":"Tira um documento da ficha e apaga logo o conteúdo do IndexedDB — sem desfazer."},{"nome":"delPerson","assinatura":"function delPerson(kind,id)","doc":"Apaga a ficha, com confirmação: a pessoa sai da lista e o seu id é tirado\ndos imóveis (proprietário) ou contratos (inquilino), que se mantêm. Os\ndocumentos saem já do IndexedDB — aqui não há desfazer."}]},{"nome":"web/app/avaliacao.js","texto":"AVALIAÇÃO","funcoes":[{"nome":"vReports","assinatura":"function vReports()","doc":"AVALIAÇÃO"},{"nome":"onRepSel","assinatura":"function onRepSel()","doc":"aplica o imóvel (ou grupo) escolhido no seletor e volta a desenhar"},{"nome":"portCard","assinatura":"function portCard(pid)","doc":"agregado de todo o portefólio (no âmbito do filtro de proprietário)"},{"nome":"repCard","assinatura":"function repCard(p)","doc":"O cartão de avaliação de um imóvel: valor introduzido contra valor por rendimento,\ncontratos ativos, gráficos do ano, conta de exploração, indicadores e — havendo\nhipotecas — a projeção da dívida até ao fim. Devolve o HTML do cartão."},{"nome":"evoValuation","assinatura":"function evoValuation(p,what)","doc":"avaliação por rendimento ano a ano (histórico) e equity projetado com a amortização"},{"nome":"reportText","assinatura":"function reportText()","doc":"A avaliação em texto simples, para partilhar ou copiar: totais do portefólio,\ncontas entre proprietários e cada imóvel com os seus contratos. Respeita o filtro de proprietário."}]}]},{"id":"movimentos","titulo":"Movimentos e seleção em massa","itens":[{"nome":"web/app/movimento.js","texto":"","funcoes":[{"nome":"txModal","assinatura":"function txModal(id,kind,propId,_x,ctId,preset)","doc":"preset: valores iniciais (vindos dos filtros ou de um botão \"Pagar\")"},{"nome":"prefill","assinatura":"function prefill()","doc":"Afina o tForm depois de mudar o imóvel ou o tipo: limpa quem paga/recebe se já não for dono,\nescolhe a hipoteca viva por defeito e, se o montante ainda estiver vazio, sugere valor e\ndescrição a partir da renda do contrato ou da prestação da hipoteca. As sugestões ficam\nmarcadas em _aA/_aL para o keepTyped as distinguir do que o utilizador escreveu."},{"nome":"keepTyped","assinatura":"function keepTyped()","doc":"Antes de repintar por causa de uma mudança: guarda o que está no DOM e esvazia\ndescrição/montante se ainda forem as sugestões automáticas — o que foi escrito à mão fica."},{"nome":"txBody","assinatura":"function txBody()","doc":"Monta o HTML do formulário do movimento a partir do tForm. Os campos variam com o tipo\n(contrato nas rendas, hipoteca e distribuição nos créditos, credor nas dívidas a terceiros,\nquem paga/recebe nos acertos) e com o contexto (modelo, recorrência, grupo de imóveis).\nSó devolve a string; quem a põe no DOM é o openModal ou o repaintTx."},{"nome":"credHint","assinatura":"function credHint()","doc":"Texto por baixo do campo do credor: o saldo corrente com essa pessoa\n(recebido, devolvido, o que falta) ou uma orientação se ainda não há registos."},{"nome":"refreshCredHint","assinatura":"function refreshCredHint()","doc":"Ao escrever o nome do credor: atualiza tForm.creditor e repinta só a dica do saldo."},{"nome":"splitSect","assinatura":"function splitSect(ows)","doc":"divisão entre proprietários: quotas, percentagem, valor certo ou ajuste"},{"nome":"splitHint","assinatura":"function splitHint(ows)","doc":"Dica por baixo da divisão entre proprietários: explica o modo escolhido, avisa quando\nas contas não batem certo (falta, excesso, percentagens fora dos 100) e mostra quanto\ncalha a cada um com o montante atual. ows: os proprietários do imóvel, já resolvidos."},{"nome":"splitError","assinatura":"function splitError()","doc":"Valida a divisão entre proprietários antes de guardar: devolve a mensagem de erro,\nou '' se está tudo certo (quotas e partes iguais nunca falham)."},{"nome":"collectSplit","assinatura":"function collectSplit()","doc":"Lê do DOM o modo e os valores da divisão entre proprietários para tForm.split.\n'quota' é o comportamento por omissão, por isso guarda-se como null."},{"nome":"psplitSect","assinatura":"function psplitSect()","doc":"Secção \"Divisão entre imóveis\" dos movimentos de grupo: escolha do modo e,\nquando o modo pede valores, um campo por imóvel. Devolve o HTML do fold."},{"nome":"psplitHint","assinatura":"function psplitHint()","doc":"Dica da divisão entre imóveis: explica o modo, avisa somas que não batem certo\ne mostra quanto fica para cada imóvel do grupo."},{"nome":"psplitError","assinatura":"function psplitError()","doc":"Valida a divisão entre imóveis: devolve a mensagem de erro ou '' se ok.\nSó se aplica a movimentos de grupo com dois ou mais imóveis."},{"nome":"collectPsplit","assinatura":"function collectPsplit()","doc":"Lê do DOM o modo e os valores por imóvel para tForm.psplit (fora de um grupo fica null)."},{"nome":"onPsplitSel","assinatura":"function onPsplitSel()","doc":"Mudou o modo da divisão entre imóveis: guarda o formulário e repinta para mostrar ou esconder os campos."},{"nome":"refreshPsplit","assinatura":"function refreshPsplit()","doc":"Ao escrever num valor por imóvel: recolhe e atualiza só a dica, sem repintar o resto do modal."},{"nome":"setSplitMode","assinatura":"function setSplitMode(m)","doc":"Muda o modo da divisão entre proprietários e repinta; 'quota' é o defeito e guarda-se como split=null."},{"nome":"onSplitSel","assinatura":"function onSplitSel()","doc":"Aplica o modo escolhido no select da divisão entre proprietários."},{"nome":"refreshSplit","assinatura":"function refreshSplit()","doc":"Ao escrever num valor da divisão entre proprietários: recolhe e atualiza só a dica com os novos montantes."},{"nome":"loanHint","assinatura":"function loanHint()","doc":"Cartão da distribuição de um pagamento de crédito: o seletor prestação/amortização e,\nconforme o tipo, capital+comissão ou juros editáveis com selo derivado e capital como resto.\nAtenção: além de devolver HTML, escreve interest/stamp/principal/fee no tForm —\né aqui que a distribuição sugerida passa a fazer parte do formulário."},{"nome":"loanLeftTxt","assinatura":"function loanLeftTxt(l,int,st,cap,fee,amt,avail)","doc":"Linha por baixo da distribuição: quanto fica em dívida depois deste pagamento,\nou o aviso quando o capital passa o que falta ou a soma não bate com o montante."},{"nome":"setPayType","assinatura":"function setPayType(v)","doc":"Alterna entre prestação e amortização: deita fora a distribuição editada à mão e recalcula a sugerida."},{"nome":"calcLoanTotal","assinatura":"function calcLoanTotal()","doc":"prestação calculada na hipoteca para o movimento atual (null se não for uma prestação)"},{"nome":"amtResetSync","assinatura":"function amtResetSync()","doc":"Mostra o botão \"Repor\" ao lado do montante só quando o que está escrito\ndifere da prestação calculada na hipoteca."},{"nome":"onAmtReset","assinatura":"function onAmtReset()","doc":"Botão \"Repor\" do montante: volta a pôr a prestação calculada e refresca distribuição e divisões."},{"nome":"onLoanReset","assinatura":"function onLoanReset()","doc":"Botão \"Repor\" da distribuição: descarta os juros/capital editados à mão e volta\nao calculado na hipoteca — incluindo o próprio montante da prestação."},{"nome":"onLoanSplit","assinatura":"function onLoanSplit(w)","doc":"editar juros ou capital numa prestação: o total mantém-se no montante e o selo deriva dos juros"},{"nome":"refreshLoanHint","assinatura":"function refreshLoanHint()","doc":"Repinta o cartão da distribuição do crédito e sincroniza o botão \"Repor\" do montante."},{"nome":"repaintTx","assinatura":"function repaintTx()","doc":"Reconstrói o corpo do modal do movimento a partir do tForm — usa-se depois de qualquer mudança estrutural."},{"nome":"setKind","assinatura":"function setKind(k)","doc":"Muda o tipo do movimento (ex.: dívida recebida ↔ paga): preserva o que foi escrito à mão,\nlimpa categoria/subcategoria se a árvore de categorias do novo tipo for outra,\ne acerta o título do modal quando não é modelo nem recorrência."},{"nome":"onPropChange","assinatura":"function onPropChange()","doc":"Mudou o imóvel (ou grupo, valores \"g:id\"): limpa tudo o que dependia dele — contrato,\nhipoteca, divisões e distribuição — e volta a sugerir valores para o novo contexto."},{"nome":"onCtChange","assinatura":"function onCtChange()","doc":"Mudou o contrato: volta a sugerir a renda e a descrição do contrato escolhido."},{"nome":"onLoanChange","assinatura":"function onLoanChange()","doc":"Mudou a hipoteca: descarta a distribuição anterior e sugere a prestação da nova."},{"nome":"onCatChange","assinatura":"function onCatChange()","doc":"Mudou a categoria: limpa a subcategoria; \"__new__\" abre o prompt para criar uma categoria\nnova na árvore deste tipo de movimento (fica logo gravada nas definições)."},{"nome":"onSubChange","assinatura":"function onSubChange()","doc":"Mudou a subcategoria; \"__new__\" abre o prompt para criar uma nova dentro da categoria atual."},{"nome":"collectTx","assinatura":"function collectTx()","doc":"Recolhe do DOM para o tForm tudo o que estiver presente no modal: campos base, distribuição\nda hipoteca, quem paga/recebe, credor, divisões, categoria e opções de recorrência/modelo.\nCada campo só é lido se existir, porque o formulário varia com o tipo de movimento.\nÉ o passo obrigatório antes de guardar ou repintar — o que não passar por aqui perde-se."},{"nome":"addTxTag","assinatura":"function addTxTag()","doc":"Abre o seletor de etiquetas com as que ainda não estão neste movimento,\ncom atalho para criar uma nova."},{"nome":"newTagFromTx","assinatura":"function newTagFromTx()","doc":"Cria uma etiqueta nova a partir do modal do movimento: entra na lista global\n(Definições → Etiquetas), fica gravada, e aplica-se logo a este movimento."},{"nome":"delTxTag","assinatura":"function delTxTag(g)","doc":"Tira uma etiqueta do movimento e repinta o modal."},{"nome":"applyLoan","assinatura":"function applyLoan(t)","doc":"Efeito do pagamento na hipoteca, na altura de guardar: valida a distribuição do movimento\n(ou recalcula-a quando não bate certo com o montante) e abate o capital ao que está em dívida.\nTambém acerta a recorrência automática da hipoteca — atualiza a prestação, ou apaga-a\nquando o crédito fica liquidado. Mexe na db mas não faz save(); isso é de quem chama."},{"nome":"delTx","assinatura":"function delTx(id)","doc":"Apaga o movimento e, se era um pagamento de crédito, repõe o capital na hipoteca\ne sincroniza a recorrência dela. O toast traz \"Anular\", que desfaz as duas coisas."},{"nome":"yearRows","assinatura":"function yearRows(l)","doc":"Agrega o plano de amortização da hipoteca em linhas anuais (capital, juros, selo,\ntaxa e dívida no fim do ano) e devolve também os totais de juros e selo até ao fim."},{"nome":"amortModal","assinatura":"function amortModal(pid,lid)","doc":"Modal da amortização de um imóvel: com uma hipoteca escolhida, gráfico e tabela ano a ano;\nsem escolha, todas as hipotecas com a linha do total. lid===undefined é a primeira abertura\n(openModal, e escolhe sozinho se só houver uma); com lid vindo do select só troca o conteúdo."},{"nome":"onAmortSel","assinatura":"function onAmortSel()","doc":"Mudou a hipoteca no select do modal da amortização: reconstrói o conteúdo."}]},{"nome":"web/app/planeados.js","texto":"","funcoes":[{"nome":"nextDate","assinatura":"function nextDate(iso,every)","doc":"Data da ocorrência seguinte: soma o período (semana, mês, trimestre ou ano)\nà data dada, prendendo o dia ao último do mês quando ele não existe\n(31 de janeiro + 1 mês dá 28/29 de fevereiro). Devolve AAAA-MM-DD;\ndata inválida devolve hoje."},{"nome":"addDays","assinatura":"addDays (iso,n)","doc":"Soma n dias a uma data AAAA-MM-DD e devolve no mesmo formato."},{"nome":"ctRecOf","assinatura":"function ctRecOf(c)","doc":"a renda de cada contrato ativo vive como movimento recorrente, criado e mantido pela app"},{"nome":"dayInMonth","assinatura":"function dayInMonth(y,m,d)","doc":"Data AAAA-MM-DD para o dia d do mês m (0-11) de y, preso ao último dia desse mês."},{"nome":"syncContractRec","assinatura":"function syncContractRec(c)","doc":"Mantém a recorrência automática da renda de um contrato: cria-a, atualiza-a\nou remove-a conforme o contrato esteja ativo, com renda e com o automático\nligado (autoRec). A janela payDay..payDayTo dá as datas; rendas antecipadas\nadiam a primeira ocorrência. Mexe em db.recurring — quem chama grava."},{"nome":"syncAllContractRecs","assinatura":"function syncAllContractRecs()","doc":"Varre as recorrências automáticas de contratos: apaga as órfãs (o contrato\njá não existe) e sincroniza cada contrato com syncContractRec."},{"nome":"loanRecOf","assinatura":"function loanRecOf(l)","doc":"prestações das hipotecas: recorrência automática, tal como as rendas dos contratos"},{"nome":"syncLoanRec","assinatura":"function syncLoanRec(p,l)","doc":"Mantém a recorrência automática da prestação da hipoteca l do imóvel p:\ncria, atualiza ou remove conforme haja dívida por pagar e o automático\nesteja ligado. O dia de cobrança sai do dia do início do empréstimo\n(limitado a 28) e o valor vem de loanCalc. Mexe em db.recurring — quem\nchama grava."},{"nome":"syncAllLoanRecs","assinatura":"function syncAllLoanRecs()","doc":"Apaga as recorrências automáticas de hipotecas que já não existem e\nsincroniza as das hipotecas vivas, imóvel a imóvel."},{"nome":"recPending","assinatura":"function recPending()","doc":"recorrências vencidas (a data prevista já passou ou é hoje)"},{"nome":"recActive","assinatura":"function recActive()","doc":"silenciada: continua por confirmar em Planeados, mas não avisa nem conta no menu"},{"nome":"recLate","assinatura":"function recLate()","doc":"as vencidas que ainda avisam e cuja janela já fechou — alimenta os alertas de atraso"},{"nome":"recAdvance","assinatura":"function recAdvance(r)","doc":"Avança a recorrência para a ocorrência seguinte (depois de confirmada):\n\"uma só vez\" apaga-se; as outras saltam para a próxima data mantendo a\nlargura da janela next..until. Passado o fim (end), remove-se e avisa.\nTira também o silêncio — confirmar volta a ligar os avisos."},{"nome":"recTx","assinatura":"function recTx(r,date)","doc":"Movimento normalizado a partir do tx da recorrência, datado de 'date' (ou da\ndata prevista). Só constrói: não regista nem toca na recorrência."},{"nome":"quickConfirmRec","assinatura":"function quickConfirmRec(id)","doc":"confirmar sem abrir: cria o movimento na data prevista e passa à seguinte"},{"nome":"skipRec","assinatura":"function skipRec(id)","doc":"Silencia ou reativa a recorrência: silenciada fica em Planeados à espera de\nconfirmação, mas sem avisos nem contagem no menu. Grava e redesenha."},{"nome":"confirmRec","assinatura":"function confirmRec(id)","doc":"abrir para rever antes de confirmar"},{"nome":"editRec","assinatura":"function editRec(id)","doc":"Abre o formulário de movimento carregado com a recorrência, em modo de\nedição: guardar altera a recorrência em vez de criar um movimento."},{"nome":"newRec","assinatura":"function newRec()","doc":"Novo movimento recorrente: pergunta o tipo e abre o formulário já em modo\nrecorrente (mensal por omissão), com a secção de repetição aberta."},{"nome":"newTpl","assinatura":"function newTpl()","doc":"Novo modelo: pergunta o tipo e abre o formulário; guardar cria um modelo\nem vez de registar um movimento."},{"nome":"editTpl","assinatura":"function editTpl(id)","doc":"Abre o formulário carregado com o modelo para o editar (guardar altera o modelo)."},{"nome":"delRec","assinatura":"function delRec(id)","doc":"Apaga a recorrência, com confirmação. Nas automáticas desliga também o\nautoRec no contrato ou na hipoteca de origem — sem isso, a sincronização\nvoltava a criá-la logo a seguir. Os movimentos já registados ficam."},{"nome":"delTpl","assinatura":"function delTpl(id)","doc":"Apaga o modelo, com confirmação; os movimentos criados a partir dele ficam."},{"nome":"applyTemplate","assinatura":"function applyTemplate(x)","doc":"Despeja o tx do modelo no formulário aberto, preservando o que é da sessão\nde edição (id, data e as marcas _rec/_tpl) para não trocar o modo do\nformulário. Redesenha o modal."},{"nome":"newFromTemplate","assinatura":"function newFromTemplate(id)","doc":"Fecha o que estiver aberto e abre um movimento novo pré-preenchido com o modelo."},{"nome":"pendingCard","assinatura":"function pendingCard(all)","doc":"HTML do cartão \"Movimentos por confirmar\". Com all mostra também as\nsilenciadas (é assim que a página Planeados o usa); sem all, só as que\navisam (vista geral). Devolve '' quando não há nada; o aberto/fechado\nvem de pendShut()."},{"nome":"pendShut","assinatura":"function pendShut()","doc":"O cartão está fechado? Verdade por omissão; só o '0' guardado quer dizer \"aberto\"."},{"nome":"pendToggle","assinatura":"function pendToggle()","doc":"Abre/fecha o cartão: guarda a escolha no aparelho e substitui só o cartão\nno DOM (render completo apenas se ele já não existir)."},{"nome":"vRecurring","assinatura":"function vRecurring()","doc":"página das recorrências e modelos"},{"nome":"recSect","assinatura":"function recSect()","doc":"secção do formulário: guardar como modelo e repetir"}]},{"nome":"web/cloud/selecao.js","texto":"Selecionar vários movimentos e tratá-los de uma vez.\n\nO toque longo num movimento passa a entrar em modo de seleção, com esse já\nmarcado. As opções de um movimento sozinho passam para um kebab na própria\nlinha — ficam a um toque em vez de a um toque longo, que ninguém adivinha.\n\nEm seleção há três níveis de marca: cada movimento, cada mês, e um global.\nO global e o do mês acompanham o scroll, senão a meio de uma lista de\nduzentos movimentos deixa de haver como marcar tudo sem voltar ao topo.\n\nEste ficheiro transforma o HTML que o vTransactions devolve, em vez de o\nreescrever. É o mesmo caminho que o painel.js já usava para os cartões da\nvista geral: a vista continua a ser de quem a escreveu, e isto acrescenta.","funcoes":[{"nome":"selEntrar","assinatura":"selEntrar (id)","doc":"Entra em modo de seleção — opcionalmente já com um movimento marcado — e repinta a vista com as caixas."},{"nome":"selReset","assinatura":"selReset ()","doc":"limpa o estado sem repintar: para quem já vai repintar por outra razão"},{"nome":"selSair","assinatura":"selSair ()","doc":"sai da seleção e repinta; o par do selReset, para quando ninguém mais vai repintar"},{"nome":"selToggle","assinatura":"selToggle (id, ev)","doc":"Marcar e desmarcar sem redesenhar a vista toda: numa lista longa, um\nrender() por cada toque numa caixa dava um salto a cada marca."},{"nome":"selMes","assinatura":"selMes (mo, ev)","doc":"Marca ou desmarca um mês inteiro: se já estava todo marcado, limpa-o;\nsenão marca o que faltar. Só conta o que está visível (filtros incluídos)."},{"nome":"selTodos","assinatura":"selTodos (ev)","doc":"como o selMes, mas para todas as linhas visíveis: tudo marcado limpa, senão marca o que falta"},{"nome":"selIdsVisiveis","assinatura":"function selIdsVisiveis()","doc":"os ids de todos os movimentos que a vista mostra neste momento (já com os filtros aplicados)"},{"nome":"selIdsDoMes","assinatura":"function selIdsDoMes(mo)","doc":"os ids visíveis de um mês (\"AAAA-MM\"), lidos das próprias linhas no DOM"},{"nome":"selPintar","assinatura":"function selPintar()","doc":"Repõe as marcas e as contagens a partir do estado, sem redesenhar a vista."},{"nome":"caixa","assinatura":"function caixa(marcada, parcial)","doc":"o HTML da caixa de marcar: cheia, vazia, ou a meio (parcial) com um traço"},{"nome":"txOpcoes","assinatura":"txOpcoes (id)","doc":"O kebab da linha: as opções de um movimento sozinho, mais a porta de entrada na seleção."},{"nome":"patchHdrSel","assinatura":"function patchHdrSel()","doc":"Veste o botão do cabeçalho para a seleção: passa a \"⋯\" (as ações da\nseleção), acende quando há marcas, e ganha um X ao lado para sair. Fora\nda seleção só remove o X — o render normal repõe o resto."},{"nome":"selAcoes","assinatura":"selAcoes ()","doc":"o menu do \"⋯\" do cabeçalho: editar ou eliminar a seleção (avisa se nada estiver marcado)"},{"nome":"selEditar","assinatura":"selEditar ()","doc":"Abre a janela de edição em massa: categoria, subcategoria e etiquetas.\nSó se aplica o que for preenchido — o resto de cada movimento fica como\nestá, e as etiquetas só se acrescentam. O Aplicar é o selGravar."},{"nome":"selCatMudou","assinatura":"selCatMudou ()","doc":"ao mudar a categoria na edição em massa, refaz o menu de subcategorias com as dessa categoria"},{"nome":"selTagToggle","assinatura":"selTagToggle (b)","doc":"liga/desliga uma etiqueta na edição em massa (o estado vive na classe do próprio botão)"},{"nome":"selGravar","assinatura":"selGravar ()","doc":"Aplica a edição em massa aos movimentos marcados e grava na base. Uma\ncategoria nova sem subcategoria escolhida limpa a antiga — ficava a\napontar para a árvore errada. Etiquetas só entram, nunca saem. No fim\nfecha tudo e sai da seleção."},{"nome":"selApagar","assinatura":"selApagar ()","doc":"Elimina os movimentos marcados: a confirmação diz quanto somam, e à saída\nfica um \"Anular\" de seis segundos (comDesfazer) — a cópia é tirada antes\ndo corte e volta inteira se o anular for clicado."}]},{"nome":"web/cloud/selecao-listas.js","texto":"Selecionar vários — imóveis e contratos.\n\nO toque longo passou a ter UM significado na app inteira: selecionar\nvários. Nos movimentos já era assim; aqui ganha o mesmo comportamento\npara as duas listas onde apagar em massa faz sentido — e apagar um\nimóvel arrasta os contratos e movimentos dele, por isso a confirmação\ndiz os números e o Anular repõe tudo.\n\nAs opções de um cartão continuam no kebab. O toque longo deixa de abrir\nmenus em qualquer lado: ou seleciona (onde há seleção) ou não faz nada.","funcoes":[]}]},{"id":"creditos","titulo":"Créditos à habitação","itens":[{"nome":"web/app/credito.js","texto":"","funcoes":[{"nome":"rateAt","assinatura":"function rateAt(l,m)","doc":"CRÉDITO"},{"nome":"loanPaidN","assinatura":"function loanPaidN(l)","doc":"prestações já registadas deste crédito (amortizações antecipadas não contam):\nencurtam o prazo restante e avançam a fase da taxa nas mistas"},{"nome":"amort","assinatura":"function amort(l,maxMonths)","doc":"A tabela de amortização do que falta pagar, mês a mês: devolve\n{rows,totInt,totStamp,n}, cada linha com taxa, prestação, juro, selo,\ncapital e saldo. Desconta as prestações já registadas (encurtam o prazo e\navançam a fase da taxa nas mistas) e recalcula a prestação sempre que a\ntaxa muda. Com maxMonths pára cedo — os totais ficam só até aí."},{"nome":"loanCalc","assinatura":"function loanCalc(l)","doc":"A prestação deste mês, pronta a mostrar: a primeira linha da amortização,\ncomo {base,interest,stamp,principal,total,rate,n} — o total já leva o selo."},{"nome":"rateLabel","assinatura":"function rateLabel(l)","doc":"A taxa em palavras, para as listas: \"fixa X%\", a Euribor com o spread e a\nsoma, ou as duas fases da mista."}]},{"nome":"web/app/creditos.js","texto":"CRÉDITOS (todas as hipotecas)","funcoes":[{"nome":"vCredits","assinatura":"function vCredits()","doc":"CRÉDITOS (todas as hipotecas)"},{"nome":"newMort","assinatura":"function newMort()","doc":"nova hipoteca: escolhe-se primeiro o imóvel (uma hipoteca tem sempre um)"},{"nome":"mortModal","assinatura":"function mortModal(pid,lid)","doc":"editar uma hipoteca num modal próprio, gravando no imóvel"},{"nome":"mortOpen","assinatura":"function mortOpen(lid,isNew)","doc":"Abre o modal da hipoteca `lid` do imóvel já carregado em pForm (newMort e\nmortModal tratam disso primeiro). Liga o repaint ao mortBody, põe o menu de\napagar quando é edição, e define o onSave: numa hipoteca nova sem capital\nem dívida recusa; senão grava o imóvel inteiro na db, sincroniza os\nmovimentos planeados das prestações e fecha."},{"nome":"mortBody","assinatura":"function mortBody(lid)","doc":"O corpo do modal: o formulário da hipoteca `lid` dentro de pForm — o mesmo\nloanSect da ficha do imóvel. É também a função de repaint do modal."},{"nome":"delMortFrom","assinatura":"function delMortFrom(pid,lid)","doc":"Apagar a partir da lista, onde ainda não há pForm: carrega o imóvel e delega no delMort."},{"nome":"delMort","assinatura":"function delMort(lid)","doc":"Apagar a hipoteca `lid` de pForm, com confirmação. As prestações já\nregistadas não se apagam — só lhes tira o loanId, e o aviso diz quantas\nficam assim. Limpa também os anexos dela do IndexedDB antes de gravar o\nimóvel e repintar."}]}]},{"id":"vistas","titulo":"Métricas, gráficos e filtros","itens":[{"nome":"web/app/metricas.js","texto":"","funcoes":[{"nome":"metrics","assinatura":"function metrics(y,pid,opts)","doc":"opts.share: com a vista filtrada por proprietário, cada imóvel entra pela quota-parte dele"},{"nome":"txShare","assinatura":"txShare (t,share)","doc":"fração do movimento que cabe ao proprietário filtrado — só quando se pede share, o filtro é uma\npessoa (não um grupo) e o movimento tem imóvel; nos restantes casos conta por inteiro"},{"nome":"monthly","assinatura":"monthly (y,pid,kind,share)","doc":"total mensal (12 valores, jan–dez) dos movimentos do tipo kind no ano y, pesado pelo\nimóvel ou âmbito atual (txW) e, com share, pela quota do proprietário filtrado"},{"nome":"byCategory","assinatura":"function byCategory(y,pid,share,cat)","doc":"cat: se indicado, devolve as subcategorias dessa categoria"}]},{"nome":"web/app/graficos.js","texto":"","funcoes":[{"nome":"chartTip","assinatura":"function chartTip(e,txt)","doc":"dica interativa: funciona a toque e a rato"},{"nome":"thinLabels","assinatura":"function thinLabels(labels)","doc":"mostra no máximo ~13 etiquetas para não ficarem ilegíveis"},{"nome":"axisY","assinatura":"function axisY(min,max,x0,x1,y0,y1,fmt)","doc":"Grelha e valores do eixo Y: 5 marcas de min a max, formatadas com fmt (ou kfmt).\nDevolve o fragmento SVG que os gráficos de linhas e de barras partilham."},{"nome":"cLine","assinatura":"function cLine(series,labels,o)","doc":"Gráfico de linhas com área sombreada e dica em cada ponto. series=[{name,values,color}],\nlabels no eixo X; o: h (altura), fmt (formatação dos valores, por omissão euro),\narea:false tira o sombreado, marks=[{i,label}] põe linhas verticais de referência.\nSubstitui valores não finitos por 0 (mexe nos arrays recebidos). Devolve HTML pronto\na inserir; com mais de uma série acrescenta a legenda por baixo."},{"nome":"cBars","assinatura":"function cBars(groups,labels,o)","doc":"Barras empilhadas: cada grupo é um array de segmentos {label,value,color}, com os\npositivos a empilhar para cima e os negativos para baixo (rendas contra despesas).\nDevolve HTML; a legenda junta-se a partir das etiquetas que aparecem nos segmentos."},{"nome":"cDonut","assinatura":"function cDonut(items,o)","doc":"Anel de proporções com o total ao centro. items=[{label,value,color}] — valores ≤ 0\nficam de fora. o: center substitui o texto central, sub é a linha pequena por baixo,\nonPick é o nome de uma função global chamada com a etiqueta da fatia (ou da legenda)\nem que se toca. Devolve HTML com a legenda ao lado; \"Sem dados.\" quando o total é zero."},{"nome":"cHBars","assinatura":"function cHBars(items,o)","doc":"Barras horizontais em HTML puro (sem SVG): uma linha por item, com a largura\nproporcional ao maior valor absoluto e os negativos a vermelho. o.fmt formata os valores."},{"nome":"legend","assinatura":"function legend(items,withVal)","doc":"Legenda com bolinha de cor. withVal acrescenta valor e percentagem; itens com \"act\" ficam clicáveis."}]},{"nome":"web/app/vistas.js","texto":"","funcoes":[{"nome":"hdrFiltToggle","assinatura":"function hdrFiltToggle()","doc":"toque no botão de filtros do cabeçalho: abre o painel certo consoante o\nseparador — dropdown nas listas de registos, modal nos movimentos, painel\nde análise nos restantes."},{"nome":"hdrFiltN","assinatura":"function hdrFiltN()","doc":"nº de filtros ativos no separador atual — decide o ponto no botão do cabeçalho"},{"nome":"anaApply","assinatura":"function anaApply()","doc":"fecha o painel de análise do separador atual (os filtros aplicam-se logo ao mexer)"},{"nome":"anaClear","assinatura":"function anaClear()","doc":"limpa o proprietário global e o imóvel em foco do separador de análise onde estamos"},{"nome":"ANA_N","assinatura":"ANA_N ()","doc":"nº de filtros ativos nos separadores de análise: proprietário e imóvel em foco"},{"nome":"anaPanel","assinatura":"function anaPanel(inner)","doc":"embrulha os controlos de análise (inner, já em HTML) no painel dropdown do\ncabeçalho, com os botões Limpar/Fechar; o wrapper tem altura 0 para o\npainel flutuar por cima da página em vez de a empurrar."},{"nome":"tornarFocavel","assinatura":"function tornarFocavel(raiz)","doc":"Cartões e afins são divs com onclick: sem isto, o teclado não chega a\nnenhuma lista — nem um leitor de ecrã os anuncia como acionáveis. Corre\ndepois de cada render e de cada fillModal."},{"nome":"render","assinatura":"function render()","doc":"Redesenha a página inteira: título e subtítulo, botão de filtros do\ncabeçalho, e o HTML da vista do separador atual (vDashboard, vProperties…).\nSubstitui o innerHTML de #view, por isso o estado do DOM anterior perde-se;\nno fim torna os cartões focáveis e repinta as miniaturas dos imóveis."},{"nome":"kpi","assinatura":"kpi (l,v,c,f,why,evo)","doc":"evo: função que devolve a série do indicador ao longo do tempo; ao tocar abre-se uma janela com a evolução"},{"nome":"kpiModal","assinatura":"function kpiModal(id)","doc":"abre a janela de evolução de um KPI: corre o evo() registado no cartão e\nmostra a série mês a mês, a ano a ano e a tabela. Se o evo falhar ou não\ndevolver nada, simplesmente não abre."},{"nome":"yearsWithData","assinatura":"function yearsWithData(pid)","doc":"anos com movimentos (no âmbito), mais o corrente"},{"nome":"evoMoney","assinatura":"function evoMoney(field,pid,fmt)","doc":"série histórica de um campo monetário das métricas (income, op, loan ou cf):\nmês a mês no ano corrente e ano a ano nos anos com movimentos. pid limita a\num imóvel ou grupo; sem fmt, formata em euros."},{"nome":"monthly_","assinatura":"monthly_ (y,pid,kind)","doc":"atalho: totais mensais já na quota-parte do proprietário filtrado"},{"nome":"evoRatio","assinatura":"function evoRatio(field,pid)","doc":"série ano a ano de um rácio, para a janela do KPI. cap e coc saem do\nhistórico real; grossYield e ltv são projeções para a frente — daí o\ntítulo e a nota diferentes que devolve."},{"nome":"card","assinatura":"card (t,s,b)","doc":"cartão genérico das vistas: título, subtítulo opcional e corpo em HTML"},{"nome":"lockPage","assinatura":"function lockPage()","doc":"trava o scroll do fundo enquanto houver um modal ou o menu lateral aberto,\ne repõe a posição ao destravar. Corre a cada abrir/fechar (componentes.js e\nnavegacao.js chamam-na) e é idempotente: só mexe quando o estado muda."},{"nome":"ownerBar","assinatura":"function ownerBar()","doc":"barra com o seletor de proprietário; vazia se não há proprietários registados"},{"nome":"onOwnerFilter","assinatura":"function onOwnerFilter()","doc":"muda o filtro global de proprietário; se o imóvel em foco sair do âmbito, larga-o"},{"nome":"dashBar","assinatura":"function dashBar()","doc":"visão geral: proprietário e imóvel"},{"nome":"onDashProp","assinatura":"function onDashProp()","doc":"muda o imóvel (ou grupo) em foco na visão geral"},{"nome":"vDashboard","assinatura":"function vDashboard()","doc":"Visão geral: KPIs do ano e de rentabilidade (com evolução ao toque),\ngráficos mensais, donut das despesas, resumo do portefólio e saldos entre\nproprietários. Respeita o filtro de proprietário (valores na quota-parte)\ne o imóvel/grupo em foco; devolve o HTML completo da vista."},{"nome":"donutCard","assinatura":"function donutCard()","doc":"o cartão do donut: categorias ao nível de topo, ou as subcategorias de donutCat"},{"nome":"donutDrill","assinatura":"function donutDrill(cat)","doc":"entra numa categoria do donut (ou sai, com cat vazio) repintando só o cartão"},{"nome":"orphanExpenses","assinatura":"function orphanExpenses(y)","doc":"despesas sem imóvel atribuído: contam no total mas não aparecem em nenhuma avaliação"},{"nome":"orphanCard","assinatura":"function orphanCard()","doc":"aviso das despesas sem imóvel na visão geral: explica porque é que os\ntotais divergem da Avaliação e dá o atalho para as ver nos movimentos.\nEscondido quando há filtro de proprietário ou não há órfãs."},{"nome":"balancesCard","assinatura":"function balancesCard(pid)","doc":"cartão reutilizável: saldos entre proprietários (de um imóvel ou de todos)"},{"nome":"settleModal","assinatura":"function settleModal(pid)","doc":"pré-visualização do acerto de contas: lista as transferências que vão ser\nregistadas, imóvel a imóvel, e as últimas liquidações. pid limita a um\nimóvel; null abrange o âmbito todo. Só escreve ao confirmar (doSettle)."},{"nome":"doSettle","assinatura":"function doSettle(pid)","doc":"regista o plano de liquidação como movimentos \"settle\" e grava — os saldos\nentre proprietários ficam a zero. É o passo destrutivo do settleModal."},{"nome":"vProperties","assinatura":"function vProperties()","doc":"Lista de imóveis com pesquisa, filtros (estado, modo de arrendamento,\nproprietário — este espelha o filtro global) e ordenação. Cada cartão\nresume estado, renda, yield, dívida, contratos e hipotecas em curso."},{"nome":"onCtGroupF","assinatura":"function onCtGroupF()","doc":"handler do antigo seletor de grupo ('ctGroupSel'); a vista atual filtra grupos via lfSel, por isso só dispara se esse seletor existir no DOM"},{"nome":"vContracts","assinatura":"function vContracts()","doc":"Contratos agrupados por imóvel, com a renda mensal de cada um no cabeçalho\nda secção. Filtros: imóvel, ativos/terminados, grupo e pesquisa; ordenação\npor nome, renda ou data de início."},{"nome":"ctFMatch","assinatura":"function ctFMatch(c,s)","doc":"um contrato passa nos filtros da lista? imóvel, estado, grupo e pesquisa por texto (nome, inquilinos, IBAN, notas…)"},{"nome":"personCard","assinatura":"function personCard(pp,kind)","doc":"cartão de pessoa para as listas: com kind 'tenant' mostra os contratos\nativos, com 'owner' os imóveis. Ao toque abre a ficha (personModal)."},{"nome":"vTenants","assinatura":"function vTenants()","doc":"Lista de inquilinos, filtrável por com/sem contrato ativo e por pesquisa;\nordenação por nome, nº de contratos ou renda."},{"nome":"vOwners","assinatura":"function vOwners()","doc":"Lista de proprietários, filtrável por imóvel, com/sem imóveis e pesquisa;\nordenação por nome ou nº de imóveis."},{"nome":"txFilterCount","assinatura":"function txFilterCount()","doc":"nº de filtros ativos nos movimentos (a pesquisa não conta: soma-se à parte no cabeçalho)"},{"nome":"txFilterCountSem","assinatura":"function txFilterCountSem()","doc":"a mesma contagem sem as datas; atenção: desligar \"sem pessoa atribuída\" conta como um filtro"},{"nome":"txTerms","assinatura":"function txTerms()","doc":"parte a pesquisa em termos: palavras soltas e frases entre aspas, tudo sem acentos"},{"nome":"txHay","assinatura":"function txHay(t)","doc":"o \"palheiro\" onde a pesquisa procura: rótulo, notas, categorias, etiquetas,\nimóvel, contrato, pessoas, data e valor do movimento, tudo desacentuado."},{"nome":"onTxSearch","assinatura":"function onTxSearch(v)","doc":"pesquisa dos movimentos com atraso de 280 ms para não redesenhar a cada\ntecla; como o render recria o campo, devolve-lhe o foco com o cursor no fim."},{"nome":"txMatch","assinatura":"function txMatch(t)","doc":"um movimento passa em TODOS os filtros ativos? Tipo ('debt' junta owed e\nrepay), imóvel/grupo ('__none__' = sem imóvel; um imóvel apanha também os\nmovimentos de grupo com quota nele), âmbito do proprietário, pessoa que\npagou/recebeu, pesquisa, categoria/subcategoria e intervalo de datas."},{"nome":"filterSummary","assinatura":"function filterSummary()","doc":"descreve os filtros ativos numa linha legível, para o topo da lista e do modal"},{"nome":"newTxFromFilters","assinatura":"function newTxFromFilters(kind)","doc":"um movimento novo assume os filtros ativos; sem filtro, o campo fica vazio"},{"nome":"newTxPick","assinatura":"function newTxPick(after)","doc":"\"Novo movimento\": primeiro o tipo, num menu"},{"nome":"useTemplateNew","assinatura":"function useTemplateNew()","doc":"\"a partir de um modelo\": escolhe um modelo guardado e regista um movimento\ncom base nele; sem modelos, salta logo para criar o primeiro."},{"nome":"newTplForTx","assinatura":"function newTplForTx()","doc":"criar um modelo a meio de “novo movimento”: guarda o modelo E regista o movimento"},{"nome":"txRerender","assinatura":"function txRerender()","doc":"os filtros vivem numa janela por cima da lista: mudar um filtro atualiza a lista e a própria janela"},{"nome":"txFilterBody","assinatura":"function txFilterBody()","doc":"corpo do modal de filtros dos movimentos: pesquisa, tipo, imóvel,\ncategoria/subcategoria, pessoas, datas e ordenação. Cada controlo aplica\nlogo (handlers onTx*), e no fim mostra o resumo e quantos movimentos passam."},{"nome":"onTxSort","assinatura":"function onTxSort()","doc":"muda o campo de ordenação dos movimentos (data ou valor)"},{"nome":"onTxDir","assinatura":"function onTxDir()","doc":"muda o sentido da ordenação dos movimentos"},{"nome":"txFilterFoot","assinatura":"function txFilterFoot()","doc":"rodapé do modal de filtros: Limpar (só quando há filtros) e Fechar"},{"nome":"txFilterModal","assinatura":"function txFilterModal()","doc":"abre o modal de filtros dos movimentos"},{"nome":"onTxProp","assinatura":"function onTxProp()","doc":"muda o filtro de imóvel/grupo dos movimentos"},{"nome":"onTxOwner","assinatura":"function onTxOwner()","doc":"muda o proprietário em foco; o filtro de imóvel cai porque o âmbito mudou"},{"nome":"onTxPaid","assinatura":"function onTxPaid()","doc":"muda o filtro de quem pagou ou recebeu"},{"nome":"onTxCat","assinatura":"function onTxCat()","doc":"muda a categoria; a subcategoria cai porque pertencia à anterior"},{"nome":"onTxSub","assinatura":"function onTxSub()","doc":"muda o filtro de subcategoria"},{"nome":"onTxNoPayer","assinatura":"function onTxNoPayer()","doc":"liga/desliga a inclusão de movimentos sem pessoa atribuída"},{"nome":"onTxDatas","assinatura":"function onTxDatas()","doc":"lê o intervalo de datas do modal e aplica-o à lista"},{"nome":"clearTxFilters","assinatura":"function clearTxFilters()","doc":"repõe todos os filtros dos movimentos na origem, incluindo a pesquisa e o proprietário global"},{"nome":"lfSearch","assinatura":"function lfSearch(k,v)","doc":"pesquisa das listas com atraso de 280 ms para não redesenhar a cada tecla;\ncomo o render recria o campo, devolve-lhe o foco com o cursor no fim."},{"nome":"limparFiltroAtual","assinatura":"function limparFiltroAtual()","doc":"limpa o filtro do separador atual, seja ele qual for — para o botão dos\nestados vazios não ter de saber onde está"},{"nome":"lfClear","assinatura":"function lfClear(k)","doc":"limpa os filtros da lista k sem mexer no painel; nos imóveis larga também o proprietário global"},{"nome":"lfCount","assinatura":"function lfCount(k)","doc":"nº de filtros ativos da lista k — a ordenação (sb/sd) e o estado do painel não contam"},{"nome":"lfHit","assinatura":"function lfHit(k,hay)","doc":"a pesquisa da lista k encontra-se em hay? palavras e frases entre aspas, sem acentos; sem pesquisa passa tudo"},{"nome":"lfSel","assinatura":"function lfSel(k,key,opts)","doc":"Os três painéis de filtro tinham três feitios: rascunho com Aplicar nas\nlistas, aplicação imediata no modal dos movimentos, imediata com um botão\nchamado «Aplicar» nas análises. Fica UM modelo mental: mexes, a lista\nmuda logo atrás; «Limpar» à esquerda, «Fechar» primário à direita, em\ntodo o lado. O rascunho foi-se com a razão de ser dele."},{"nome":"lfToggle","assinatura":"function lfToggle(k)","doc":"abre/fecha o painel de filtros da lista k"},{"nome":"lfApply","assinatura":"function lfApply(k)","doc":"fecha o painel da lista k (os filtros aplicam-se logo ao mexer)"},{"nome":"lfBar","assinatura":"function lfBar(k,sels,found,sorts)","doc":"o dropdown de filtros (aberto pelo botão do cabeçalho) inclui a pesquisa no topo"},{"nome":"lfSort","assinatura":"function lfSort(k,list,keys)","doc":"aplica a ordenação escolhida; sem escolha, mantém a ordem dada"},{"nome":"fab","assinatura":"function fab(actions)","doc":"botão flutuante de adicionar, no canto inferior direito (o espaço no fundo da página é acrescentado no render)"},{"nome":"lfPropOpts","assinatura":"lfPropOpts (withAll)","doc":"opções de imóvel para os seletores das listas: \"Todos os imóveis\" + um por imóvel"},{"nome":"creditorsCard","assinatura":"function creditorsCard(pid)","doc":"dívidas a terceiros: recebido, devolvido e o que falta, com botão para pagar"},{"nome":"vTransactions","assinatura":"function vTransactions()","doc":"Movimentos: KPIs do filtro atual (com evolução ao toque), saldos entre\nproprietários, dívidas a terceiros e a lista agrupada por mês com o saldo\nde cada um. Tudo respeita os filtros e a ordenação escolhidos no modal."},{"nome":"onTxFilter","assinatura":"function onTxFilter()","doc":"muda o filtro de tipo; categoria e subcategoria caem porque a árvore muda com o tipo"},{"nome":"onProjProp","assinatura":"function onProjProp()","doc":"muda o imóvel (ou grupo) em foco nas projeções"},{"nome":"vProjections","assinatura":"function vProjections()","doc":"Projeções ao horizonte definido nas definições (s.years): rendas com o\naumento anual de cada contrato, despesas do ano corrente inflacionadas, e\nprestações segundo o plano de cada hipoteca — param quando o crédito acaba.\nSai em KPIs, gráficos e tabela ano a ano com uma coluna por contrato."},{"nome":"decadeMarks","assinatura":"decadeMarks (y0,n)","doc":"marcas para os gráficos de longo prazo: um traço em cada ano terminado em 0 dentro do horizonte"},{"nome":"setSet","assinatura":"function setSet(k,v)","doc":"escreve uma definição, grava na base e redesenha — usado pelos inputs das definições e das projeções"}]},{"nome":"web/cloud/painel.js","texto":"Visao geral: movimentos por tras dos indicadores, pendentes e ordem dos cartoes.","funcoes":[{"nome":"kpiTxs","assinatura":"function kpiTxs(q)","doc":"mesma regra do metrics(): ano, tipo, fora-dos-totais e peso do imóvel/quota"},{"nome":"openTx","assinatura":"openTx (id)","doc":"abre a ficha de um movimento a partir da lista do indicador — só se ele ainda existir"},{"nome":"kpiToTx","assinatura":"kpiToTx ()","doc":"salta para os Movimentos já com os filtros do indicador aplicados"},{"nome":"backToDash","assinatura":"backToDash (fromModal)","doc":"regressa à visão geral e repõe nos Movimentos os filtros que lá estavam antes do salto"},{"nome":"rejectRec","assinatura":"rejectRec (id)","doc":"Recusar a ocorrência de um planeado: pede confirmação e depois avança o plano\nsem criar movimento nenhum (um \"once\" desaparece de vez). Grava e re-renderiza."},{"nome":"originOf","assinatura":"function originOf(r)","doc":"De onde vem a história: o início do contrato ou da hipoteca. A\nrecorrência criada por eles arranca no mês corrente, por isso os meses\nanteriores não aparecem em lado nenhum."},{"nome":"already","assinatura":"function already(r, d)","doc":"já existe um movimento deste contrato/hipoteca nesse mês?"},{"nome":"missedDates","assinatura":"function missedDates(r)","doc":"As datas do plano que já passaram sem movimento registado, da origem\n(início do contrato ou da hipoteca) até hoje, respeitando o fim do plano.\nO guarda de 600 períodos evita ciclos infinitos com datas estragadas."},{"nome":"fillMissed","assinatura":"fillMissed (id)","doc":"Abre o modal que propõe registar de uma vez os períodos em falta do plano,\ncom o total e o aviso de que é tudo estimativa. Não escreve nada na base —\nisso é o doFillMissed, ao confirmar."},{"nome":"doFillMissed","assinatura":"doFillMissed (id)","doc":"Cria de facto os movimentos em falta, todos com o valor atual do plano e a\netiqueta \"Estimativa\" (que fica registada nas etiquetas das definições). As\nprestações abatem no capital da hipoteca, como se confirmadas uma a uma. No\nfim empurra o plano até à próxima data futura, grava e fecha os modais."},{"nome":"asked","assinatura":"function asked()","doc":"os ids dos planos por que já perguntámos, guardados neste aparelho"},{"nome":"markAsked","assinatura":"function markAsked(ids)","doc":"junta estes ids à lista dos já perguntados (só ficam os últimos 200)"},{"nome":"refreshKnown","assinatura":"function refreshKnown()","doc":"fotografa os planos que existem neste momento, para reconhecer os acabados de criar"},{"nome":"offerFill","assinatura":"function offerFill()","doc":"Corre pouco depois de cada save(): se entretanto apareceu um plano novo com\n2 ou mais períodos em atraso, abre-lhe logo o modal de preenchimento — uma\núnica vez por plano, e nunca por cima de outro modal aberto."},{"nome":"menuOption","assinatura":"function menuOption(opts)","doc":"... e à lista de opções do toque longo numa recorrência\nacrescenta uma opção ao menu de toque longo que acabou de abrir"},{"nome":"txOfProp","assinatura":"txOfProp (pid)","doc":"salta para os Movimentos já filtrados por um imóvel"},{"nome":"pendBlock","assinatura":"function pendBlock(list)","doc":"o HTML da lista \"por confirmar\" que se pendura no cartão de um imóvel ou contrato"},{"nome":"decoratePending","assinatura":"function decoratePending()","doc":"Depois de cada render de Imóveis ou Contratos, acrescenta a cada cartão os\nseus movimentos por confirmar. Mexe no DOM já desenhado, e não duplica o\nbloco se ele já lá estiver."},{"nome":"dashKey","assinatura":"function dashKey(el)","doc":"Chave estável que identifica um bloco da visão geral (título de secção,\nindicador, gráfico…), para a ordem guardada sobreviver a re-renderizações.\nVive do texto visível, porque os blocos não trazem ids próprios."},{"nome":"blkByKey","assinatura":"function blkByKey(k)","doc":"o elemento .cw-blk com esta chave, se estiver no ecrã"},{"nome":"saveDashOrder","assinatura":"function saveDashOrder()","doc":"grava em db.settings.dashOrder2 a ordem em que os blocos estão agora no DOM"},{"nome":"resetDashOrder","assinatura":"resetDashOrder ()","doc":"esquece a ordem personalizada e volta à de origem, redesenhando a vista"},{"nome":"editBar","assinatura":"function editBar()","doc":"insere no topo da vista a barra do modo de edição (repor ordem / concluir), sem duplicar"},{"nome":"patchHdr","assinatura":"function patchHdr()","doc":"em modo de edição, o botão de filtros do cabeçalho passa a dizer \"Concluir\""},{"nome":"enterEdit","assinatura":"enterEdit (key)","doc":"Entra no modo de edição dos cartões (chega-se cá pelo toque longo). Recebe a\nchave do bloco tocado para o arrasto poder começar sem levantar o dedo."},{"nome":"exitEdit","assinatura":"exitEdit (silent)","doc":"sai do modo de edição: solta o arrasto, re-renderiza e avisa com um toast (salvo silent)"},{"nome":"startDrag","assinatura":"function startDrag(el, clientY, clientX)","doc":"começa a arrastar um bloco: marca-o, trava a seleção de texto e liga o scroll automático"},{"nome":"blocks","assinatura":"function blocks()","doc":"os blocos da grelha onde decorre o arrasto (irmãos do que vai na mão)"},{"nome":"shuffle","assinatura":"function shuffle(target, cx, cy)","doc":"troca só quando o centro do cartão segurado entra no espaço do outro\n(ou seja, quando está maioritariamente já na nova posição)"},{"nome":"dragTo","assinatura":"function dragTo(cx, cy)","doc":"Põe o cartão debaixo do dedo e, quando o centro dele entra a sério no espaço\nde outro bloco (ver cobre/ENTRADA acima), troca-os. Também solta o bloqueio\nanti-oscilação assim que o centro sai de cima do último bloco trocado."},{"nome":"passoAuto","assinatura":"function passoAuto()","doc":"Um passo do scroll automático: perto das margens a página desliza (tanto mais\ndepressa quanto mais perto) e o arrasto é reavaliado para o cartão seguir o dedo."},{"nome":"comecarAuto","assinatura":"function comecarAuto()","doc":"Um temporizador e não requestAnimationFrame: o cartão tem de continuar a\nandar com o dedo parado na margem, e um rAF que não dispare (aba sem pintar)\ndeixaria o arrasto preso sem dar sinal."},{"nome":"pararAuto","assinatura":"function pararAuto()","doc":"desliga o temporizador do scroll automático"},{"nome":"endDrag","assinatura":"function endDrag()","doc":"larga o cartão: para o scroll automático, limpa o estado visual e grava a ordem nova"}]},{"nome":"web/cloud/filtros.js","texto":"Faz a lista de imoveis flutuar por cima do painel de filtros, sem cortes.","funcoes":[{"nome":"popAnchor","assinatura":"function popAnchor(pop)","doc":"Prende a lista ao botão em position:fixed, por baixo ou por cima conforme\no espaço que houver no ecrã (a altura fica entre 150 e 340px), e marca-a\ncom data-float para o popRelease saber o que desfazer. Mede o .selbtn\nirmão; sem ele não mexe em nada."},{"nome":"popRelease","assinatura":"function popRelease(pop)","doc":"Desfaz o que o popAnchor pôs — os estilos inline e o data-float. Nas\nlistas que nunca flutuaram não toca."},{"nome":"releaseAll","assinatura":"function releaseAll()","doc":"Solta todas as listas flutuantes que entretanto fecharam; as ainda\nabertas ficam ancoradas onde estão."}]}]},{"id":"ui","titulo":"Componentes e navegação","itens":[{"nome":"web/app/componentes.js","texto":"","funcoes":[{"nome":"sel","assinatura":"function sel(id,value,options,onchange)","doc":"Gera o HTML de um menu de escolha. `id` fica num input escondido, de onde\nval(id) lê o valor; `options` é [{v,label}] (ou {div:true} para uma linha\nseparadora); `onchange` é o NOME de uma função global, chamada quando se\nescolhe. Regista as opções em window.__sel para o selPick as encontrar."},{"nome":"closePops","assinatura":"function closePops(keep)","doc":"fecha os menus abertos, excepto os que contêm \"keep\" (um menu de escolha dentro do menu de filtros\nnão pode fechar o menu que o contém)"},{"nome":"posicaoPop","assinatura":"function posicaoPop(botao, limite, quer, folga)","doc":"Onde cabe um menu que abre a partir de um botão.\n\nDecisão separada da medição de propósito: é geometria pura, e é a parte\nque se pode testar sem um browser. Devolve o lado e, quando não couber\ninteiro, a altura a que tem de encolher.\n\n`quer` é a altura que o menu já tem com o tecto do CSS aplicado. Só se\nencolhe, nunca se cresce: deixar um menu de 16 categorias crescer até ao\nespaço disponível dava-lhe 488px e tomava conta do ecrã."},{"nome":"ajustarPop","assinatura":"function ajustarPop(p)","doc":"Mede o que rodeia o menu e aplica o que o posicaoPop decidir.\n\nSem isto, um menu perto do fundo abria para baixo e ficava cortado pelo\ncorpo do modal — medido: 70% de um dropdown de 16 categorias fora de\nvista, sem qualquer sinal de que faltava ali alguma coisa. O limite é o\nprimeiro antepassado que corta (o corpo do modal, normalmente), ou o ecrã\nquando não há nenhum.\n\nOs menus dentro dos painéis de filtro têm tratamento próprio em\ncloud/filtros.js, que os solta para position:fixed — esses não passam por\naqui com o mesmo efeito, e não há conflito porque esse corre depois."},{"nome":"selOpen","assinatura":"function selOpen(e,id)","doc":"Abre o dropdown de um sel() — ou fecha-o, se já estava aberto. Fecha os\noutros menus primeiro e deixa o ajustarPop virá-lo ou encolhê-lo para caber."},{"nome":"selPick","assinatura":"function selPick(e,id,i)","doc":"Escolha de uma opção: escreve o valor no input escondido, troca o rótulo do\nbotão, fecha o menu e chama o onchange registado (pelo nome, em window) —\né por aí que os formulários reagem à mudança."},{"nome":"menu","assinatura":"function menu(id,items)","doc":"menu de ações (⋯)"},{"nome":"menuOpen","assinatura":"function menuOpen(e,id)","doc":"Abre/fecha o menu de ações (⋯) criado por menu(), com o mesmo ajuste de posição dos sel()."},{"nome":"tagField","assinatura":"function tagField(items,addLabel,addAct,removeAct,cls)","doc":"etiquetas removíveis"},{"nome":"fold","assinatura":"function fold(id,title,body,o)","doc":"Devolve o HTML de uma secção dobrável. `o.open` é só o estado inicial:\ndepois manda o foldState, para a dobra sobreviver aos re-renders.\n`o.summary` aparece no cabeçalho, visível mesmo com a secção fechada."},{"nome":"toggleFold","assinatura":"function toggleFold(id)","doc":"abre ou fecha a secção no DOM e guarda o estado, para o próximo render o respeitar"},{"nome":"fileBlock","assinatura":"function fileBlock(label,list,inputId,onPick,delFn,opts)","doc":"bloco de ficheiros reutilizável"},{"nome":"delFileConfirm","assinatura":"function delFileConfirm(fn,fid,tipo)","doc":"A confirmação que faltava: o apagar ficava a 8px do puxador de arrastar,\nambos pequenos, e o toque falhado destruía o ficheiro no ato — do\nIndexedDB, sem undo. Agora pergunta, e diz o que se perde."},{"nome":"openMeta","assinatura":"function openMeta(fid)","doc":"Abre a ficha do ficheiro `fid` (nome, tamanho, pré-visualização), procurando-o\nentre os metadados já guardados e os pendentes do formulário aberto."},{"nome":"thumbSrc","assinatura":"function thumbSrc(id)","doc":"miniatura pequena de uma foto: usa a guardada (tn_), ou cria-a uma vez a partir do original"},{"nome":"makeThumb","assinatura":"function makeThumb(blob)","doc":"Encolhe uma imagem para miniatura (lado maior ≤ 220px) e devolve uma Promise\ncom o blob JPEG. Nunca amplia; rejeita se o blob não for imagem legível."},{"nome":"paintThumbs","assinatura":"function paintThumbs(list,root)","doc":"Pinta as miniaturas depois do HTML entrar no DOM: para cada ficheiro da\nlista resolve a miniatura (thumbSrc) e mete o <img> na caixa th_<id>.\n`root` limita a procura — por omissão à janela de cima, porque a lista\npor baixo usa os mesmos ids."},{"nome":"livePhotoName","assinatura":"function livePhotoName(id,v)","doc":"guarda o nome da foto no pForm à medida que se escreve, para não se perder num repinte"},{"nome":"modalTop","assinatura":"modalTop ()","doc":"a janela de cima da pilha, ou null se não há nenhuma aberta"},{"nome":"modalBodyEl","assinatura":"modalBodyEl ()","doc":"o elemento .body da janela de cima — onde as vistas repintam o conteúdo (null sem janela)"},{"nome":"modalLayer","assinatura":"function modalLayer()","doc":"Constrói e devolve o esqueleto DOM de uma janela vazia (véu, cabeçalho com X,\ncorpo e rodapé) — quem chama pendura-o no body e preenche-o com o fillModal."},{"nome":"modalSnap","assinatura":"function modalSnap(el)","doc":"O que está escrito na janela, numa string comparável. É o suficiente para\nsaber se fechar deita fora trabalho de alguém."},{"nome":"demote","assinatura":"function demote(el)","doc":"Manda uma janela para baixo da pilha: os ids passam a data-mid (para o\ngetElementById só ver a de cima), e a janela fica escurecida e inerte."},{"nome":"promote","assinatura":"function promote(el)","doc":"o inverso do demote: devolve os ids à janela e torna-a de novo utilizável quando a de cima fecha"},{"nome":"fillModal","assinatura":"function fillModal(el,title,body,foot,menuHtml)","doc":"Preenche uma janela já criada: título, corpo, menu do cabeçalho e rodapé —\npor omissão, Cancelar + Guardar (que chama o onSave da janela de cima)."},{"nome":"pushHist","assinatura":"function pushHist()","doc":"Arma a sentinela no histórico (uma só de cada vez, via _histOn) para o\n\"voltar\" do Android cair no popstate abaixo em vez de sair da app."},{"nome":"openModal","assinatura":"function openModal(title,body,foot,menuHtml)","doc":"Abre uma janela nova por cima do que houver: a anterior desce na pilha\n(demote), o scroll da página tranca e a sentinela do \"voltar\" arma-se.\nTira também um retrato do formulário (snap), para o closeModal saber se\nhá alterações por deitar fora. Devolve a camada, com onSave a null —\nquem chama define-o depois."},{"nome":"focarModal","assinatura":"function focarModal(el)","doc":"leva o foco para dentro da janela, para o teclado e os leitores de ecrã não ficarem atrás do véu"},{"nome":"setModal","assinatura":"function setModal(title,body,foot,menuHtml)","doc":"substitui o conteúdo da janela de cima (sem empilhar)"},{"nome":"closeModal","assinatura":"function closeModal(origem)","doc":"Fecha a janela de cima. `origem` diz por onde se saiu ('fundo', 'x',\n'voltar'…): esses caminhos de abandono, com alterações por guardar,\nabrem primeiro a pergunta \"Sair sem guardar?\". Sem origem (Guardar,\nCancelar), fecha sem perguntar — são decisões, não acidentes."},{"nome":"_sairSemGuardar","assinatura":"function _sairSemGuardar()","doc":"resposta ao \"Sair sem guardar\": fecha a pergunta e a janela por baixo, sem voltar a perguntar"},{"nome":"closeAllModals","assinatura":"function closeAllModals()","doc":"despeja a pilha inteira de janelas (closeModal sem origem: fecha sem perguntar)"},{"nome":"confirmModal","assinatura":"function confirmModal(title,text,cb)","doc":"O botão diz o verbo da ação e veste-se de perigo quando destrói: um\n\"Confirmar\" primário igual ao Guardar convidava ao reflexo justamente\nonde não há undo."},{"nome":"comDesfazer","assinatura":"function comDesfazer(msg,restaurar,aoExpirar)","doc":"Toast com \"Anular\" durante seis segundos. `restaurar` repõe os dados (a\ngravação e o repinte vêm por acréscimo) se o anular for clicado;\n`aoExpirar` corre quando o prazo passa sem clique — ou quando outro\ndesfazer atropela este — e é aí que se liquida o que não volta."},{"nome":"falhaCampo","assinatura":"function falhaCampo(id,msg)","doc":"O toast diz o que falta; isto aponta o campo — realça-o, leva-o ao ecrã\ne larga o realce à primeira tecla."},{"nome":"pickModal","assinatura":"function pickModal(title,options,onPick,extra)","doc":"escolher de uma lista, no estilo da app"},{"nome":"lpShow","assinatura":"function lpShow(title,opts)","doc":"A folha de opções do toque longo: fecha o que estiver aberto e mostra a\nlista num pickModal. Cada opção é {label, icon, act} — o act corre depois\nde fechar tudo. Os rótulos destrutivos (Apagar/Remover/…) pintam-se de\nvermelho aqui mesmo, já com o HTML no DOM."},{"nome":"lpMenu","assinatura":"function lpMenu(v)","doc":"O menu por omissão do toque longo: descodifica o data-lp (\"tipo:id\", ex.\n\"prop:abc\") e mostra as ações que fazem sentido para esse cartão — imóvel,\nmovimento, contrato, pessoa, recorrente, modelo ou hipoteca. A seleção em\nmassa (cloud/selecao.js) embrulha-o para tratar dos movimentos à maneira dela."}]},{"nome":"web/app/navegacao.js","texto":"NAVEGAÇÃO","funcoes":[{"nome":"view","assinatura":"view ()","doc":"O contentor onde cada vista é desenhada (o elemento #view)."},{"nome":"buildNav","assinatura":"function buildNav()","doc":"Reconstrói a navegação da gaveta (agrupada por NAV_GROUPS), marcando o\nseparador atual e o crachá dos planeados pendentes — na cor de aviso quando\nnenhum passou do prazo. Refaz também a barra de baixo."},{"nome":"buildTabbar","assinatura":"function buildTabbar(late)","doc":"Reconstrói a barra de baixo do telemóvel com os destinos de TABBAR;\nlate é a contagem de planeados pendentes para o crachá."},{"nome":"go","assinatura":"function go(id)","doc":"Muda de separador: limpa a subpágina das Definições e o donut, fecha a\ngaveta, refaz a navegação e repinta, com scroll para o topo."},{"nome":"goSet","assinatura":"function goSet(p)","doc":"Navega dentro das Definições: p é a subpágina ('' volta ao menu). Entrar\nnuma subpágina arma o histórico, para o voltar do sistema subir a Definições."},{"nome":"openDrawer","assinatura":"function openDrawer()","doc":"Abre a gaveta de navegação: fecha primeiro os painéis de filtros, arma o\nhistórico (o voltar do sistema fecha-a) e trava o scroll do fundo."},{"nome":"closeFilterPanels","assinatura":"function closeFilterPanels()","doc":"Fecha os painéis de filtros abertos na vista atual (funil das listas e painel\nde análise), deitando fora o rascunho; só repinta se algum estava aberto."},{"nome":"closeDrawer","assinatura":"function closeDrawer(fromPop)","doc":"Fecha a gaveta se estiver aberta e destrava o scroll do fundo. fromPop marca\nas chamadas vindas do voltar do sistema (de momento não muda o comportamento)."}]},{"nome":"web/app/auxiliares.js","texto":"","funcoes":[{"nome":"grupos","assinatura":"function grupos(intStr)","doc":"mete o espaço fino de milhares numa string de dígitos (a parte inteira, já em texto)."},{"nome":"money","assinatura":"function money(v,dec2)","doc":"valor em euros para mostrar: milhares com espaço fino, vírgula decimal e € no fim.\ndec2 força sempre duas casas; sem dec2 arredonda ao euro inteiro. Os negativos\nlevam o sinal de menos tipográfico (−), não o hífen."},{"nome":"fmtPhone","assinatura":"function fmtPhone(v)","doc":"telefone legível: 9 dígitos sem indicativo assumem-se portugueses (+351), o resto\ndo número agrupa-se de 3 em 3 a seguir ao indicativo. Vazio se não houver dígitos."},{"nome":"sanitizeRich","assinatura":"function sanitizeRich(html)","doc":"limpa HTML vindo de fora: só ficam as marcas que o editor cria (negrito, listas,\nparágrafos…), sem atributos, scripts nem estilos; marcas inline vazias caem.\nSe o DOMParser falhar, devolve o texto todo escapado — nunca HTML por limpar."},{"nome":"rich","assinatura":"function rich(s)","doc":"texto guardado → HTML seguro de apresentação: sanitiza se trouxer marcas; senão escapa e converte \\n em <br>."},{"nome":"richEditor","assinatura":"function richEditor(label,id,value,ph)","doc":"caixas de texto simples; o que estava guardado com HTML antigo é convertido em texto ao editar"},{"nome":"richToText","assinatura":"function richToText(s)","doc":"HTML antigo → texto simples: itens de lista viram \"• \", blocos viram quebras de\nlinha, as restantes marcas caem e as entidades são descodificadas. Texto sem\nmarcas passa intacto."},{"nome":"richTouch","assinatura":"function richTouch(e)","doc":"touchstart na barra do editor: executa o comando do botão tocado sem deixar o editor perder o foco."},{"nome":"richHost","assinatura":"function richHost(editor)","doc":"o editor onde um comando da barra deve atuar: o que tem o foco, ou o da última\nseleção guardada (que é reposta), ou, em último recurso, o do modal de cima com o\ncursor no fim. Devolve a caixa .rich-content já focada, ou null se não houver."},{"nome":"toggleInline","assinatura":"function toggleInline(host,cmd)","doc":"com o cursor apenas pousado (sem texto selecionado), o teclado do telemóvel ignora o\n\"estilo pendente\" do execCommand; por isso criamos a marca com um marcador invisível\ne pomos o cursor lá dentro — o que se escrever a seguir fica formatado"},{"nome":"richCmd","assinatura":"function richCmd(cmd,arg,editor)","doc":"aplica um comando de formatação (execCommand) no editor certo, dispara \"input\"\npara quem estiver a gravar alterações e atualiza o realce da barra."},{"nome":"richState","assinatura":"function richState(host)","doc":"realça na barra o que está ativo onde o cursor está"},{"nome":"richVal","assinatura":"function richVal(id)","doc":"conteúdo de um editor, já limpo; vazio se só tiver quebras"},{"nome":"pct","assinatura":"pct (v,d)","doc":"fração → percentagem com vírgula (0.253 → \"25,3%\"); d casas decimais (1 por omissão); \"—\" se não for número."},{"nome":"today","assinatura":"today ()","doc":"data de hoje em ISO (AAAA-MM-DD) — o formato em que as datas se guardam e comparam."},{"nome":"roomName","assinatura":"roomName (p,rid)","doc":"nome do quarto rid do imóvel p; vazio se não existir."},{"nome":"findLoan","assinatura":"findLoan (p,id)","doc":"hipoteca com este id dentro do imóvel p; null se lá não estiver."},{"nome":"anyLoan","assinatura":"function anyLoan(id)","doc":"hipoteca por id, procurada em todos os imóveis"},{"nome":"pidProps","assinatura":"function pidProps(pid)","doc":"imóveis de um filtro: id de imóvel, 'g:ID' de grupo, ou vazio = âmbito atual"},{"nome":"ownersOfProp","assinatura":"function ownersOfProp(p)","doc":"CONTAS ENTRE PROPRIETÁRIOS\nCada movimento com \"pago por\" fica a crédito de quem pagou, e o custo divide-se\nem partes iguais pelos proprietários do imóvel. Receber uma renda é o inverso:\nquem recebeu passa a dever aos outros. Movimentos sem pagador indicado não\nentram nestas contas — de outra forma inventavam-se dívidas."},{"nome":"sharesOf","assinatura":"function sharesOf(p)","doc":"quota-parte de cada proprietário (fração). Sem percentagens definidas: partes iguais."},{"nome":"shareOf","assinatura":"shareOf (p,oid)","doc":"quota-parte (fração 0–1) do proprietário oid no imóvel p; 0 se não for dono."},{"nome":"splitShares","assinatura":"function splitShares(total,shares)","doc":"divide um total inteiro (cêntimos) pelas quotas, somando exatamente o total"},{"nome":"txSplitCents","assinatura":"function txSplitCents(t,p,os)","doc":"quanto cabe a cada dono (cêntimos, positivos) num movimento, conforme o modo de divisão:\nquota (quota-parte), pct (percentagens próprias), amount (valores certos) ou adjust\n(ajustes individuais; o resto pelas quotas)"},{"nome":"txOwnerFrac","assinatura":"function txOwnerFrac(t,oid)","doc":"fração de um movimento que cabe a um dono (para a vista filtrada por proprietário)"},{"nome":"txProps","assinatura":"function txProps(t)","doc":"imóveis abrangidos por um movimento (o próprio, ou os do grupo)"},{"nome":"psplitCents","assinatura":"function psplitCents(t,ps,total)","doc":"divide o total (cêntimos) pelos imóveis do grupo, conforme o modo escolhido"},{"nome":"txPropShare","assinatura":"function txPropShare(t,pid)","doc":"fração de um movimento que cabe a um imóvel"},{"nome":"txW","assinatura":"function txW(t,pid)","doc":"peso do movimento numa vista: por imóvel (pid) ou no âmbito atual"},{"nome":"txGroupOwners","assinatura":"function txGroupOwners(t)","doc":"donos (fichas) dos imóveis do grupo de um movimento, sem repetir"},{"nome":"balanceLines","assinatura":"function balanceLines(pid)","doc":"efeito de cada movimento nos saldos (cêntimos por dono), para se poder conferir"},{"nome":"refreshDetail","assinatura":"function refreshDetail()","doc":"se o modal \"Como se chega aos saldos\" estiver por cima, reabre-o para refletir dados frescos."},{"nome":"balancesDetail","assinatura":"function balancesDetail(pid)","doc":"abre o modal \"Como se chega aos saldos\": cada movimento que conta, o efeito em\ncêntimos por dono e o saldo acumulado até aí. pid limita a um imóvel (vazio =\nâmbito atual). Tocar num movimento abre-o para editar; sem movimentos, só avisa."},{"nome":"ownerBalances","assinatura":"function ownerBalances(pid)","doc":"saldos entre comproprietários, em euros por dono: quem pagou fica a crédito e a\nparte de cada um sai das quotas ou da divisão escolhida no movimento; as\ntransferências acertam contas diretamente. pid limita a um imóvel; sem pid vale o\nâmbito atual. Positivo é a receber, negativo a pagar."},{"nome":"settlePlan","assinatura":"function settlePlan(bal)","doc":"menor número de transferências que zera os saldos"},{"nome":"ownerIsGrp","assinatura":"ownerIsGrp ()","doc":"o filtro de proprietário atual é um grupo ('g:ID')?"},{"nome":"ownerFilterIds","assinatura":"function ownerFilterIds()","doc":"ids de proprietário abrangidos pelo filtro atual: vazio sem filtro, os do grupo, ou só o escolhido."},{"nome":"ownerFilterName","assinatura":"function ownerFilterName()","doc":"nome a mostrar do filtro de proprietário atual (pessoa ou grupo); vazio sem filtro."},{"nome":"scope","assinatura":"scope ()","doc":"imóveis da vista atual: todos sem filtro de proprietário; com filtro, os que\npertencem a quem foi escolhido (e, para uma pessoa, só onde a quota é > 0)."},{"nome":"propStatus","assinatura":"function propStatus(p)","doc":"estado de ocupação de um imóvel, para cartões e filtros: devolve {key,label,badge}\n— uso próprio, vago, parcial (\"2/3 quartos\", no modo de quartos) ou arrendado."},{"nome":"num","assinatura":"function num(s)","doc":"número escrito à mão → Number: ignora símbolos e decide se as vírgulas e os\npontos são decimais ou separadores de milhares. Devolve 0 quando não percebe —\nnunca NaN, para as somas não se estragarem."},{"nome":"toast","assinatura":"function toast(m,op)","doc":"op: {rotulo, fn, ms} poe um botao no toast — e a peca que faz o Anular\npossivel. Sem op, comporta-se exatamente como sempre."},{"nome":"cats","assinatura":"cats ()","doc":"árvore de categorias das despesas e pagamentos: a das definições, ou a de fábrica."},{"nome":"catsIn","assinatura":"catsIn ()","doc":"árvore de categorias das receitas: a das definições, ou a de fábrica."},{"nome":"excKey","assinatura":"excKey (tk,cat,sub)","doc":"categorias/subcategorias podem ficar fora dos totais de receitas e despesas"},{"nome":"isExc","assinatura":"function isExc(kind,cat,sub)","doc":"esta categoria (ou a subcategoria, se dada) está excluída dos totais deste tipo de movimento?"},{"nome":"toggleExc","assinatura":"function toggleExc(tk,cat,sub)","doc":"liga/desliga a exclusão de uma categoria dos totais; tk é a chave da árvore\n('cats' ou 'catsIn'), não o tipo do movimento. Grava e volta a desenhar tudo."},{"nome":"allCats","assinatura":"function allCats(kind)","doc":"todas as categorias conhecidas, para o filtro (sem repetir)"},{"nome":"creditorBalances","assinatura":"function creditorBalances(pid)","doc":"de quem se recebeu / a quem se pagou uma dívida a terceiros, com o que falta devolver"},{"nome":"knownCreditors","assinatura":"knownCreditors ()","doc":"credores já escritos nos movimentos, sem repetir e por ordem — para sugerir ao preencher."},{"nome":"ic","assinatura":"function ic(n,s)","doc":"ícone SVG inline pelo nome n, com s px de lado (20 por omissão);\no traço herda a cor do texto onde for colado (currentColor)."},{"nome":"fitInsets","assinatura":"function fitInsets()","doc":"O wrapper Android injeta os valores exatos. Fora dele, medimos o env() e,\nse der zero num ecrã sem barra do browser, assumimos uma barra de estado."},{"nome":"__setInsets","assinatura":"__setInsets (t,b,l,r)","doc":"chamada pelo wrapper Android com as margens exatas da área segura (px); passa-as\nàs variáveis CSS e marca-as como nativas, para o fitInsets deixar de adivinhar."},{"nome":"mq","assinatura":"mq ()","doc":"a tal MediaQueryList do modo escuro, criada uma vez e reutilizada; se o matchMedia\nfalhar, devolve um substituto inerte para o resto do código não ter de testar."},{"nome":"isDark","assinatura":"function isDark()","doc":"o tema efetivo é escuro? Sim com 'dark' explícito, ou em automático quando o sistema está escuro."},{"nome":"applyTheme","assinatura":"function applyTheme()","doc":"aplica o tema efetivo à página: classe .dark no <html>, paleta dos gráficos\ntrocada dentro do próprio array PAL (quem lhe guarda referência vê as cores\nnovas), e meta theme-color / color-scheme atualizados — a razão de o modo\nautomático não fixar o color-scheme está na nota lá dentro."},{"nome":"setTheme","assinatura":"function setTheme(t)","doc":"escolhe o tema ('light', 'dark' ou 'auto'), grava nas definições e aplica já."}]},{"nome":"web/app/definicoes.js","texto":"","funcoes":[{"nome":"vImport","assinatura":"function vImport()","doc":"DADOS"},{"nome":"navRow","assinatura":"navRow (title,sub,icon,page)","doc":"DEFINIÇÕES"},{"nome":"vDefaults","assinatura":"function vDefaults()","doc":"Subpágina \"Valores por omissão\": crescimento das rendas, inflação, horizonte,\nyield de avaliação e imposto do selo. Cada campo grava logo ao sair (setSet)."},{"nome":"vSettings","assinatura":"function vSettings()","doc":"Vista principal das Definições: com setPage preenchido devolve a subpágina\nrespetiva (com o Voltar colado ao topo); sem ele, o menu — tema, linhas de\nnavegação com contagens e o cartão \"Sobre\"."},{"nome":"catTree","assinatura":"function catTree(tk,title,sub)","doc":"Cartão editável de uma árvore de categorias (tk: 'cats' ou 'catsIn'):\nrenomear escrevendo no próprio nome, apagar, tirar dos totais (botão €)\ne gerir subcategorias em chips. O crachá diz quantos movimentos a usam."},{"nome":"vCats","assinatura":"function vCats()","doc":"Subpágina \"Tipos de movimento\": as duas árvores (receitas e pagamentos) em\ndobras, mais o botão de repor as listas de origem."},{"nome":"vTags","assinatura":"function vTags()","doc":"Subpágina \"Etiquetas\": cada uma com o número de movimentos que a usam,\nbotão de apagar e botão de criar nova."},{"nome":"gMemberName","assinatura":"function gMemberName(kind,id)","doc":"Nome legível de um membro de grupo a partir do tipo e do id; '' se já não existir."},{"nome":"vGroups","assinatura":"function vGroups()","doc":"Subpágina \"Grupos\": uma secção por tipo (imóveis, proprietários, contratos),\ncada grupo com os membros em resumo; tocar num abre o modal de edição."},{"nome":"groupModal","assinatura":"function groupModal(kind,id)","doc":"Abre o modal de criar (só kind) ou editar (com id) um grupo. Trabalha numa\ncópia (gForm) — nada é gravado até Guardar, que exige nome e pelo menos um\nmembro antes de escrever em db.groups."},{"nome":"groupBody","assinatura":"function groupBody()","doc":"Corpo do modal do grupo, gerado a partir de gForm: nome e membros em chips."},{"nome":"repaintGroup","assinatura":"function repaintGroup()","doc":"Redesenha o corpo do modal do grupo depois de mexer nos membros, sem o fechar."},{"nome":"addGroupMember","assinatura":"function addGroupMember()","doc":"Seletor com os candidatos que ainda não estão no grupo (imóveis,\nproprietários ou contratos, conforme o tipo). Recolhe primeiro o nome já\nescrito para gForm, para o repinte não o perder."},{"nome":"delGroupMember","assinatura":"function delGroupMember(id)","doc":"Tira um membro do grupo em edição (só em gForm) e repinta; recolhe antes o nome escrito."},{"nome":"delGroup","assinatura":"function delGroup(id)","doc":"Apaga o grupo depois de confirmar com o impacto: os movimentos atribuídos\nficam sem grupo (voltam a contar para todos) e os filtros ativos que\napontavam para ele são limpos. Grava e repinta."},{"nome":"promptModal","assinatura":"function promptModal(title,label,value,cb)","doc":"Modal genérico de um só campo de texto. Enter equivale a Guardar; o cb só é\nchamado se sobrar texto depois do trim. Foca o campo ao abrir."},{"nome":"addCat","assinatura":"function addCat(tk)","doc":"Pede o nome e cria uma categoria vazia na árvore tk; grava e repinta."},{"nome":"renameCat","assinatura":"function renameCat(tk,oldName,newName)","doc":"Renomeia uma categoria mantendo a ordem (reconstrói o objeto) e atualiza os\nmovimentos dessa árvore que a usavam. Nome vazio ou igual só repinta."},{"nome":"delCat","assinatura":"function delCat(tk,k)","doc":"Apaga a categoria depois de confirmar com o impacto: os movimentos que a\nusavam ficam sem categoria nem subcategoria (não se apagam)."},{"nome":"addSub","assinatura":"function addSub(tk,k)","doc":"Pede o nome e junta uma subcategoria à categoria k (ignora repetidas); grava e repinta."},{"nome":"renameSub","assinatura":"function renameSub(tk,k,old)","doc":"Muda o nome de uma subcategoria via prompt: atualiza a lista, os movimentos\nque a usavam e migra a marca de exclusão dos totais para o nome novo."},{"nome":"delSub","assinatura":"function delSub(tk,k,sb)","doc":"Apaga a subcategoria depois de confirmar com o impacto: sai da lista e dos\nmovimentos que a usavam (ficam só sem subcategoria)."},{"nome":"resetCats","assinatura":"function resetCats()","doc":"Repõe as duas árvores nas listas de origem, após confirmação; os movimentos\nmantêm o texto de categoria que já tinham."},{"nome":"addTag","assinatura":"function addTag()","doc":"Pede o nome e cria uma etiqueta (ignora repetidas); grava e repinta."},{"nome":"delTag","assinatura":"function delTag(g)","doc":"Apaga a etiqueta depois de confirmar com o impacto: sai das definições e de\ntodos os movimentos que a tinham."},{"nome":"filtrosComuns","assinatura":"function filtrosComuns()","doc":"A lista de filtros comuns guardada nas definições ([] enquanto não houver)."},{"nome":"vFiltrosComuns","assinatura":"function vFiltrosComuns()","doc":"Subpágina \"Filtros comuns\": cada filtro com o resumo das escolhas (tocar\nabre o modal de edição), botão de apagar e botão de criar novo."},{"nome":"fcResumo","assinatura":"function fcResumo(f)","doc":"Resumo das escolhas de um filtro numa linha, separadas por «·»;\ndevolve '' quando o filtro não fixa nada."},{"nome":"fcModal","assinatura":"function fcModal(id)","doc":"Abre o modal de criar (sem id) ou editar um filtro comum; trabalha numa\ncópia (fcForm) — nada é gravado até fcGuardar."},{"nome":"fcCorpo","assinatura":"function fcCorpo()","doc":"Corpo do modal do filtro: nome, tipo, imóvel, proprietário, categoria,\nsubcategoria e datas. As categorias dependem do tipo escolhido (as dívidas\nusam a árvore das despesas), daí mudar o tipo repintar o formulário."},{"nome":"fcColher","assinatura":"function fcColher(soFormulario)","doc":"soFormulario: escrever no nome não repinta (perdia o foco a cada tecla);\nmudar tipo ou categoria repinta, porque as opções seguintes dependem"},{"nome":"fcGuardar","assinatura":"function fcGuardar()","doc":"Guarda o filtro do modal: colhe o formulário, exige nome, substitui (ou\nacrescenta) em db.settings.filters e fecha com um toast."},{"nome":"delFiltroComum","assinatura":"function delFiltroComum(id)","doc":"Apaga um filtro comum sem pedir confirmação — o toast traz Desfazer,\nque repõe a cópia guardada."},{"nome":"aplicarFiltroComum","assinatura":"function aplicarFiltroComum(id)","doc":"O aplicador: cada vista pega no que lhe diz respeito."},{"nome":"fcSelector","assinatura":"function fcSelector(fn)","doc":"Selector \"aplicar um filtro comum\" para meter num funil de filtros; devolve\n'' enquanto não houver filtros. fn é o onchange (por omissão onFcAplicar)."},{"nome":"onFcAplicar","assinatura":"function onFcAplicar()","doc":"onchange do selector: aplica o filtro escolhido (a opção vazia não faz nada)."}]},{"nome":"web/cloud/guia.js","texto":"Primeiros passos e tutoriais.\n\nQuem chega a uma app de gestão de imóveis com o ecrã vazio não sabe por\nonde começar, e a ordem importa: sem perfil os contratos saem sem os dados\ndo senhorio, sem imóveis não há onde pendurar um contrato, e sem contrato\nas rendas não se geram sozinhas.\n\nNada disto obriga a nada. É um cartão na vista geral com o que falta, e\ntutoriais para quem quiser ser levado pela mão. Fecha-se e não volta.\n\nO tutorial é um cartão a flutuar, não um modal: quem está a seguir os\npassos tem de conseguir mexer na app por baixo enquanto o lê.","funcoes":[{"nome":"feitos","assinatura":"function feitos()","doc":"os tutoriais já vistos até ao fim, lidos do localStorage ({id: 1});\ndevolve {} quando não há nada ou o armazenamento está vedado"},{"nome":"marcarFeito","assinatura":"function marcarFeito(id)","doc":"regista no localStorage que este tutorial foi visto até ao fim"},{"nome":"guiaAbrir","assinatura":"guiaAbrir (id)","doc":"abre o tutorial pedido no primeiro passo; um id desconhecido não faz nada"},{"nome":"guiaAnterior","assinatura":"guiaAnterior ()","doc":"recua um passo no tutorial aberto (no primeiro passo não faz nada)"},{"nome":"guiaSeguinte","assinatura":"guiaSeguinte ()","doc":"avança um passo; no último (\"Terminar\") marca o tutorial como visto,\nfecha o cartão e repinta a app, para o cartão de passos refletir isso"},{"nome":"guiaFechar","assinatura":"guiaFechar ()","doc":"fecha e remove o cartão do tutorial, sem o marcar como visto"},{"nome":"guiaAjustar","assinatura":"function guiaAjustar()","doc":"Com uma janela aberta, o cartão encosta ao topo.\n\nFicava por baixo da janela e desaparecia: entrava-se nas definições para\npreencher o perfil e o tutorial sumia, sem forma de continuar. Agora passa\npor cima — e muda para o topo, senão tapava os botões de guardar e\ncancelar, que estão em baixo."},{"nome":"guiaPintar","assinatura":"function guiaPintar()","doc":"Desenha (ou redesenha) o cartão flutuante com o passo atual: cria o #cwGuia\nse ainda não existir, muda para o ecrã que o passo aponta (p.ir) e escreve\ntítulo, texto e botões. O texto do passo é HTML de confiança — vem de\nTUTORIAIS, escrito aqui —, por isso só o título passa pelo esc."},{"nome":"euSou","assinatura":"function euSou()","doc":"o registo de owner do utilizador com sessão, ou null — é lá que vive\no NIF que diz se o perfil está preenchido"},{"nome":"passos","assinatura":"function passos()","doc":"A lista de primeiros passos com o estado calculado da base local: perfil\n(há NIF?), imóveis, contratos e movimentos. O passo dos contratos salta\nquando não há imóveis para arrendar. Cada passo traz o porquê e a ação\n(act) que o botão \"Fazer agora\" dispara."},{"nome":"passosFora","assinatura":"passosFora ()","doc":"dispensa o cartão de primeiros passos de vez (fica no localStorage)\ne repinta já, para ele desaparecer"},{"nome":"passosDispensados","assinatura":"function passosDispensados()","doc":"o cartão de primeiros passos foi dispensado? (false se o localStorage falhar)"},{"nome":"cartaoPassos","assinatura":"function cartaoPassos()","doc":"O HTML do cartão de primeiros passos que a vista geral mostra no topo —\nou '' quando foi dispensado, não há sessão, ou já está tudo feito (o\ncartão não fica pendurado a dar os parabéns). Cada passo por fazer tem\no \"Fazer agora\" e o botão do tutorial respetivo."},{"nome":"listaDeTutoriais","assinatura":"listaDeTutoriais ()","doc":"Todos os tutoriais, para quem os quiser rever. Vive aqui e não na ajuda\nporque é aqui que estão — a ajuda só os mostra."}]},{"nome":"web/cloud/novidades.js","texto":"Atualizações e novidades.\n\nTrês coisas, por esta ordem de importância:\n\n1. A app verifica sozinha, ao abrir, se há versão nova, e instala-a.\n2. Se a versão em uso já não for aceitável, tranca e obriga a atualizar.\n3. Havendo novidades, mostra o que mudou — só as partes que dizem\nrespeito a quem está a ver.","funcoes":[{"nome":"funcsDoUtilizador","assinatura":"function funcsDoUtilizador()","doc":"Que funcionalidades esta pessoa usa.\nHoje toda a gente tem todas — não há ainda permissões parciais. Quando\nhouver, é esta função que passa a devolver só as que a pessoa tem, e tudo\no resto (avisos, modal, secção de novidades) acompanha sem mudar."},{"nome":"afetaMe","assinatura":"function afetaMe(sec)","doc":"Diz se uma secção de novidades toca nalguma funcionalidade desta pessoa."},{"nome":"avisoParaMim","assinatura":"function avisoParaMim(a)","doc":"Um aviso só conta se sobrar alguma secção depois de filtrar."},{"nome":"avisosDesde","assinatura":"function avisosDesde(v)","doc":"Os avisos posteriores à versão v, já filtrados ao que diz respeito a quem vê."},{"nome":"vistoAte","assinatura":"function vistoAte()","doc":"Até que versão as novidades já foram vistas (0 se nunca, ou sem localStorage)."},{"nome":"marcarVisto","assinatura":"function marcarVisto(v)","doc":"Guarda no localStorage que as novidades até à versão v já foram vistas."},{"nome":"secHtml","assinatura":"function secHtml(sec, chave)","doc":"Uma secção de novidades como cartão dobrável; a chave liga-a ao estado de\naberta/fechada em novAbertas."},{"nome":"novHtml","assinatura":"function novHtml(avisos)","doc":"A lista de avisos inteira em HTML — serve o modal e a secção das Definições."},{"nome":"novToggle","assinatura":"novToggle (chave)","doc":"Abrir e fechar uma secção.\n\nRedesenhava só o corpo do modal. Na secção das Definições não há modal\nnenhum, por isso o toque mudava o estado e não se via nada — era preciso\nsair do submenu e voltar a entrar. Agora redesenha onde quer que a lista\nesteja: no modal se houver um, senão na vista."},{"nome":"verNovidades","assinatura":"verNovidades (avisos, aoFechar)","doc":"Abre o modal \"O que há de novo\"; aoFechar, se vier, corre quando a pessoa\ncarrega em Continuar."},{"nome":"novFechar","assinatura":"novFechar ()","doc":"Fecha o modal, marca as novidades como vistas e corre o combinado ao fechar."},{"nome":"mostrarNovidadesSeHouver","assinatura":"function mostrarNovidadesSeHouver()","doc":"Mostra as novidades por ver, se sobrar alguma depois de filtrar."},{"nome":"gateAtualizar","assinatura":"function gateAtualizar(minima)","doc":"O ecrã que tranca a app quando a versão em uso desceu abaixo da mínima\naceite: tapa tudo e só deixa atualizar. Chamado duas vezes não duplica."},{"nome":"atualizarAgora","assinatura":"atualizarAgora ()","doc":"Limpa as caches com o passo a passo à vista e recarrega a página — é o\ncaminho de todos os botões \"Atualizar\"."},{"nome":"limparCaches","assinatura":"function limparCaches()","doc":"Apaga as caches do browser e pede ao service worker para se atualizar.\nNunca rejeita: sem caches ou sem service worker resolve na mesma, porque o\nque importa é a recarga que vem a seguir."},{"nome":"jaRecarreguei","assinatura":"function jaRecarreguei(alvo)","doc":"Uma recarga por versão-alvo. Se depois de recarregar continuar velha, o\nproblema não é a cache — e um ciclo de recargas seria pior do que o atraso."},{"nome":"marcarRecarga","assinatura":"function marcarRecarga(alvo)","doc":"Regista (na sessão) que já se recarregou a caminho desta versão."},{"nome":"bannerAtualizar","assinatura":"function bannerAtualizar(v)","doc":"A faixa discreta no fundo do ecrã: há versão nova, atualiza quando quiseres.\nÉ o plano B, para quando a recarga automática não chegou à versão nova."},{"nome":"ecraAtualizar","assinatura":"function ecraAtualizar(versao, passo)","doc":"O ecrã que se vê enquanto a app se atualiza sozinha. Antes era um piscar\nmudo: a página recarregava sem dizer porquê, e quem visse ficava sem\nsaber se era um erro. Agora diz o que está a fazer, passo a passo."},{"nome":"verificarVersao","assinatura":"verificarVersao ()","doc":"Pergunta ao servidor (/versao.json) que versão há: abaixo da mínima tranca\na app; havendo mais nova, limpa as caches e recarrega sozinha uma vez, com\no ecrã de progresso à vista; se mesmo assim continuar velha, resta a faixa.\nSem rede não faz nada — a app fica com o que tem."},{"nome":"vNovidades","assinatura":"function vNovidades()","doc":"A secção \"Novidades\" das Definições: todos os avisos que dizem respeito a\nesta pessoa, ou uma nota de que ainda não há nenhum."},{"nome":"ecraLivre","assinatura":"function ecraLivre()","doc":"As novidades entram na fila atrás dos avisos que já existem: primeiro o\naviso inicial, depois os termos, e só com o ecrã livre é que se\nconta o que mudou. Três janelas empilhadas seriam pior do que nenhuma."},{"nome":"talvezNovidades","assinatura":"talvezNovidades ()","doc":"Mostra as novidades por ver, mas só com o ecrã livre de avisos mais\nimportantes (aviso inicial, termos, atualização forçada)."}]},{"nome":"web/avisos.js","texto":"Novidades de cada publicação.\n\nFicheiro só de dados: é lido pela app e também pelo service worker (com\nimportScripts), por isso não pode tocar em `document` nem em `window`.\n\nA versão não se escreve à mão em lado nenhum — é a da primeira entrada\ndesta lista. Assim não há como publicar novidades e esquecer o número, nem\nsubir o número sem dizer o que mudou.\n\nCada secção declara que funcionalidades toca. É por funcionalidade e não\npor papel de propósito: quando houver permissões parciais, quem tiver\nacesso a uma funcionalidade vê o que lhe diz respeito, sem precisar de\npertencer a um papel inteiro.","funcoes":[]},{"nome":"web/legal.js","texto":"Termos e Condições e Política de Privacidade.\nFicam num ficheiro à parte por serem longos e mudarem por outras razões\nque não o código. Ao alterá-los, muda também TERMS_VERSION no worker\n(worker/src/api.js) para a app voltar a pedir a aceitação a toda a gente.\n\nATENÇÃO: preenche a identificação de quem opera o serviço.\n\nSobre a MORADA: não tens de publicar a tua morada de casa. O que a lei\npede é um endereço de contacto onde possas ser alcançado. Alternativas,\nda mais simples à mais formal:\n· um apartado dos CTT (poucos euros por ano);\n· um serviço de domiciliação / escritório virtual (dá-te uma morada\ncomercial real, tipicamente 10–30 €/mês);\n· a sede de uma sociedade unipessoal, se e quando criares uma.\nEnquanto o serviço for gratuito e pessoal, podes deixar MORADA e NIF\nvazios: os documentos escondem essas linhas sozinhos. A partir do\nmomento em que cobrares, precisas de morada e NIF publicados.","funcoes":[]}]},{"id":"pedidos","titulo":"Pedidos de ajuda e erros","itens":[{"nome":"worker/src/rotas/tickets.js","texto":"Pedidos de ajuda e erros comunicados pela app.","funcoes":[{"nome":"rotasTickets","assinatura":"async function rotasTickets(c)","doc":"Rotas dos pedidos de ajuda: criar um pedido (grava na D1, avisa o suporte\nno Discord e envia o número por email a quem escreveu) e listar os pedidos\nda própria pessoa — só os que ela contou, não os erros registados pela app.\nDevolve a Response, ou nada."}]},{"nome":"worker/src/rotas/relatos.js","texto":"Erros apanhados no browser de quem usa a app.\n\nCorre antes da verificação de sessão de propósito. O ecrã de entrada é onde\num erro custa mais — quem não consegue entrar não tem como contar o que se\npassou — e era exatamente aí que os relatos se perdiam, porque o cliente só\nos enviava depois de haver sessão. Com sessão o relato fica em nome de quem\no viu; sem ela fica anónimo, limitado por endereço.","funcoes":[{"nome":"navegador","assinatura":"function navegador(ua)","doc":"O user-agent inteiro não cabe num embed e ninguém o lê. O que interessa é\nqual o browser e o sistema — que é o que separa \"está partido\" de \"está\npartido no browser da Samsung\"."},{"nome":"rotasRelatos","assinatura":"async function rotasRelatos(c)","doc":"Rota do POST /api/reports: guarda um relato de erro vindo do browser,\nassinado pela sessão quando existe, anónimo e com tecto mais baixo quando\nnão. Acima do tecto responde ok na mesma, para o cliente não insistir.\nDevolve null noutros caminhos."}]},{"nome":"worker/src/lib/relatos.js","texto":"Erros apanhados sozinhos abrem um pedido na mesma fila dos que as\npessoas contam, agrupados por assinatura para nao encher o canal.","funcoes":[{"nome":"marcarPessoa","assinatura":"async function marcarPessoa(env, fp, userId, t)","doc":"Quantas pessoas distintas apanharam esta assinatura.\n\nDuzentas ocorrências de uma pessoa e duzentas de duzentas pessoas contavam\nigual no `n`, e são problemas de gravidade muito diferente. A chave\nprimária da tabela faz a distinção sozinha: a mesma pessoa a repetir o\nmesmo erro não acrescenta linha."},{"nome":"recordReport","assinatura":"async function recordReport(env, ctx, categoria, message, detail, userId, extra)","doc":"Um erro apanhado sozinho abre um pedido na mesma fila dos que as pessoas\ncontam. Erros repetidos somam-se ao pedido que já existe, em vez de abrirem\num novo de cada vez."}]},{"nome":"worker/src/notify.js","texto":"Avisos para o Discord: um canal para quem programa (pedidos e erros) e\noutro para quem opera (consumo da infraestrutura). Sem webhook configurado,\ntudo isto não faz nada — a app funciona à mesma.","funcoes":[{"nome":"post","assinatura":"async function post(url, payload)","doc":"POST de JSON para um webhook. Devolve true/false e nunca lança:\num Discord em baixo não pode partir o resto do pedido."},{"nome":"cut","assinatura":"cut (s, n)","doc":"Corta a n caracteres com reticências — o Discord recusa embeds com campos longos demais."},{"nome":"avisar","assinatura":"function avisar(env, ctx, embed, components, canal, webhook, reserva)","doc":"Com bot configurado, a mensagem leva botões para resolver o pedido sem sair\ndo Discord; sem ele, vai pelo webhook, sem botões."},{"nome":"notifyDev","assinatura":"function notifyDev(env, ctx, embed, components)","doc":"Erros da app e do servidor, infraestrutura, segurança: quem constrói."},{"nome":"notifySuporte","assinatura":"function notifySuporte(env, ctx, embed, components)","doc":"Pedidos contados por pessoas: quem fala com quem usa. Sem canal de suporte\nconfigurado, vão para onde iam antes."},{"nome":"ticketEmbed","assinatura":"function ticketEmbed(t, user)","doc":"O embed de um pedido novo (problema ou sugestão): assunto, corpo, quem o fez\ne o id do ticket no rodapé — é por esse id que os botões do bot o encontram."},{"nome":"errorEmbed","assinatura":"function errorEmbed(r)","doc":"O embed de um relato de erro (r vem da tabela de relatos, já agregado por mensagem:\nn é quantas vezes aconteceu, pessoas a quantos utilizadores diferentes)."},{"nome":"usageFields","assinatura":"async function usageFields(env)","doc":"Consumo do dia, contra os limites do plano gratuito. Os números da\nCloudflare vêm da API de análise; se ela não responder, vai o que\nconseguimos contar por dentro, que chega para perceber a tendência.\nOs campos do consumo, partilhados pelo resumo diário e pelo comando /uso."},{"nome":"watchLimits","assinatura":"async function watchLimits(env, ctx)","doc":"A vigia em si (a razão de ser está no comentário acima): compara o consumo com os\ntectos, avisa o canal de administração quando um passa o limiar — com @here a partir\nde 95% — e devolve quantos limites motivaram aviso, para o cron poder registar."},{"nome":"dailyReport","assinatura":"async function dailyReport(env, ctx)","doc":"O resumo diário: manda os campos de usageFields para o canal de administração, com a\ncor a acompanhar o pior sinal encontrado (🔴 acima de 90%, ⚠️ acima de 70%). Devolve\ntrue/false conforme chegou, ou null quando não há canal nem webhook configurados."},{"nome":"cloudflareUsage","assinatura":"async function cloudflareUsage(env)","doc":"API de análise da Cloudflare (GraphQL). Devolve null se não der."}]},{"nome":"web/cloud/ajuda.js","texto":"Documentos legais, aceitacao dos termos e pedidos de ajuda.","funcoes":[{"nome":"loadTickets","assinatura":"function loadTickets()","doc":"Vai buscar os pedidos do utilizador à API; quando chegam, repinta a página\nde Ajuda se ela estiver à vista. Se a rede falhar, fica uma lista vazia."},{"nome":"vAjuda","assinatura":"function vAjuda()","doc":"A página \"Ajuda e sugestões\": botões para reportar problema ou sugerir\nmelhoria, os pedidos em curso e os concluídos (com estado e resposta da\nequipa), e a lista de tutoriais. À primeira passagem dispara o loadTickets\ne repinta quando os pedidos chegarem."},{"nome":"tutoriaisNaAjuda","assinatura":"function tutoriaisNaAjuda()","doc":"Os tutoriais listados um a um: quem precisa de um não devia ter de esperar\nque a app lho ofereça na vista geral, nem de dispensar o cartão dos\nprimeiros passos para nunca mais lá chegar."},{"nome":"newTicket","assinatura":"newTicket (kind)","doc":"Abre o modal de novo pedido; kind ('problema' ou 'sugestao') só muda os textos."},{"nome":"sendTicket","assinatura":"sendTicket (kind)","doc":"Valida e envia o pedido escrito no modal, juntando a versão e o user agent\n(os dados do utilizador não vão). Com sucesso fecha o modal e recarrega a\nlista; o erro fica escrito dentro do próprio modal."},{"nome":"reportErr","assinatura":"function reportErr(msg, detail)","doc":"Envia um relato de erro para a API: mensagem, detalhe (stack), versão, ecrã\ne user agent. No máximo 8 por sessão e cada mensagem conta uma vez; falhas\nno envio são silenciosas — não há para onde reportar o próprio relato."},{"nome":"ondeEstava","assinatura":"function ondeEstava()","doc":"em que ecrã estava a pessoa: ajuda a reproduzir, e `tab` pode ainda não\nexistir se o erro for cedo"},{"nome":"vDoc","assinatura":"function vDoc(html)","doc":"Embrulha um documento legal (Termos ou Privacidade) num cartão de leitura\ncom botão para voltar à página legal das Definições."},{"nome":"vLegal","assinatura":"function vLegal()","doc":"O aviso prático não repete os documentos: os Termos e a Política dizem-no\ncom valor legal, aqui fica só o essencial."},{"nome":"vLegalAntigo","assinatura":"function vLegalAntigo()","doc":"O aviso completo de antes de haver Termos e Condições: garantias, cópias,\ndados de terceiros, segurança e responsabilidade, por extenso. Já nenhuma\npágina o mostra — o caminho em vigor é o vLegal com os documentos legais."},{"nome":"lockScroll","assinatura":"function lockScroll(on)","doc":"trava a página por baixo enquanto um ecrã de entrada estiver aberto"},{"nome":"readDoc","assinatura":"readDoc (e, page)","doc":"Os ecrãs de entrada (sessão, aviso, termos) vivem acima dos modais, por\nisso o documento tem de abrir numa camada própria, por cima de tudo."},{"nome":"closeDoc","assinatura":"closeDoc ()","doc":"Fecha a camada do documento aberta pelo CW.readDoc e devolve o scroll à página."},{"nome":"showTermsGate","assinatura":"function showTermsGate()","doc":"Ecrã bloqueante para quem aceitou uma versão antiga dos termos: deixa ler\nos documentos e só sai dali aceitando — ou recusando, o que apaga a conta\ndepois de mais uma confirmação. Se já estiver aberto, não duplica."},{"nome":"acceptTerms","assinatura":"acceptTerms ()","doc":"Regista a aceitação dos termos na API e fecha o ecrã bloqueante; se o\nregisto falhar, o erro aparece no próprio ecrã e ele fica aberto."},{"nome":"refuseTerms","assinatura":"refuseTerms ()","doc":"Modal de confirmação da recusa dos termos: avisa que apaga a conta e tudo o\nque lá está, sugere exportar primeiro e exige escrever APAGAR."},{"nome":"doRefuseTerms","assinatura":"doRefuseTerms ()","doc":"Consuma a recusa: a API apaga a conta no servidor (a palavra de confirmação\né validada lá) e este aparelho fica limpo — dados locais, sessão e snapshots\n— a terminar no ecrã de entrada."},{"nome":"showLegalGate","assinatura":"function showLegalGate()","doc":"Abre o aviso prático por cima da app, logo depois de haver sessão — uma vez\npor aparelho e por versão dos documentos. Fica até se carregar num botão."},{"nome":"acceptLegal","assinatura":"acceptLegal (full)","doc":"Fecha o aviso prático e marca-o como visto nesta versão; com `full`, segue\npara a página legal das Definições, onde está o detalhe todo."},{"nome":"copyId","assinatura":"copyId ()","doc":"Copia o id do utilizador para a área de transferência, para o dar a quem se\nquer conectar; o toast aparece na mesma quando o clipboard não existe."},{"nome":"addConn","assinatura":"addConn ()","doc":"Envia um convite de conexão para o id escrito no campo; fica pendente até o\noutro utilizador aceitar do lado dele."},{"nome":"acceptConn","assinatura":"acceptConn (id)","doc":"Aceita o convite de conexão id e sincroniza logo, para o que o outro já partilhou aparecer."},{"nome":"delConn","assinatura":"delConn (id, isPending)","doc":"Remove uma conexão, ou retira um convite (isPending). Convites saem sem\nperguntar; conexões feitas pedem confirmação, porque ambos deixam de ver as\ncasas partilhadas do outro — os dados de cada um não se apagam."},{"nome":"sharesModal","assinatura":"sharesModal (connId)","doc":"Modal para escolher que casas se partilham com a conexão connId. Ao guardar\nenvia a lista à API e, para cada casa partilhada pela primeira vez, abre de\nseguida a proposta de divisão de quotas, uma de cada vez (fila _shareQueue)."},{"nome":"nextShareProposal","assinatura":"function nextShareProposal()","doc":"Passa à casa seguinte na fila de propostas de quotas que o sharesModal deixou."},{"nome":"passwordModal","assinatura":"passwordModal ()","doc":"Modal de mudança de palavra-passe, com os requisitos a acenderem-se à\nmedida que se escreve. Quem entra com Google deixa o campo da atual vazio."},{"nome":"savePassword","assinatura":"savePassword ()","doc":"Valida a nova palavra-passe e envia a mudança à API; o servidor termina as\nsessões dos outros aparelhos e pode devolver um token novo para este, que\nfica guardado. Os erros aparecem dentro do próprio modal."},{"nome":"revokeSessions","assinatura":"revokeSessions ()","doc":"Depois de confirmado, termina a sessão em todos os outros aparelhos; este\ncontinua ligado (guarda o token novo se o servidor o devolver)."},{"nome":"deleteAccount","assinatura":"deleteAccount ()","doc":"Modal de confirmação para apagar a conta: diz quantos imóveis se perdem e\nexige escrever APAGAR e a palavra-passe (vazia para quem entra com Google)."},{"nome":"doDeleteAccount","assinatura":"doDeleteAccount ()","doc":"Apaga a conta na API (confirmação e palavra-passe validadas lá) e limpa\neste aparelho — dados locais, sessão e snapshots — a acabar no ecrã de\nentrada. Numa conta de teste o servidor pode entregar logo a seguinte, e\nnesse caso a app recarrega já com ela em vez de cair no login."},{"nome":"logout","assinatura":"logout ()","doc":"Termina a sessão neste aparelho depois de confirmar: os dados ficam na\nconta e a app volta ao ecrã de entrada, com a navegação reposta."}]}]},{"id":"correio","titulo":"Correio (Resend e Email Routing)","itens":[{"nome":"worker/src/lib/correio.js","texto":"O correio do Rendorium, pelo Resend.\n\nTrês remetentes, três papéis:\n\nno-reply@rendorium.com   o que a máquina diz sozinha (reset de password,\navisos) — com Reply-To para o support, porque\nas pessoas respondem na mesma e alguém tem de ler\nsupport@rendorium.com    respostas a pedidos de ajuda\ngeneral@rendorium.com    o resto (contacto, anúncios)\n\nSem RESEND_API_KEY definido, tudo isto é um no-op que diz que não enviou\n— a app funciona na mesma, como sempre foi a regra com o Discord. Fora\nde produção o assunto leva o prefixo do ambiente, para um teste nunca\nse confundir com um email a sério.","funcoes":[{"nome":"molde","assinatura":"function molde(titulo, corpoHtml, rodape)","doc":"O molde de todos os emails: simples, com a cara da app, e sempre com a\nversão em texto — há caixas de correio que só mostram isso."},{"nome":"dominioDaCasa","assinatura":"function dominioDaCasa(email)","doc":"Qualquer endereço no domínio da casa — rendorium.com ou um subdomínio.\nServe o registo (ninguém cria contas com o nosso nome) e o correio que\nentra (o test@ só aceita o que a própria casa envia)."},{"nome":"enviarEmail","assinatura":"async function enviarEmail(env, { para, assunto, html, texto, remetente })","doc":"Envia um email pelo Resend. Devolve sempre { enviado, motivo } e nunca\nlança: sem RESEND_API_KEY é um no-op, e um erro de rede ou do Resend vem\ncomo motivo — quem chama decide se isso trava alguma coisa. `remetente` é\numa chave de REMETENTES ('maquina' por omissão); `html` e `texto` são as\nduas versões do corpo, e manda-se as que existirem."},{"nome":"numeroPedido","assinatura":"function numeroPedido(id)","doc":"O número de um pedido: os primeiros 8 caracteres do id, em maiúsculas.\nÉ o mesmo prefixo que o /pedido do Discord e a procura do back office\naceitam — quem cita o número do email encontra o pedido em todo o lado."},{"nome":"emailPedidoRecebido","assinatura":"async function emailPedidoRecebido(env, para, id, assunto)","doc":"A confirmação automática de que um pedido de ajuda ficou registado, com o\nnúmero que a pessoa pode citar em qualquer canal. Devolve o resultado do enviarEmail."},{"nome":"emailReporPassword","assinatura":"async function emailReporPassword(env, para, ligacao)","doc":"O email de reset de palavra-passe: entrega a `ligacao` já pronta. O \"vale\n1 hora, uma vez\" é garantido por quem a criou — aqui só se escreve o envelope."},{"nome":"emailRespostaPedido","assinatura":"async function emailRespostaPedido(env, para, assunto, resposta, id)","doc":"A resposta da equipa a um pedido, enviada do support@ para a pessoa poder\nresponder na mesma conversa. A `resposta` vai cortada a 1500 caracteres e\nescapada — é texto da equipa, mas HTML de email não é sítio para surpresas."}]},{"nome":"worker/src/lib/enderecos.js","texto":"Os endereços @rendorium.com, geridos do back office.\n\nNão há caixas de correio: um endereço é uma REGRA de reencaminhamento no\nEmail Routing do Cloudflare — o que chega a nome@rendorium.com segue para\num destino verificado (o Gmail de quem gere). Por isso um endereço não\ntem palavra-passe: não há onde entrar. Enviar é outra história, e já\nestá resolvida — o Resend assina o domínio inteiro, e qualquer\nfrom@rendorium.com serve sem se criar nada aqui.\n\nFala-se com a API do Cloudflare com um token próprio (CF_EMAIL_TOKEN,\ncom Email Routing de zona em edição e Zone em leitura). Sem token, a\nsecção explica o que falta em vez de fingir que funciona.","funcoes":[{"nome":"cf","assinatura":"async function cf(env, caminho, metodo, corpo)","doc":"Uma chamada à API do Cloudflare, autenticada com o CF_EMAIL_TOKEN. Devolve\no corpo já como objeto quando o Cloudflare diz success; tudo o resto —\nHTTP falhado, resposta que não é JSON, success a false — vira um Error\ncom a mensagem deles (ou o código HTTP, quando nem mensagem há)."},{"nome":"zona","assinatura":"async function zona(env)","doc":"A zona e a conta descobrem-se pelo nome e ficam 1h no KV: com o token\nchega, sem ids para configurar à mão."},{"nome":"endereco","assinatura":"function endereco(nome)","doc":"aceita \"faturas\" ou \"faturas@rendorium.com\"; devolve o endereço completo\nou null se o nome não presta"},{"nome":"listarEnderecos","assinatura":"async function listarEnderecos(env)","doc":"O estado do Email Routing num só objeto: os endereços @rendorium.com (as\nregras com matcher literal no \"to\" — email, destino e se está ativa) e os\ndestinos da conta, cada um com a marca de verificado. Duas chamadas ao\nCloudflare em paralelo, sem cache: é sempre o estado real."},{"nome":"criarEndereco","assinatura":"async function criarEndereco(env, nome, destino)","doc":"Criar um endereço: recusa colisões (a regra que já existe diz para onde\nmanda), e só reencaminha para destinos verificados — um destino novo\nrecebe o email de verificação do Cloudflare e o endereço cria-se à\nsegunda, depois do clique."}]}]},{"id":"discord","titulo":"Discord (bot e papéis)","itens":[{"nome":"worker/src/discord.js","texto":"Bot do Discord, alojado no próprio worker: o Discord envia as interações\npor HTTP e nós respondemos. Duas vistas — quem programa trata dos pedidos\ne dos erros, quem opera vê o consumo da infraestrutura.","funcoes":[{"nome":"hex","assinatura":"hex (s)","doc":"Converte uma string hexadecimal (chave pública, assinatura) nos bytes correspondentes."},{"nome":"verifySignature","assinatura":"async function verifySignature(env, sig, ts, raw)","doc":"A assinatura Ed25519 do Discord é a única autenticação deste endpoint."},{"nome":"reply","assinatura":"reply (content, embeds)","doc":"Resposta efémera: só quem correu o comando a vê."},{"nome":"publico","assinatura":"publico (content, embeds, components)","doc":"Resposta à vista de todos no canal, com botões opcionais."},{"nome":"cut","assinatura":"cut (s, n)","doc":"Corta o texto a n caracteres, com reticências — o Discord recusa campos longos."},{"nome":"comoLista","assinatura":"comoLista (p)","doc":"Um papel ou vários: daqui para baixo aceita-se qualquer um dos dois."},{"nome":"nomeDoPapel","assinatura":"nomeDoPapel (p)","doc":"Os papéis por extenso, para as mensagens: \"admin + dev\", ou \"nenhum\"."},{"nome":"cor","assinatura":"cor (p)","doc":"A cor dos embeds segue o papel mais alto que a pessoa tem."},{"nome":"catsDe","assinatura":"function catsDe(pap)","doc":"As categorias que esta pessoa vê, somando os papéis que tiver."},{"nome":"lista","assinatura":"lista (v)","doc":"Parte uma variável de ambiente numa lista de ids (aceita vírgulas e espaços)."},{"nome":"pertence","assinatura":"function pertence(env, i, chave)","doc":"Diz se quem fala está na lista da variável de ambiente `chave`: pelo id de\npessoa ou por qualquer um dos cargos de Discord que tem."},{"nome":"papeisDe","assinatura":"function papeisDe(env, i)","doc":"Todos os papéis de quem está a falar, do mais alto para o mais baixo."},{"nome":"papel","assinatura":"function papel(env, i)","doc":"O papel principal, para mostrar e para dar cor: o mais alto que a pessoa tem."},{"nome":"podeCorrer","assinatura":"function podeCorrer(pap, comando, acessos)","doc":"O papel é a regra; as exceções por pessoa são o remendo. Passar `acessos`\né opcional de propósito: sem elas, isto continua a ser a função pura que\nos testes usam, e o comportamento é o do papel."},{"nome":"comandosDe","assinatura":"function comandosDe(pap, acessos)","doc":"Os comandos que esta pessoa pode correr, para o /comandos e para as recusas."},{"nome":"ticketEmbedFull","assinatura":"function ticketEmbedFull(t)","doc":"O embed completo de um pedido: estado, categoria, de quem veio e a resposta\njá dada. Fica cinzento quando concluído."},{"nome":"ticketButtons","assinatura":"function ticketButtons(id)","doc":"Os botões \"Em resolução\" e \"Concluir\" que acompanham um pedido; o id viaja\nno custom_id, para o clique saber de que pedido é."},{"nome":"acharTicket","assinatura":"async function acharTicket(env, ref)","doc":"Procura um pedido pelo id inteiro ou por um prefixo — as listas só mostram\nos primeiros 8 caracteres, e escrevê-los chega."},{"nome":"mudarEstado","assinatura":"async function mudarEstado(env, ref, estado, resposta, quem)","doc":"Também por aqui se escreve no fio e no rasto: uma resposta dada pelo\nDiscord que só mexesse na coluna reply ficava invisível no back office,\ne ninguém sabia que caminho a escreveu."},{"nome":"cmdPedidos","assinatura":"async function cmdPedidos(env, opts, pap)","doc":"/pedidos: até dez pedidos, do mais recente para trás, sempre dentro das\ncategorias que o papel vê. Sem filtros mostra o que está por tratar; aceita\nestado e categoria — e pedir uma categoria vedada é dito, não escondido."},{"nome":"fichaDe","assinatura":"async function fichaDe(env, userId)","doc":"Quem escreveu, e o que se sabe dele.\n\nO aviso que chega ao canal traz o nome; o /pedido, aberto mais tarde,\ntrazia só o id. Quem faz suporte estava a responder a uma pessoa de quem\nnão sabia nada — nem o plano, nem há quanto tempo era utilizador, nem se\njá tinha escrito antes."},{"nome":"campoDaFicha","assinatura":"function campoDaFicha(f)","doc":"A ficha de quem escreveu, como campo de embed: plano, antiguidade, casas, e\nos avisos que mudam a resposta. Devolve null quando não há ficha."},{"nome":"cmdPedido","assinatura":"async function cmdPedido(env, opts, pap)","doc":"/pedido: abre um pedido pelo id, com a ficha de quem escreveu no lugar do\ncampo \"De\" e os botões de mudar o estado."},{"nome":"cmdResponder","assinatura":"async function cmdResponder(env, opts, pap, quem)","doc":"/responder: escreve a resposta no pedido e marca-o em resolução; se for um\npedido de gente, a pessoa recebe a resposta por email e na app."},{"nome":"cmdFechar","assinatura":"async function cmdFechar(env, opts, pap, quem)","doc":"/fechar: dá o pedido por concluído, com resposta final se vier texto."},{"nome":"cmdErros","assinatura":"async function cmdErros(env, opts)","doc":"Os erros apanhados sozinhos vivem em `tickets` desde a migração 0008, com\na categoria a dizer de onde vieram. A tabela `reports` ficou para trás."},{"nome":"cmdCopias","assinatura":"async function cmdCopias(env, opts)","doc":"Ver as cópias que existem, ou forçar uma agora — antes de uma migração\narriscada, por exemplo, em vez de esperar pelas 09:00."},{"nome":"podeVer","assinatura":"function podeVer(pap, categoria)","doc":"Um pedido só se lê e se responde de dentro do papel a que pertence."},{"nome":"guardaDoPedido","assinatura":"async function guardaDoPedido(env, id, pap)","doc":"A guarda comum dos comandos que mexem num pedido: acha-o e confirma que o\npapel o pode ver. Devolve { t } com o pedido, ou { erro } com a recusa já\npronta a devolver ao Discord."},{"nome":"cmdComandos","assinatura":"function cmdComandos(pap, acessos)","doc":"/comandos: o que esta pessoa pode correr, com a nota do que lhe foi dado\npor exceção e as categorias de pedidos que vê."},{"nome":"cmdDocs","assinatura":"async function cmdDocs(env, i, papeis)","doc":"/docs: a mesma entrada do /entrar, mas a aterrar na documentação — um\ncomando, zero passos intermédios. O bilhete é igual ao do /entrar (cinco\nminutos, uma utilização) e o destino vem de uma lista fechada."},{"nome":"cmdEntrar","assinatura":"async function cmdEntrar(env, i, papeis, request)","doc":"Uma ligação de uso único para a ferramenta de equipa.\n\nA resposta é sempre privada (flags 64): a ligação vale por uma sessão, e\num canal partilhado não é sítio para ela. O endereço sai do próprio pedido,\npor isso o bot de dev dá uma ligação para o dev e o de produção para\nprodução, sem ninguém ter de configurar nada."},{"nome":"cmdTest","assinatura":"async function cmdTest(env, i, opts, request)","doc":"Uma ligação para o ambiente de TESTE — nunca para produção. O bot de dev\naponta a si próprio; o de produção (quem responde ao Discord depois da\npromoção) aponta ao dev, porque o /t/entrar de produção nem existe.\nAbrir a ligação lava as contas de teste e entra numa fresca."},{"nome":"GERIVEIS","assinatura":"GERIVEIS ()","doc":"Os comandos que se gerem aqui. Os do master ficam de fora de propósito."},{"nome":"menuAcesso","assinatura":"function menuAcesso(alvoId, papeis, acessos)","doc":"Os componentes do /access: um menu de escolha múltipla com o estado de cada\ncomando gerível (o que vem do cargo já vem marcado) e o botão de repor tudo\nao cargo."},{"nome":"vistaAcesso","assinatura":"function vistaAcesso(alvoId, papeis, acessos)","doc":"A mensagem inteira: o menu é o que se mexe, o embed é o que explica.\n\nO menu sozinho mostra o que está ligado mas não de onde vem, e essa é a\nparte que interessa a quem gere — daí os dois juntos."},{"nome":"cmdAccess","assinatura":"async function cmdAccess(env, i, opts)","doc":"/access: mostra quem pode o quê para a pessoa escolhida, com o menu para\ndar e tirar comandos. Só o master cá chega."},{"nome":"papeisDoAlvo","assinatura":"async function papeisDoAlvo(env, i, alvoId, guardados)","doc":"Os cargos do alvo, perguntados ao Discord no momento de gravar.\n\nOs que viajaram na mensagem podem estar velhos — o cargo pode ter mudado\nentre abrir o menu e mexer nele — e gravar exceções contra um cargo velho\ndava exceções erradas. Se a pergunta não der, vale o que veio na mensagem:\né melhor do que recusar o clique."},{"nome":"acessoInteracao","assinatura":"async function acessoInteracao(env, i, meus, cid)","doc":"Trata os cliques na mensagem do /access: o botão repõe tudo ao cargo, o\nmenu grava a diferença entre o que ficou marcado e o que o cargo dá.\nEscreve na base, deixa rasto na auditoria, e substitui a mensagem pela\nvista nova."},{"nome":"cmdUso","assinatura":"async function cmdUso(env)","doc":"/uso: o consumo da infraestrutura neste momento, num embed."},{"nome":"cmdResumo","assinatura":"async function cmdResumo(env, ctx)","doc":"/resumo: envia já o resumo diário para o canal de administração, sem\nesperar pela hora marcada."},{"nome":"quemFala","assinatura":"function quemFala(i, pap)","doc":"Quem está a falar, para o fio e para o rasto."},{"nome":"handleInteraction","assinatura":"async function handleInteraction(request, env, ctx)","doc":"A porta de entrada de todas as interações do Discord: verifica a assinatura,\nresponde ao ping, e encaminha botões, menus e comandos — cada um atrás da\npergunta \"este papel pode?\". Devolve sempre a Response JSON que o Discord\nespera; um erro num comando vira mensagem, não um 500."},{"nome":"postAsBot","assinatura":"async function postAsBot(env, channelId, payload)","doc":"Mensagem num canal usando o bot (permite botões, ao contrário do webhook)."}]},{"nome":"worker/src/acessos.js","texto":"Acessos dados ou retirados a uma pessoa em concreto.\n\nO papel continua a ser a regra: é dele que vem quase tudo, e é o que se\ngere no Discord com cargos. Isto é a exceção — dar a alguém um comando que\no papel não dá, ou tirar-lhe um que dá, sem ter de inventar um cargo novo\npara uma pessoa só.\n\nAs exceções vivem no KV e são lidas em cada interação. São poucas por\nnatureza: se um dia forem muitas, isso quer dizer que falta um cargo, não\nque falta espaço aqui.","funcoes":[{"nome":"chave","assinatura":"chave (discordId)","doc":"A chave no KV onde vivem as exceções desta pessoa."},{"nome":"lerAcessos","assinatura":"async function lerAcessos(env, discordId)","doc":"As exceções desta pessoa, lidas do KV. Devolve sempre {mais, menos}: sem\nentrada, sem KV ou com lixo lá dentro, sai o vazio — e vale só o papel."},{"nome":"guardarAcessos","assinatura":"async function guardarAcessos(env, discordId, acessos)","doc":"Grava as exceções no KV, sem duplicados, e devolve o que ficou. Sem\nnenhuma exceção apaga a entrada — ausência e vazio são a mesma coisa."},{"nome":"origemDoAcesso","assinatura":"function origemDoAcesso(pap, comando, acessos, regras)","doc":"De onde vem o acesso a um comando, para se poder mostrar e não só decidir.\n\n'papel'    vem do cargo — é o que se marca como (predefinido)\n'dado'     acrescentado a esta pessoa\n'retirado' tirado a esta pessoa\n'nao'      nem o papel dá nem foi acrescentado"},{"nome":"excecoesDoMenu","assinatura":"function excecoesDoMenu(marcados, geriveis, vemDoCargo)","doc":"Do que ficou marcado no menu para as exceções a guardar.\n\nÉ a única parte do menu de caixas que decide alguma coisa: guarda-se a\ndiferença para o cargo, não a lista marcada. Assim, mudar o cargo de\nalguém no Discord continua a mudar-lhe os acessos — o que ficou aqui é só\naquilo em que esta pessoa difere do cargo dela."}]},{"nome":"scripts/discord-register.js","texto":"Regista os comandos do bot no Discord.\n\nDISCORD_APP_ID=... DISCORD_BOT_TOKEN=... [DISCORD_GUILD_ID=...] \\\nnode scripts/discord-register.js\n\nCom DISCORD_GUILD_ID, os comandos aparecem de imediato nesse servidor.\nSem ele, ficam globais e podem demorar até uma hora a aparecer.","funcoes":[{"nome":"registar","assinatura":"registar (url)","doc":"PUT da lista completa de comandos no endereço dado — o Discord substitui o\nque lá estava. Devolve { ok, status, texto } em vez de lançar, para quem\nchama poder tentar o registo global a seguir."}]},{"nome":"scripts/discord-comandos.js","texto":"Pergunta ao Discord que comandos tem registados, no servidor e globais.\n\nDISCORD_APP_ID=... DISCORD_BOT_TOKEN=... [DISCORD_GUILD_ID=...] \\\nnode scripts/discord-comandos.js\n\nServe para responder a \"o comando não aparece\" com um facto em vez de um\npalpite: ou está registado e é a aplicação que não o mostra, ou nunca lá\nchegou. São problemas diferentes.","funcoes":[{"nome":"pedir","assinatura":"pedir (url)","doc":"GET à API do Discord com o token do bot. Devolve {ok, estado, corpo} com\no corpo em texto cru — em erro é isso mesmo que se quer mostrar."},{"nome":"mostrar","assinatura":"function mostrar(titulo, r)","doc":"Imprime a lista de comandos de uma resposta do pedir e devolve os nomes,\npara se poderem comparar servidor e globais. Em erro diz o que veio e devolve []."}]}]},{"id":"equipa","titulo":"Back office (/equipa)","itens":[{"nome":"worker/src/equipa.js","texto":"Sessões de quem trabalha no serviço.\n\nEntra-se a partir do Discord e mais lado nenhum. Quem faz suporte corre\n/entrar no servidor, o bot responde com uma ligação de uso único, e essa\nligação cria a sessão. Não há botão de \"entrar com Discord\" no ecrã de\nquem usa a app, nem sequer uma página onde tentar.\n\nPorquê assim e não por OAuth: a interação do Discord já traz quem é\n(i.member.user.id) e que cargos tem (i.member.roles), assinada com a\nchave do Discord. Um OAuth pediria à pessoa uma autorização para saber o\nque o bot já sabe, e obrigaria a expor um endereço de entrada.\n\nA sessão de equipa é deliberadamente separada da de quem usa a app: outro\ncookie, outro espaço no KV, outra função de leitura. Nenhuma das duas se\npode fazer passar pela outra.","funcoes":[{"nome":"novoToken","assinatura":"function novoToken()","doc":"32 bytes de aleatório criptográfico em hexadecimal (64 caracteres):\nserve de bilhete e de token de sessão."},{"nome":"criarBilhete","assinatura":"async function criarBilhete(env, quem)","doc":"Um bilhete de uso único, criado a pedido do bot. Guarda quem é e que papel\ntinha no momento — o papel volta a ser verificado quando a sessão é usada,\nmas isto deixa o registo do que se passou.\n\nVive na base e não no KV, ao contrário da sessão que dele nasce. É a\núnica coisa aqui que se escreve num sítio e se lê noutro: o bot é\natendido perto do Discord e o clique perto de quem clica. O KV leva algum\ntempo a concordar consigo próprio entre regiões, e nesse intervalo uma\nligação acabada de criar não existe para quem a abre."},{"nome":"verBilhete","assinatura":"async function verBilhete(env, t)","doc":"O que uma ligação é, sem lhe mexer. Mostrar não é usar: a página de\nentrada precisa de saber a quem pertence, e não pode gastá-la só por\nalguém — ou alguma coisa — a ter aberto."},{"nome":"usarBilhete","assinatura":"async function usarBilhete(env, t)","doc":"Gastar a ligação. Numa só instrução de propósito: com ler-e-depois-apagar,\ndois pedidos ao mesmo tempo liam ambos a mesma ligação por usar e entravam\nos dois. Assim, quem marcar a linha primeiro é o único que entra."},{"nome":"cookieDaEquipa","assinatura":"function cookieDaEquipa(token, expirar false)","doc":"A linha Set-Cookie da sessão de equipa. Com expirar=true sai com\nMax-Age=0, que é como se apaga um cookie HttpOnly."},{"nome":"lerCookie","assinatura":"function lerCookie(request, nome)","doc":"O valor do cookie `nome`, mas só se tiver a forma de um token nosso\n(64 hex) — qualquer outra coisa vale null e nem chega a tocar no KV."},{"nome":"getEquipa","assinatura":"async function getEquipa(env, request)","doc":"Quem está a usar a ferramenta de equipa, ou null.\nSó lê o cookie da equipa: uma sessão de cliente nunca dá acesso a isto."},{"nome":"rotasEquipa","assinatura":"async function rotasEquipa(c)","doc":"As rotas de entrar e sair da ferramenta de equipa. Devolve a Response, ou\nnull quando o pedido não é daqui e o worker deve seguir para as outras\nrotas. O que a ferramenta faz por dentro vive no equipa-api.js — aqui é\nsó a porta."}]},{"nome":"worker/src/equipa-api.js","texto":"O que a ferramenta de equipa pode fazer.\n\nAs mesmas regras do bot, pelos mesmos papéis: o suporte vê os pedidos\ncontados por pessoas, quem programa vê os erros, quem opera vê as\nmáquinas — e nenhum vê o canto dos outros. A diferença é a forma: aqui\nprocura-se e navega-se, que é o que um canal de Discord não sabe fazer.\n\nNada aqui devolve dados de imóveis, contratos ou movimentos. Quem faz\nsuporte precisa de saber com quem fala e o que essa pessoa escreveu, não\nde lhe ver as contas.\n\nDesde que isto ganhou poderes de escrita, vale uma regra sem exceções:\ntoda a ação que muda alguma coisa escreve primeiro no audit_log. Nas\nações sobre contas é mesmo primeiro — se o rasto não se conseguir\nescrever, a ação não acontece. Mexer numa conta sem deixar registo é o\ngénero de atalho que só se nota quando já ninguém sabe o que se passou.","funcoes":[{"nome":"cortar","assinatura":"cortar (s, n)","doc":"Corta a `n` caracteres com reticências — para os resumos que vão para o rasto."},{"nome":"categoriasDe","assinatura":"function categoriasDe(eu)","doc":"A mesma regra do bot, e de propósito a mesma função: duas cópias disto\nacabavam a discordar uma da outra na primeira mudança de papéis."},{"nome":"eMaster","assinatura":"eMaster (eu)","doc":"As ações sobre contas são só do master. Não por desconfiança dos outros —\npor serem as únicas ações daqui que mexem na vida de quem usa a app, e\nisso quer um responsável único enquanto a equipa couber numa mão."},{"nome":"ficha","assinatura":"async function ficha(env, userId)","doc":"A ficha de quem escreveu. É a mesma informação que o bot mostra, e pela\nmesma razão: responder sem saber quem é a pessoa é responder às cegas."},{"nome":"ficha360","assinatura":"async function ficha360(env, userId)","doc":"O resto da vista a 360º: só na página da pessoa, porque são mais seis\nconsultas e a ficha básica também serve dentro de cada pedido."},{"nome":"rotasEquipaApi","assinatura":"async function rotasEquipaApi(c)","doc":"As rotas /api/equipa que fazem o trabalho: pedidos, pessoas, contas,\nendereços, operação e rasto. Chega cá com `eu` — a sessão de equipa — já\nverificado; tudo o que devolve passa primeiro pelo filtro das categorias\ndo papel, e as ações sensíveis pelo eMaster. Devolve a Response, ou null\nquando a rota não é daqui."}]},{"nome":"worker/src/equipa-vista.js","texto":"A página da ferramenta de equipa.\n\nServida pelo worker e não pelos ficheiros da app: quem faz suporte não\ncarrega a aplicação de quem a usa, nem partilha código com ela. São duas\ncoisas com públicos diferentes, e mantê-las separadas evita que um dia\numa sessão de equipa consiga chamar alguma coisa da outra.\n\nÉ uma página escrita à mão, sem dependências. Cresceu de fila de pedidos\npara back office — pedidos, erros, pessoas, operação e rasto — mas o\nprincípio mantém-se: uma ferramenta usada por meia dúzia de pessoas não\njustifica mais do que isto.","funcoes":[{"nome":"pagina","assinatura":"function pagina(corpo, titulo)","doc":"Embrulha o corpo no documento HTML completo: <head>, tema claro e escuro,\ne os estilos da ferramenta inteira. Todas as páginas da equipa — a própria\nferramenta, o ecrã de entrada — passam por aqui."},{"nome":"paginaEquipa","assinatura":"function paginaEquipa(eu)","doc":"Quem não tem sessão não vê a ferramenta, nem sabe o que lá está."},{"nome":"pedir","assinatura":"function pedir(rota, opcoes)","doc":"fetch com as regras da casa: cookies de sessão, resposta lida como JSON,\num 401 recarrega a página (a sessão morreu, volta-se ao ecrã de entrada)\ne qualquer outro falhanço vira Error com a mensagem do servidor"},{"nome":"enviar","assinatura":"function enviar(rota, corpo)","doc":"POST em JSON por cima de pedir; sem corpo vai um {} vazio"},{"nome":"sair","assinatura":"function sair()","doc":"termina a sessão de equipa no servidor e recarrega — cai no ecrã de entrada"},{"nome":"falha","assinatura":"function falha(e)","doc":"mostra a mensagem do erro no lugar do conteúdo (o .catch das vistas)"},{"nome":"aCarregar","assinatura":"function aCarregar()","doc":"substitui o conteúdo pelo \"A carregar…\" enquanto a rede responde"},{"nome":"selo","assinatura":"function selo(p)","doc":"o distintivo de estado de um pedido: verde concluído, âmbar em resolução"},{"nome":"nav","assinatura":"function nav(ativa)","doc":"pinta os separadores do cabeçalho — só os que os papéis deixam ver —\ne marca o ativo; guarda a secção atual em seccao"},{"nome":"ir","assinatura":"function ir(s)","doc":"muda de secção: marca o separador e abre a vista respetiva"},{"nome":"verLista","assinatura":"function verLista(tipo, e, q)","doc":"A lista de pedidos (tipo 'pessoas') ou de erros (tipo 'erros'), filtrada\nno servidor: e é o estado ('abertos' ou '' para todos) e q o texto da\nprocura, feita com Enter no campo. O filtro fica na variável estado para\na procura não o perder; cada cartão abre o detalhe."},{"nome":"verPedido","assinatura":"function verPedido(id)","doc":"O detalhe de um pedido: o texto e o contexto, a ficha de quem escreveu,\no fio de respostas e notas internas, os outros pedidos da mesma pessoa\ne a caixa de responder com as respostas-tipo. Os modelos carregam-se à\nprimeira vez e ficam em cache na variável modelos."},{"nome":"agir","assinatura":"function agir(id, acao)","doc":"executa uma ação sobre o pedido (responder, fechar, nota, atribuir,\nreabrir) com o texto da caixa; responder e nota exigem texto escrito"},{"nome":"mudarCategoria","assinatura":"function mudarCategoria(id)","doc":"muda a categoria do pedido para a escolhida no seletor e reabre o detalhe"},{"nome":"usarModelo","assinatura":"function usarModelo()","doc":"copia a resposta-tipo escolhida para a caixa, por cima do que lá estiver"},{"nome":"guardarModelo","assinatura":"function guardarModelo()","doc":"guarda o texto da caixa como resposta-tipo nova (o nome vem de um prompt)\ne deita fora a cache, para a lista vir fresca no próximo pedido"},{"nome":"verPessoas","assinatura":"function verPessoas(q)","doc":"A procura de contas por email, nome ou id. Só vai à rede com 3 ou mais\ncaracteres — menos que isso era pedir meia base de dados. Cada resultado\nabre a ficha; o master tem ainda o botão de criar conta."},{"nome":"criarConta","assinatura":"function criarConta()","doc":"Criar uma conta à mão: para a equipa, para um teste com email verdadeiro,\npara quem pede ajuda a entrar. O servidor recusa emails repetidos."},{"nome":"verPessoa","assinatura":"function verPessoa(id)","doc":"A ficha completa de uma conta: dados e atividade, ligações e partilhas,\npropostas de quotas pendentes, limites ativos e os pedidos que fez.\nO cartão de ações só aparece quando o servidor diz que quem vê é master."},{"nome":"cartaoAcoes","assinatura":"function cartaoAcoes(q)","doc":"As ações sobre a conta. Cada uma pede o motivo — é o que daqui a seis\nmeses distingue \"porque foi preciso\" de \"ninguém sabe\"."},{"nome":"acaoConta","assinatura":"function acaoConta(id, acao)","doc":"Dispara uma ação de master sobre a conta. Umas pedem primeiro um valor\n(plano, email, palavra-passe; apagar pede o email exato da conta como\nconfirmação) e todas pedem o motivo — sem motivo não acontece nada."},{"nome":"verOperacao","assinatura":"function verOperacao()","doc":"O painel de operação inteiro: modo de demonstração, sessão de teste (fora\nde produção), o batimento das operações agendadas, os endereços de email,\nas cópias no R2 com o histórico e o consumo. Os endereços chegam à parte,\npor verEnderecos — o resto do painel não fica à espera do Cloudflare."},{"nome":"mudarDemo","assinatura":"function mudarDemo(ligar)","doc":"ligar=true volta ao modo demo (ou cancela o fim marcado); false marca o\nfim, com confirmação — a app passa logo a avisar toda a gente. O motivo\nfica no rasto."},{"nome":"verEnderecos","assinatura":"function verEnderecos()","doc":"Preenche o cartão dos endereços de email: cada um com o destino para onde\nreencaminha, mais os destinos ainda por verificar. Sem CF_EMAIL_TOKEN no\nservidor, escreve a receita para o criar em vez de fingir que funciona."},{"nome":"criarEndereco","assinatura":"function criarEndereco()","doc":"pede por prompt o nome, o destino (vazio usa o já verificado) e o motivo,\ne cria o endereço; mesmo em erro recarrega a lista — o servidor pode ter\nposto um destino novo à espera de verificação"},{"nome":"sessaoTeste","assinatura":"function sessaoTeste(comDados, manter, limpar)","doc":"Pede uma ligação de sessão de teste — a mesma que o /test do Discord dá.\ncomDados semeia dados de exemplo, manter cria uma conta extra em vez de\nretomar a mais recente, limpar apaga as contas de teste de quem pede\n(com confirmação). A ligação vale 10 minutos e aparece no cartão."},{"nome":"copiarAgora","assinatura":"function copiarAgora()","doc":"dispara uma cópia manual da base para o R2, com confirmação; no fim\ndiz as linhas e o tamanho, e recarrega o painel"},{"nome":"resumoCopia","assinatura":"function resumoCopia(dia)","doc":"A verificação de uma cópia: descomprime no servidor, conta por tabela, e\ncompara com a base viva. Uma cópia truncada rebenta na descompressão; uma\ncoxa aparece aqui com as contagens a divergir."},{"nome":"verRasto","assinatura":"function verRasto(alvo)","doc":"a auditoria: as últimas 200 ações da equipa, opcionalmente filtradas por\nalvo. Só leitura — o rasto escreve-se sempre e não se apaga nunca."},{"nome":"paginaEntrada","assinatura":"function paginaEntrada(token, v, depois)","doc":"A página que a ligação do Discord abre.\n\nAbrir não entra. Mostra quem é e põe um botão — e é o botão que gasta a\nligação. É o que impede que uma pré-visualização, um leitor de links ou o\nbrowser a adiantar-se gastem a ligação antes da pessoa lá chegar.\n\nO endereço leva o token, por isso a página não pode deixar sair um\nreferer nem ficar em cache."},{"nome":"escapar","assinatura":"function escapar(s)","doc":"escapa HTML para as interpolações destas páginas (do lado do cliente\nexiste o gémeo, esc)"}]},{"nome":"worker/src/docs-vista.js","texto":"A documentação da casa, servida em /equipa/docs.\n\nNão se escreve documentação aqui: ela vem do próprio código — o\ncomentário de abertura de cada ficheiro e o comentário de cada função,\nextraídos no deploy pelo scripts/gerar-docs.js e organizados por\nFUNCIONALIDADE. A página é para um programador que chegue de novo:\ngaveta de navegação à esquerda, o interface de cada função (assinatura\n+ documentação) no meio, e uma pesquisa que atravessa tudo.\n\nÉ da equipa: pede a mesma sessão que o resto do /equipa.","funcoes":[{"nome":"esc","assinatura":"esc (s)","doc":"Escapa &, < e > para HTML; null e undefined viram ''."},{"nome":"prosa","assinatura":"prosa (t)","doc":"os comentários são prosa: quebras duplas separam parágrafos, simples juntam"},{"nome":"paginaDocs","assinatura":"function paginaDocs()","doc":"Monta a página inteira — gaveta, comandos, capítulos, pesquisa — a partir\ndo DOCS gerado no deploy, e devolve-a como Response HTML sem cache. Tudo\ninline: a página não volta a pedir nada ao servidor, e a pesquisa corre no\nbrowser sobre o próprio DOM."}]}]},{"id":"teste","titulo":"Ambiente de teste (/test)","itens":[{"nome":"worker/src/teste.js","texto":"O ambiente de teste, a um /test de distância.\n\nO comando /test no Discord responde com uma ligação temporária para o\nambiente de dev. Abri-la faz três coisas, por esta ordem: apaga as contas\nde teste anteriores (cada visita começa lavada), cria uma conta de teste\nnova, e entra com ela — com ou sem dados de exemplo.\n\nA ligação é um bilhete ASSINADO, não um estado: HMAC sobre a validade e\nas opções, com uma chave derivada do token do bot do Discord — o único\nsegredo que os dois ambientes já partilham. Assim o worker de produção\n(que é quem responde ao Discord depois da promoção) consegue emitir\nligações para o dev sem os dois falarem um com o outro.\n\nNada disto existe em produção: sem ENV_NAME, a rota é um 404 e ponto —\nprodução nunca cria contas de teste, venha a assinatura de onde vier.","funcoes":[{"nome":"chave","assinatura":"async function chave(env)","doc":"A chave das ligações de teste. Com os bots de dev e produção separados,\no token do bot deixou de ser partilhado — a TESTE_CHAVE (a mesma nos dois\nambientes) é o que deixa o /test de qualquer servidor assinar ligações\nque o worker de dev aceita. Sem ela, vale o token do bot, como dantes."},{"nome":"assinarTeste","assinatura":"async function assinarTeste(env, exp, dados, manter, quem, limpar, email)","doc":"A assinatura HMAC-SHA256, em hexadecimal, dos campos de uma ligação de\nteste — na ordem fixa em que o rotaTeste os volta a verificar. Os campos\nvazios também contam: mudar qualquer um muda a assinatura."},{"nome":"ligacaoTeste","assinatura":"async function ligacaoTeste(env, base, comExemplo, manter, quem, limpar, email)","doc":"As contas de teste são PERSISTENTES: por omissão a ligação retoma a conta\nmais recente do dono (os dados ficam de um dia para o outro); `manter`\ncria uma extra; `limpar` é a única coisa que apaga. O `email` do dev vai\nassinado dentro da ligação — quem a abre grava-o no KV do ambiente de\nteste, e é para lá que segue o correio das contas dele."},{"nome":"criarContaDeTeste","assinatura":"async function criarContaDeTeste(env, quem)","doc":"A conta de teste em si: email no subdomínio, palavra-passe impossível,\ntermos aceites, e o dono (o dev que a pediu) gravado para o seletor."},{"nome":"pagina","assinatura":"function pagina(status, titulo, texto)","doc":"Quem abre esta rota é uma pessoa num browser: os erros são uma página\nque se lê, não um JSON que se decifra."},{"nome":"rotaTeste","assinatura":"async function rotaTeste(c)","doc":"A rota /t/entrar: valida a validade e a assinatura e, conforme as opções\nda ligação, limpa as contas do dono, retoma a mais recente ou cria uma\nnova — e entra com ela (302 com cookie de sessão). Os erros são páginas\nlegíveis, porque quem abre isto é uma pessoa num browser. Fora do\nambiente de teste é sempre 404, venha a assinatura de onde vier."},{"nome":"proximaContaDeTeste","assinatura":"async function proximaContaDeTeste(env, dono)","doc":"Depois de se apagar uma conta de teste, a sessão seguinte: a irmã mais\nrecente do mesmo dono — ou, se não sobrar nenhuma, uma acabada de criar.\nQuem testa o \"apagar conta\" não pode aterrar no ecrã de login de um\nambiente onde nem sequer há formulário que lhe valha."},{"nome":"rotasContasDeTeste","assinatura":"async function rotasContasDeTeste(c)","doc":"o seletor de contas do ambiente de dev\nTrês rotas com sessão, só fora de produção e só para contas de teste COM\ndono: listar as contas do mesmo dev, trocar para uma delas, e criar uma\nextra. A afinidade é o test_owner — cada dev vê e toca só nas suas."}]}]},{"id":"planos","titulo":"Limites e fim da demonstração","itens":[{"nome":"worker/src/lib/planos.js","texto":"Os planos, com dentes.\n\nO campo users.plan existia e nada o lia na hora de decidir. Aqui vive a\nregra: o que cada plano deixa CRIAR. Nunca o que deixa ver — os termos\nprometem que nada do que existe é apagado ou fica inacessível, e o código\ntem de cumprir a promessa.\n\nO interruptor do modo de demonstração suspende os limites todos. Vive no\nKV e só o master lhe toca, pelo back office. Enquanto estiver ligado, a\napp comporta-se como sempre se comportou; desligá-lo é o momento em que\nos planos passam a valer.","funcoes":[{"nome":"fimDemo","assinatura":"async function fimDemo(env)","doc":"Desligar o demo não desliga nada no momento: marca a DATA em que os\nlimites entram em vigor, 30 dias à frente por omissão. Até lá, tudo se\ncomporta como sempre — mas a app passa a avisar toda a gente do que aí\nvem, e é esse aviso que os termos prometem. Voltar a ligar apaga a data.\n\nUma leitura de KV por pedido chegava; com a cache nem isso. Sem KV ou sem\ndata marcada, é demo: nunca se tranca clientes por um outage."},{"nome":"modoDemo","assinatura":"async function modoDemo(env)","doc":"Ainda estamos em demonstração? true enquanto não houver data de fim\nmarcada, ou enquanto ela não chegar. É isto que suspende os limites."},{"nome":"definirDemo","assinatura":"async function definirDemo(env, ligado, dias)","doc":"Liga ou desliga o modo de demonstração. Ligar apaga a data marcada;\ndesligar marca o fim para daqui a `dias` (30 por omissão) — só nessa data\né que os limites passam a valer. Escreve no KV, atualiza a cache, e\ndevolve a data marcada (ou null quando fica ligado)."},{"nome":"esquecerCache","assinatura":"function esquecerCache()","doc":"exposto para os testes poderem limpar a cache entre casos"},{"nome":"podeCriar","assinatura":"function podeCriar(plan, tipo, imoveisAtuais)","doc":"O veredicto sobre criar mais um. `tipo`: 'imovel' | 'contract' | 'rec'.\nDevolve null quando pode, ou a frase que explica porquê não."}]},{"nome":"worker/src/lib/limites.js","texto":"Travão contra força bruta e abuso. Os contadores vivem na D1: o KV gratuito\nsó aceita mil escritas por dia e cada gravação de dados gastava uma.","funcoes":[{"nome":"rateLimit","assinatura":"async function rateLimit(env, key, limit, windowSec)","doc":"Conta mais um acontecimento na chave e diz se ainda cabe: true deixa\npassar, false é para responder 429. A janela é fixa — windowSec segundos a\ncontar do primeiro acontecimento — e cada chamada gasta uma escrita na D1.\nSe a base falhar, deixa passar: um contador em baixo não pode deitar o\nserviço abaixo."}]}]},{"id":"anexos","titulo":"Anexos e ficheiros","itens":[{"nome":"worker/src/files.js","texto":"Anexos: o conteúdo vive no R2, os metadados na D1. Quem pode ver um anexo\né quem pode ver a casa a que ele pertence; enquanto não estiver guardado\nnuma casa, só quem o carregou.","funcoes":[{"nome":"fileIdsIn","assinatura":"function fileIdsIn(data)","doc":"Percorre um registo à procura dos anexos que ele refere."},{"nome":"linkFiles","assinatura":"async function linkFiles(env, houseId, data)","doc":"Depois de guardar uma casa ou um registo, os anexos que ele refere passam a\npertencer-lhe — é isto que os torna visíveis a quem partilha a casa."},{"nome":"podeVer","assinatura":"async function podeVer(env, me, row, canAccessHouse)","doc":"A regra de acesso a um anexo: o dono vê sempre; guardado numa casa, vê\nquem tiver acesso à casa; solto e de outra pessoa, ninguém."},{"nome":"handleFiles","assinatura":"async function handleFiles(request, env, me, seg, method, deps)","doc":"As rotas /api/files/:id. PUT carrega (o corpo para o R2, os metadados\npara a D1, com os limites de tamanho e o id preso ao primeiro dono); GET\ndevolve o conteúdo com o tipo e o nome originais; DELETE apaga dos dois\nlados. O GET responde 404 tanto ao que não existe como ao que não se pode\nver — não se confirma a existência do que é dos outros."}]},{"nome":"worker/src/rotas/anexos.js","texto":"Anexos: o conteudo vive no R2, o acesso segue a casa.","funcoes":[{"nome":"rotasAnexos","assinatura":"async function rotasAnexos(c)","doc":"Rota dos anexos (/api/files/:id): entrega tudo ao handleFiles, que fala com\no R2 e verifica o acesso pela casa a que o ficheiro pertence."}]},{"nome":"web/cloud/anexos.js","texto":"Anexos: sobem para o servidor e voltam de la quando faltam no aparelho.","funcoes":[{"nome":"casaDoAnexo","assinatura":"function casaDoAnexo(id)","doc":"a que casa pertence um anexo, procurando quem o refere"},{"nome":"subirAnexo","assinatura":"function subirAnexo(id, blob)","doc":"Sobe um anexo para o servidor (PUT /api/files/:id), a indicar a casa a que pertence\npara quem recebe a partilha o poder ler. Ignora miniaturas e uploads já em curso.\nSem rede fica tudo local e tenta-se de novo na próxima sincronização; uma recusa do\nservidor (grande de mais, sem permissão) avisa por toast, mas só uma vez por sessão."},{"nome":"baixarAnexo","assinatura":"function baixarAnexo(id)","doc":"Vai buscar ao servidor um anexo que falta neste aparelho; guarda-o no IndexedDB para\na próxima vez e devolve o blob — ou null sem sessão, sem rede ou sem o ficheiro lá."},{"nome":"subirPendentes","assinatura":"function subirPendentes()","doc":"Depois de sincronizar, sobe o que ainda só existe neste aparelho."},{"nome":"decorateShared","assinatura":"function decorateShared()","doc":"Depois de cada render, pendura o distintivo \"de <nome>\" nos cartões das casas\nque outra pessoa partilhou connosco (mexe no DOM já desenhado, sem re-render)."},{"nome":"rememberPage","assinatura":"function rememberPage()","doc":"Guarda em localStorage o separador atual (e a sub-página das definições), para o restorePage."},{"nome":"restorePage","assinatura":"function restorePage()","doc":"No arranque, devolve o utilizador ao separador onde estava; ignora estados\nguardados que já não existem e não faz nada quando era só o painel inicial."}]},{"nome":"web/app/anexos.js","texto":"ANEXOS (IndexedDB)","funcoes":[{"nome":"idb","assinatura":"function idb()","doc":"Abre (uma só vez) a base 'gi_files' do IndexedDB e devolve a ligação; rejeita quando o browser não deixa."},{"nome":"allFileMetas","assinatura":"function allFileMetas()","doc":"Os metadados de todos os anexos referidos nos dados gravados: contratos, fotos e\nhipotecas dos imóveis, documentos de pessoas. É a lista do que deve existir em disco."},{"nome":"cleanFiles","assinatura":"function cleanFiles()","doc":"Apaga do IndexedDB os blobs que já nada refere, poupando os pendentes dos\nformulários ainda abertos. Corre em fundo e falha em silêncio."},{"nome":"takeFiles","assinatura":"function takeFiles(input)","doc":"Lê ficheiros do <input>, guarda os blobs e devolve os metadados."},{"nome":"openFileMeta","assinatura":"function openFileMeta(meta)","doc":"Abre um anexo a partir dos metadados: imagens em modal com botão de guardar,\no resto descarrega logo. Avisa por toast quando o blob não está no aparelho."},{"nome":"downloadMeta","assinatura":"function downloadMeta(fid)","doc":"Descarrega o anexo com o nome original, através de um <a download> temporário."},{"nome":"pendingMetas","assinatura":"function pendingMetas()","doc":"Os anexos ainda nos formulários abertos (contrato, imóvel, pessoa, hipotecas):\njá têm blob guardado, mas os metadados ainda não chegaram a db."}]}]},{"id":"infra","titulo":"Infraestrutura","itens":[{"nome":"worker/src/index.js","texto":"Worker do Rendorium (nome interno: gestor-imobiliario): /api/* vai para a API (D1 + KV);\ntudo o resto é servido pelos assets estáticos (a PWA em web/).","funcoes":[{"nome":"harden","assinatura":"function harden(res)","doc":"Veste uma resposta com os cabeçalhos de segurança antes de sair; só os\nvalores exactos em PODE_APERTAR escapam a ser substituídos. Devolve uma\nResponse nova — a original não se volta a usar."}]},{"nome":"worker/src/api.js","texto":"API REST do Rendorium.\n\nModelo de dados: cada utilizador é dono das suas casas; os registos\n(inquilinos, contratos, movimentos, ...) pertencem a uma casa. Um utilizador\npode ligar-se a outro através do id curto e, dentro dessa conexão, cada um\nescolhe que casas partilha. Casas partilhadas são visíveis e editáveis pelo\noutro utilizador; apagar a casa ou gerir a partilha é só do dono.\n\nEste ficheiro é só o encaminhador: monta o contexto, corre as rotas por\nordem e devolve a primeira resposta. Cada área vive no seu módulo, em\nrotas/, e os ajudantes partilhados em lib/.","funcoes":[{"nome":"handleApi","assinatura":"async function handleApi(request, env, ctx)","doc":"Ponto de entrada de todos os /api: normaliza o caminho, monta o contexto\npartilhado e corre as rotas por ordem — primeiro as que dispensam sessão\n(autenticação e relatos de erro), depois, já com o utilizador resolvido,\nas de COM_SESSAO. A primeira Response ganha; sem nenhuma, 404."}]},{"nome":"worker/src/landing.js","texto":"A página de entrada do rendorium.com.\n\nServida pelo worker quando o pedido chega pelo domínio raiz (ou www) —\na app vive em app.rendorium.com e não se mistura. É uma página escrita à\nmão, sem dependências, com a mesma cara da app: quem clica em \"Abrir a\napp\" não pode sentir que mudou de produto.\n\nO Rendorium é um projeto pessoal, sem planos nem pagamentos — a página\ndiz o que a ferramenta faz e mais nada. As funcionalidades vivem num\ncarrossel: no telemóvel desliza-se, no computador há setas e pontos.","funcoes":[{"nome":"paginaLanding","assinatura":"function paginaLanding()","doc":"Constrói a página inteira (HTML, estilos e o guião do carrossel, tudo\ninline) e devolve-a como Response com uma hora de cache — a página muda\nquando se publica, não por pedido."}]},{"nome":"worker/src/salvaguarda.js","texto":"Cópia da base de dados para fora da base de dados.\n\nO Time Travel da D1 repõe a base num instante do passado, mas no plano\ngratuito só guarda 7 dias — e vive dentro da própria base: não serve de\nnada se a base for apagada, se a conta se perder, ou se um erro só der\npela falta de dados duas semanas depois. Daí uma cópia diária no R2, que é\noutro serviço, com outro ciclo de vida.\n\nFormato: NDJSON comprimido. Uma linha por registo, `{\"t\":tabela,\"r\":{...}}`,\nprecedida de um cabeçalho com a data e as tabelas incluídas. É um formato\nque se lê com o olho e se restaura com um ciclo — ver scripts/restaurar.js.","funcoes":[{"nome":"aPodar","assinatura":"function aPodar(chaves, agora, dias DIAS, meses = MESES)","doc":"Que cópias já não são precisas. Mantém-se as dos últimos DIAS dias e, para\ntrás disso, só a do dia 1 de cada mês durante MESES meses. Função pura de\npropósito: a decisão de apagar é a que mais interessa poder testar."},{"nome":"tabelasDaBase","assinatura":"async function tabelasDaBase(env)","doc":"As tabelas da base, descobertas em vez de escritas à mão: uma tabela nova\nnuma migração passa a ser copiada sem ninguém se lembrar dela."},{"nome":"fluxo","assinatura":"function fluxo(env, tabelas, conta)","doc":"Lê a base por páginas e vai entregando linhas NDJSON. Nunca tem a base\ntoda em memória — o worker tem 128 MB e a base pode ir até 500."},{"nome":"copiar","assinatura":"async function copiar(env)","doc":"Faz a cópia do dia e poda as que já não são precisas. Devolve o que\naconteceu, para o resumo diário poder dizer se correu bem."},{"nome":"podar","assinatura":"async function podar(env, agora now()","doc":"Apaga do R2 as cópias que o aPodar marcar e devolve quantas foram."},{"nome":"listar","assinatura":"async function listar(env)","doc":"Todas as cópias no R2, como {key, size, uploaded}, da mais recente para a\nmais antiga. Segue a paginação até ao fim: é sobre esta lista que se poda."},{"nome":"estado","assinatura":"async function estado(env)","doc":"Resumo para o canal de administração: uma cópia que deixou de acontecer só\nse dá por falta quando é precisa, por isso é preciso dizê-lo todos os dias."},{"nome":"kb","assinatura":"function kb(n)","doc":"Bytes em texto de gente: \"512 KB\", \"3,2 MB\" — com a vírgula portuguesa."}]},{"nome":"worker/src/lib/http.js","texto":"Peças de HTTP partilhadas por todas as rotas: respostas, leitura do corpo,\nvalidação de identificadores e os limites de tamanho.","funcoes":[{"nome":"json","assinatura":"function json(data, status 200, headers = {})","doc":"Uma Response JSON com o charset certo; headers extra somam-se aos nossos."},{"nome":"err","assinatura":"function err(status, message)","doc":"O erro no formato que a app espera: { error: mensagem }, com o status dado."},{"nome":"body","assinatura":"async function body(request)","doc":"O corpo do pedido como objeto, ou null quando não é JSON ou passa de\nMAX_BODY — quem chama trata o null como pedido inválido, sem try/catch."},{"nome":"cleanData","assinatura":"function cleanData(data, id)","doc":"O corpo de um registo tem de ser um objeto simples, sem tentativas de\npoluir o protótipo, e o seu id nunca pode contradizer o id da linha."},{"nome":"weakPassword","assinatura":"function weakPassword(p)","doc":"forte: 8+ caracteres com maiúsculas, minúsculas, números e um símbolo"}]},{"nome":"worker/src/lib/auditoria.js","texto":"Rasto do que a equipa faz e do que as máquinas fazem.\n\nDuas tabelas, duas perguntas:\n\naudit_log — quem fez o quê sobre quem, e porquê. Escreve-se em cada ação\ndo back office e nunca se altera nem se apaga: no primeiro desentendimento\nsobre \"quem mudou isto?\", ou o registo existe ou já não se reconstrói.\n\nop_log — as operações agendadas deixam uma linha por execução. O alarme\nnão é uma linha com erro: é a ausência de linhas novas, que era o que\nninguém via quando o cron morria de todo.","funcoes":[{"nome":"auditar","assinatura":"async function auditar(env, eu, acao, alvo, detalhe)","doc":"Nunca lança: a auditoria não pode ser o motivo de uma ação falhar. Mas\ntambém não engole em silêncio — devolve se escreveu, e quem chama uma\nação sensível pode recusar-se a agir sem rasto."},{"nome":"registarOp","assinatura":"async function registarOp(env, op, ok, detalhe)","doc":"Uma linha por execução de uma operação agendada (ou manual). A poda dos\nregistos velhos vai de caminho: 90 dias chegam para ver tendências, e uma\ntabela de batimentos não pode crescer para sempre."}]},{"nome":"web/sw.js","texto":"Service worker: a app abre offline (a API sincroniza quando voltar a rede).","funcoes":[]},{"nome":"scripts/gerar-docs.js","texto":"A documentação sai do próprio código.\n\nPara quem chega de novo ao projeto: cada ficheiro abre com um comentário\nque explica o que é, e as funções têm o seu comentário por cima. Este\nguião junta tudo por FUNCIONALIDADE (não por pasta): o cabeçalho de cada\nficheiro, a assinatura de cada função com a documentação adjacente, os\ncomandos do Discord com quem os pode correr, e as armadilhas conhecidas\n(docs/armadilhas.md). Escreve worker/src/docs-gerados.js, que o worker\nserve em /equipa/docs — com gaveta de navegação e pesquisa.\n\nCorre no deploy (a página nunca fica atrás do código) e o resultado vai\nno repositório, para o wrangler local e os testes terem sempre o módulo.\n\nnode scripts/gerar-docs.js","funcoes":[{"nome":"ler","assinatura":"ler (p)","doc":"lê um ficheiro do repositório (caminho relativo à raiz) como UTF-8"},{"nome":"limpa","assinatura":"function limpa(texto)","doc":"tira a decoração dos banners ( TÍTULO ) e a sintaxe de comentário"},{"nome":"cabecalho","assinatura":"function cabecalho(src)","doc":"o comentário de abertura de um ficheiro (bloco /* */ ou série de //)"},{"nome":"funcoesDe","assinatura":"function funcoesDe(src)","doc":"percorre o ficheiro linha a linha e devolve [{nome, assinatura, doc}] por cada\nfunção de topo que case com uma das FORMAS; doc é o comentário adjacente acima"},{"nome":"ficheiro","assinatura":"function ficheiro(caminho)","doc":"tudo o que os docs mostram de um ficheiro: o caminho, o cabeçalho e as funções"},{"nome":"comandosDoDiscord","assinatura":"function comandosDoDiscord()","doc":"Os comandos do bot, lidos do registo (entradas de topo, dois espaços de\nindentação — se a formatação mudar, o teste dos docs rebenta e avisa)."},{"nome":"permissoes","assinatura":"function permissoes()","doc":"o mapa PERMISSOES de worker/src/discord.js, lido do próprio código: comando → papéis que o podem correr"},{"nome":"armadilhas","assinatura":"function armadilhas()","doc":"as armadilhas: um markdown mantido à mão, secções por «## »"},{"nome":"todosOsFicheiros","assinatura":"function todosOsFicheiros()","doc":"varre as pastas de código e devolve todos os .js (menos o gerado),\npara se saber o que ainda não está arrumado no MAPA"}]},{"nome":"scripts/make-icons.js","texto":"Gera os ícones da PWA, iguais aos do APK, sem dependências.\n\nnode scripts/make-icons.js\n\nO desenho é o mesmo que o Android usa em res/drawable/ic_launcher_*.xml:\num gradiente diagonal verde e a casa a traço branco, a mesma do menu\nlateral. Antes a PWA tinha uma casa cheia sobre verde liso — parecia outra\napp no ecrã inicial de quem tinha as duas.\n\nSe algum dia mexeres no ícone do Android, mexe aqui também: são dois\ndesenhos separados que têm de dizer a mesma coisa.","funcoes":[{"nome":"crc32","assinatura":"function crc32(buf)","doc":"CRC-32 de um chunk do PNG, com a tabela calculada uma vez e guardada na própria função."},{"nome":"chunk","assinatura":"function chunk(type, data)","doc":"Um chunk PNG completo: comprimento, tipo, dados e CRC — o formato exige os quatro."},{"nome":"png","assinatura":"function png(width, height, rgba)","doc":"Embrulha os pixels RGBA num PNG válido (assinatura, IHDR, IDAT comprimido, IEND)\ne devolve o Buffer pronto a escrever em disco."},{"nome":"distSegmento","assinatura":"function distSegmento(px, py, ax, ay, bx, by)","doc":"Distância de um ponto a um segmento — é o que dá o traço com pontas\nredondas sem ter de desenhar círculos nas juntas."},{"nome":"distCasa","assinatura":"function distCasa(x, y)","doc":"A distância de um ponto ao traço mais próximo da casa, nas coordenadas do vetor de 48."},{"nome":"makeIcon","assinatura":"function makeIcon(size)","doc":"Desenha o ícone pixel a pixel: o gradiente diagonal de fundo e a casa a traço\nbranco, com 3×3 amostras por pixel para o contorno não sair serrado.\nDevolve o PNG como Buffer, no tamanho pedido."}]},{"nome":"scripts/restaurar.js","texto":"Lê uma cópia do R2 e escreve o SQL que a repõe.\n\n# tirar a cópia do R2\nnpx wrangler r2 object get gestor-imobiliario/copias/2026-09-01.ndjson.gz \\\n--file copia.ndjson.gz\n\n# ver o que lá está, sem escrever nada\nnode scripts/restaurar.js copia.ndjson.gz --resumo\n\n# gerar o SQL e aplicá-lo\nnode scripts/restaurar.js copia.ndjson.gz > repor.sql\nnpx wrangler d1 execute gestor-imobiliario --remote --file repor.sql\n\nPor omissão o SQL só acrescenta o que falta (INSERT OR IGNORE), que é o que\nse quer depois de perder registos. Com --substituir, cada linha da cópia\npassa a mandar sobre a que está na base (INSERT OR REPLACE) — é para repor\num estado inteiro, e apaga alterações feitas depois da cópia.\n\nTestar primeiro na base de dev:\nnpx wrangler d1 execute gestor-imobiliario-dev --remote --file repor.sql","funcoes":[{"nome":"cita","assinatura":"cita (v)","doc":"Um valor de coluna como literal SQL: NULL, número tal e qual, 0/1 para\nbooleanos, X'...' para blobs e texto entre plicas com as plicas dobradas."}]},{"nome":"scripts/versao.js","texto":"Escreve web/versao.json a partir de web/avisos.js.\n\nnode scripts/versao.js          gera o ficheiro\nnode scripts/versao.js --check  confirma que está em dia (para o CI)\n\nO ficheiro é o que a app vai buscar para saber se está atrasada. Tem de\nsair de avisos.js e não ser escrito à mão: uma versão que não bate certo\ncom as novidades faria a app recarregar-se em ciclo.","funcoes":[]}]},{"id":"migracoes","titulo":"Migrações da base","itens":[{"nome":"migrations/0001_init.sql","texto":"Esquema inicial: utilizadores, conexões entre utilizadores, partilha de casas\ne armazenamento dos dados da app (casas + registos por casa + dados globais\ndo utilizador). Os dados de domínio guardam-se como JSON por registo — o\nworker valida a propriedade/partilha e o cliente mantém a lógica de negócio.\nConexão entre dois utilizadores. Criada quando um utilizador adiciona o id\ndo outro; fica 'pending' até o outro aceitar.\nCasas que cada utilizador escolheu partilhar numa conexão concreta.\nRegistos ligados a uma casa (inquilinos, contratos, movimentos, despesas...).\nDados do utilizador não ligados a nenhuma casa (definições, categorias...).","funcoes":[]},{"nome":"migrations/0002_share_proposals.sql","texto":"Propostas de divisão de percentagens de uma casa partilhada.\nUma proposta por casa; entra em vigor quando todos os comproprietários\n(dono + utilizadores com quem a casa está partilhada) a aprovarem.","funcoes":[]},{"nome":"migrations/0003_oauth.sql","texto":"Entrada com Google / Apple: liga a conta ao \"sub\" do fornecedor.\nContas criadas por OAuth ficam com pass_hash/pass_salt vazios.","funcoes":[]},{"nome":"migrations/0004_account_deletion.sql","texto":"Eliminação de conta ao estilo do Reddit: a linha do utilizador fica como\nlápide anónima (\"[deleted]\") para que as referências noutros dados — quem\npagou um movimento numa casa partilhada, por exemplo — continuem legíveis\nsem revelar quem era. Todos os dados próprios são apagados.","funcoes":[]},{"nome":"migrations/0005_session_epoch.sql","texto":"Permite invalidar todas as sessões de um utilizador de uma vez: cada sessão\nguarda a \"época\" em que nasceu e deixa de valer quando a época do utilizador\navança (mudança de palavra-passe ou \"terminar sessão nos outros aparelhos\").","funcoes":[]},{"nome":"migrations/0006_terms_and_limits.sql","texto":"Aceitação dos termos (guardada por versão, para se poder pedir de novo\nquando mudarem) e plano de subscrição da conta.\nContadores de limite de utilização. Estavam em KV, que no plano gratuito\nsó permite mil escritas por dia — cada gravação de dados gastava uma.\nAqui cabem cem vezes mais.","funcoes":[]},{"nome":"migrations/0007_tickets_reports.sql","texto":"Pedidos de ajuda e sugestões dos utilizadores, e relatórios automáticos de\r\nerros. Ambos alimentam o canal de dev no Discord.","funcoes":[]},{"nome":"migrations/0008_files_and_categories.sql","texto":"Anexos no R2: a tabela guarda quem carregou e a que casa pertence, que é\r\no que decide quem os pode ver. O conteúdo vive no bucket, com o id à chave.\r\nTudo o que precisa de atenção passa a ser um pedido, com categoria:\r\n  user      · contado por uma pessoa (problema ou sugestão)\r\n  client    · erro apanhado no browser\r\n  server    · erro apanhado no worker\r\n  infra     · limites e infraestrutura (quotas, cron, deploys)\r\n  seguranca · tentativas de abuso e eventos de segurança\r\nErros já registados passam a pedidos, para não se perder o histórico.","funcoes":[]},{"nome":"migrations/0009_contexto_dos_erros.sql","texto":"Contexto dos erros, para se poder decidir o que corrigir primeiro.\r\n\r\nAté agora um erro repetido só somava no contador `n`. Duzentas ocorrências\r\nda mesma pessoa e duzentas de duzentas pessoas contavam igual — e são\r\nproblemas de gravidade muito diferente.\r\nQuem apanhou cada erro. Uma linha por pessoa e por assinatura: o índice\r\núnico faz com que a mesma pessoa a repetir o mesmo erro não conte duas\r\nvezes, e é o que permite responder a \"quantas pessoas?\".\r\nEm que versão da app aconteceu. Sem isto, um relato de quem ainda não\r\natualizou parece um bug da versão em vigor.","funcoes":[]},{"nome":"migrations/0010_ligacoes_de_equipa.sql","texto":"Ligações de uso único para a ferramenta de equipa.\r\n\r\nEstavam no KV, e foi o sítio errado. O KV só fica consistente entre\r\nregiões ao fim de algum tempo: a ligação era escrita no ponto de presença\r\nque atende o Discord e lida no de quem clica, que quase nunca é o mesmo.\r\nUma ligação acabada de criar aparecia como inexistente, e o erro que se\r\nvia era \"já foi usada ou expirou\" — que era falso nas duas metades.\r\n\r\nNa base a leitura vê sempre a escrita. E o uso único passa a fazer-se numa\r\nsó instrução (UPDATE ... WHERE used_at IS NULL), em vez de ler-e-depois-\r\napagar: se dois pedidos chegarem ao mesmo tempo, só um altera a linha.","funcoes":[]},{"nome":"migrations/0011_back_office.sql","texto":"O portal de equipa vira back office: ganha poderes de escrita sobre contas\r\ne pedidos. Tudo o que escreve passa a deixar rasto — a auditoria vem na\r\nmesma migração que os poderes, de propósito: não há um dia em que um\r\nexistiu sem a outra.\r\nQuem fez o quê, sobre quem, e porquê. Só se escreve e lê: não há UPDATE\r\nnem DELETE em lado nenhum do código, e é copiada para o R2 com o resto.\r\nO fio de um pedido. Até aqui um pedido tinha UMA resposta (a coluna reply):\r\nresponder segunda vez apagava a primeira e a pessoa perdia a conversa.\r\nA coluna reply fica — a app do utilizador lê-a — mas passa a ser só a\r\núltima resposta; o fio inteiro vive aqui, com as notas internas que a\r\npessoa nunca vê.\r\nQuem está a tratar de um pedido, para dois não responderem ao mesmo sem\r\nsaberem um do outro.\r\nConta suspensa: não entra, nada se apaga. É o estado que faltava entre\r\nativa e apagada — apagar é irreversível e o suporte não tinha travão\r\nnenhum para uma conta abusiva ou comprometida.\r\nRespostas-tipo para as perguntas que se repetem.\r\nBatimento das operações agendadas e histórico das cópias. Se o cron morrer\r\nde todo, nada dava por isso — o único sinal era o resumo diário não\r\naparecer no Discord. Cada execução deixa aqui uma linha, e a ausência de\r\nlinhas novas é o alarme.","funcoes":[]},{"nome":"migrations/0012_dono_das_contas_de_teste.sql","texto":"Cada conta de teste sabe que dev a criou: e o que permite ao seletor do\r\nambiente de dev mostrar a cada um so as suas, e ao /test lavar so as de\r\nquem pediu. NULL para toda a gente normal - a coluna nao muda nada fora\r\ndo ambiente de teste.","funcoes":[]}]},{"id":"armadilhas","titulo":"Armadilhas conhecidas","itens":[{"nome":"docs/armadilhas.md","texto":"Coisas que já morderam alguém neste projeto. Cada uma custou uma tarde; ler isto custa cinco minutos.","funcoes":[{"nome":"O guião do /equipa vive num template literal","assinatura":"","doc":"Todo o JavaScript do back office (equipa-vista.js) é TEXTO dentro de um\r\ntemplate literal do servidor. Um `\\n` simples numa string é cozido pelo\r\nservidor num newline real dentro do guião servido — SyntaxError no browser\r\ne a página inteira morta em «A carregar…». Escreve `\\\\n` e `\\\\'`, como o\r\nresto do ficheiro. Há um teste (equipa-guiao.test.js) que faz parse do\r\nguião gerado por papel — se rebentar aí, foi isto."},{"nome":"node:sqlite não aceita ?1 repetido","assinatura":"","doc":"A D1 aceita parâmetros numerados (`?1` usado duas vezes); o node:sqlite\r\ndos testes não — dá «column index out of range». O duplo de teste\r\n(testes/lib/bd.js) traduz automaticamente, mas se vires esse erro num\r\nteste novo, é quase de certeza SQL com parâmetros numerados a passar por\r\num caminho que não traduz."},{"nome":"Os assets respondem antes do worker","assinatura":"","doc":"Por omissão, um pedido que bata num ficheiro estático (ex.: `/` →\r\nindex.html) é servido SEM o worker correr. O host-branching (landing no\r\napex, app no resto) só funciona porque `run_worker_first = [\"/\"]` está no\r\nwrangler.toml. Se adicionares outra rota que colida com um ficheiro\r\nestático, tens de a acrescentar lá."},{"nome":"Definir routes desliga o workers.dev","assinatura":"","doc":"`custom_domain = true` no wrangler.toml desativa o endereço workers.dev\r\npor omissão — e as instalações antigas vivem lá. O `workers_dev = true`\r\nexplícito é obrigatório e não pode sair."},{"nome":"Os secrets só chegam ao worker num deploy","assinatura":"","doc":"Mudar um secret no GitHub não muda nada no worker: é o passo «Publicar\r\nsegredos» do deploy que os grava. Depois de corrigir um secret, corre o\r\ndeploy do ambiente certo — senão o worker continua com o valor antigo\r\n(foi assim que a validação do endpoint do Discord «falhou» com a chave\r\ncerta no GitHub e a errada no worker)."},{"nome":"Cada token do Cloudflare no seu sítio","assinatura":"","doc":"O token de deploy (conta inteira: workers, D1, KV, R2, DNS) vive só no\r\nGitHub Actions e NUNCA entra no runtime de um worker. O worker recebe\r\ntokens dedicados e mínimos (CF_EMAIL_TOKEN para o Email Routing,\r\nCF_ANALYTICS_TOKEN só de leitura). Já houve um fallback que publicava o\r\ntoken de deploy no worker — não voltar a isso."},{"nome":"Bots separados, chave partilhada","assinatura":"","doc":"Produção e dev têm aplicações Discord distintas (o endpoint das\r\ninterações é da aplicação, não do servidor), logo tokens de bot\r\ndiferentes. As ligações do /test são assinadas com a TESTE_CHAVE — a\r\nmesma nos dois ambientes — precisamente porque o token do bot deixou de\r\nser partilhado. No ambiente de dev, qualquer secret `<NOME>_DEV` tem\r\nprecedência sobre o partilhado."},{"nome":"Objetos indexados por input do utilizador","assinatura":"","doc":"`ACOES[acao]` com `acao = 'constructor'` devolve uma função herdada — e\r\nchamada com `(env, …)` já devolveu o env inteiro, segredos incluídos.\r\nUsa sempre `Object.prototype.hasOwnProperty.call(mapa, chave)` antes de\r\nindexar com o que vem de fora."},{"nome":"O correio tem regras próprias","assinatura":"","doc":"`enviarEmail` é um no-op sem RESEND_API_KEY (a app funciona na mesma);\r\nfora de produção o assunto leva o prefixo do ambiente; e um destinatário\r\n`@teste.rendorium.com` é redirecionado — para o email do dev que criou a\r\nconta (registado via /test email:…) ou para test@rendorium.com. Nunca\r\nassumas que o destinatário final é o que passaste."},{"nome":"Mudar o legal.js implica subir a versão","assinatura":"","doc":"Qualquer alteração de substância aos termos ou à privacidade exige subir\r\n`VERSION` no web/legal.js E `TERMS_VERSION` no worker/src/lib/http.js\r\n(iguais). É isso que faz a app pedir nova aceitação a toda a gente — o\r\nmecanismo prometido na secção de alterações dos próprios termos."},{"nome":"Patches em ficheiros com UTF-8 no Windows","assinatura":"","doc":"Aplicar edições por heredoc bash corrompe acentos e emoji. Os patches\r\nescrevem-se num ficheiro .py (UTF-8) e corre-se esse ficheiro — nunca\r\ncódigo com texto acentuado por stdin."}]}]}]};
